# Single shared definitions — duplicating these here would fork behavior in
# the single-file build, where the later copy silently shadows the earlier
# one (build_vnflight.py now fails on duplicate top-level names).
# (intra-package import stripped by build)
pass


# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

DEFAULT_BRIDGE_URL = "http://127.0.0.1:8385"
DEFAULT_BRIDGE_PORT = 8385
STATE_FILENAME = ".vnflight_state.json"
CONFIG_FILENAME = "vnflight.json"
# How long launch_game waits for a freshly spawned bridge to answer. The
# 1.6 MB single-file artifact imports in 4-5 s idle and slower under load;
# the MCP launch handler reserves this plus its setup phase out of the
# transport budget so a slow start is never killed before its receipt.
BRIDGE_READINESS_TIMEOUT_S = 25.0
# Launch-file handshake: written into the game's game/ directory at launch
# so launcher-mediated games (steam://, goggalaxy://) — which do NOT inherit
# the vnflight launcher's environment — still learn the bridge URL, slot
# token, and save slot for THIS launch.  The shim reads it at init.
LAUNCH_FILE_NAME = "vnflight_launch.json"
LAUNCH_RECEIPT_PREFIX = "vnflight_registration_"
# Claim protocol (see ``_write_launch_file``).  A game needs several seconds
# to boot far enough to read the launch file; two launches of the SAME game
# started close together would otherwise both read whichever file won the
# race.  The shim stamps ``claimed_by`` once it has adopted a file, and the
# writer waits for that stamp before overwriting.
LAUNCH_CLAIM_WAIT = 45.0  # seconds to wait for the previous launch's claim
LAUNCH_CLAIM_POLL = 0.5  # seconds between re-reads while waiting
LAUNCH_CLAIM_FRESH_HORIZON = 120.0  # older/farther-future files never block
# Writer-vs-writer serialization (see ``_write_launch_file``).  The claim
# protocol above serializes a writer against a BOOTING GAME; these serialize
# two WRITERS — two threads of the (threaded) hub, or two processes.
LAUNCH_LOCK_SUFFIX = ".lock"  # sits next to the launch file
LAUNCH_LOCK_POLL = 0.1  # seconds between non-blocking OS-lock retries
# A contender may have arrived behind a writer doing the full claim wait.
# Keep acquisition bounded so an unexpected filesystem-lock failure cannot
# wedge launches forever; timeout degrades to the existing explicit warning.
LAUNCH_LOCK_ACQUIRE_WAIT = LAUNCH_CLAIM_WAIT + 20.0

IS_WINDOWS = platform.system() == "Windows"

if IS_WINDOWS:
    try:
        import winreg
    except ImportError:
        winreg = None
else:
    winreg = None

# Keep references to log file handles so they aren't garbage-collected
# while the child process is still writing to them.
_launch_log_handles: List[Any] = []


def _coerce_expected_setting_value(old_value: Any, requested: Any) -> Any:
    """Mirror the shim's receipt-producing setting coercion."""
    if isinstance(old_value, bool):
        if isinstance(requested, bool):
            return requested
        return str(requested).lower() in {"true", "1", "yes"}
    if isinstance(old_value, int) and not isinstance(old_value, bool):
        return int(requested)
    if isinstance(old_value, float):
        return float(requested)
    return requested


def _validated_setting_application_receipt(
    applied: Any,
    expected_changes: Dict[str, Any],
) -> Tuple[Optional[List[dict]], Optional[str]]:
    """Validate a successful batch-set receipt before describing its result.

    The shim returns one complete row per submitted key. Missing, duplicate,
    partial, or malformed rows cannot prove that a profile was already in
    effect, even when the surrounding command result says ``success``.
    """
    expected_keys = set(expected_changes)
    if not isinstance(applied, list):
        return None, "the applied receipt is not a list"
    if len(applied) != len(expected_keys):
        return None, (
            "the applied receipt has {} row(s), expected {}".format(
                len(applied), len(expected_keys))
        )
    seen = set()
    for entry in applied:
        if not isinstance(entry, dict):
            return None, "the applied receipt contains a non-object row"
        if not {"key", "old_value", "value"} <= set(entry):
            return None, "the applied receipt contains an incomplete row"
        key = entry.get("key")
        if key not in expected_keys:
            return None, "the applied receipt contains an unexpected key"
        if key in seen:
            return None, "the applied receipt contains a duplicate key"
        try:
            expected_value = _coerce_expected_setting_value(
                entry.get("old_value"), expected_changes[key])
        except (TypeError, ValueError):
            return None, "the submitted value cannot match the live setting type"
        if entry.get("value") != expected_value:
            return None, "the applied receipt contains an unexpected value"
        seen.add(key)
    if seen != expected_keys:
        return None, "the applied receipt omits a submitted key"
    return applied, None


# ---------------------------------------------------------------------------
# HTTP helper (for admin endpoints not covered by BridgeClient)
# ---------------------------------------------------------------------------


def _http_request(
    method: str,
    url: str,
    data: Optional[dict] = None,
    timeout: float = 5.0,
) -> Tuple[int, Any]:
    """
    Perform an HTTP request.  Returns (status_code, parsed_json_or_None).
    """
    headers = {"Content-Type": "application/json"}
    body = None
    if data is not None:
        body = json.dumps(data, ensure_ascii=False).encode("utf-8")
    try:
        req = urllib.request.Request(url, data=body, headers=headers, method=method)
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8")
            try:
                return resp.status, json.loads(raw)
            except json.JSONDecodeError:
                return resp.status, {"_raw": raw}
    except urllib.error.HTTPError as exc:
        try:
            err_body = exc.read().decode("utf-8")
            return exc.code, json.loads(err_body)
        except Exception:
            return exc.code, {"error": str(exc)}
    except urllib.error.URLError as exc:
        return 0, {"error": f"Connection failed: {exc.reason}"}
    except Exception as exc:
        return 0, {"error": str(exc)}


def _slot_free_detail(data: Any) -> str:
    if isinstance(data, dict):
        detail = data.get("message") or data.get("error") or data.get("_raw")
        if detail:
            return str(detail)
    return "slot free request failed"


def _slot_free_already_gone(data: Any) -> bool:
    if not isinstance(data, dict):
        return False
    code = str(
        data.get("error_code")
        or data.get("code")
        or data.get("reason")
        or ""
    ).lower()
    if code in {"slot_not_found", "no_slot_to_free", "already_freed"}:
        return True
    text = str(data.get("message") or data.get("error") or data.get("_raw") or "")
    lowered = text.lower()
    return "no slot" in lowered and "to free" in lowered


def _expected_shim_game_id(
    game: Optional[dict], fallback_game_id: str,
) -> str:
    """Return the game_id the shim will self-report for this launch.

    The shim derives its own identity from its install directory's
    basename (see vnflight.rpy: ``os.path.basename(os.path.dirname(
    renpy.config.gamedir))``), NOT from the vnflight.json config key that
    was used to launch it.  Ordinarily those coincide -- the game_dir IS
    the config id.  But a config entry can explicitly alias a physical
    game directory shared with another entry -- e.g. testing the same
    game under a different Ren'Py SDK ("echoes_of_tomorrow_r7" with
    ``"game_dir": "echoes_of_tomorrow"``) -- in which case the shim
    reports "echoes_of_tomorrow" while the launch used the suffixed
    config id.  Slot-matching during the connect wait must compare
    against THIS derived id, or a slot that legitimately belongs to the
    launch never matches and the wait times out even though the game is
    running fine.

    Deliberately keyed off the config's own ``game_dir`` field rather
    than the resolved install path: a Steam/GOG install path's directory
    name need not match the game's vnflight.json id at all (registry
    lookups, launcher-owned folder names), and conflating "install path
    basename differs from the id" with "this is a shim-id alias" would
    misfire launch matching for any launcher-mediated game.
    """
    game_dir = (game or {}).get("game_dir")
    if game_dir:
        name = Path(str(game_dir)).name
        if name:
            return name.lower().replace(" ", "_")
    return fallback_game_id


def _same_game_slot_pids(slots: list[dict], game_id: str) -> set[int]:
    pids: set[int] = set()
    for slot in slots:
        if not _game_ids_match(slot.get("game_id"), game_id):
            continue
        pid = slot.get("game_pid")
        try:
            if pid:
                pids.add(int(pid))
        except (TypeError, ValueError):
            continue
    return pids


def _free_existing_game_slot(
    session: Any,
    game_id: str,
    existing_slots: list[dict] | None = None,
    client_state: Any = None,
    bridge_url: Optional[str] = None,
    match_id: Optional[str] = None,
) -> Tuple[bool, str]:
    """Free existing same-game slots before replacement launch.

    *match_id*, when given, is the id actually compared against each slot's
    reported ``game_id`` (see ``_expected_shim_game_id``); *game_id* still
    names the launch in error/log text so messages stay in terms of what the
    caller typed.

    Returns (ok, error).  Failing closed is safer than launching into a stale
    slot and letting later commands operate on old pending state.
    """
    target_id = match_id if match_id is not None else game_id
    if existing_slots is None:
        existing_slots = session.list_slots()
    if existing_slots is None:
        return False, (
            "Could not list bridge slots before launching. "
            "Restart the bridge/MCP session before launching."
        )
    collisions = _normalized_game_id_collision(existing_slots, target_id)
    if collisions:
        return False, (
            f"Ambiguous normalized game id for '{game_id}': "
            f"{', '.join(sorted(collisions))}. "
            "Use a slot id or resolve the bridge slot collision before launching."
        )
    for slot in existing_slots:
        if not _game_ids_match(slot.get("game_id"), target_id):
            continue
        slot_id = slot.get("slot_id")
        ok, data = session.free_slot(slot_id)
        if not ok and _slot_free_already_gone(data):
            ok = True
        if not ok:
            detail = _slot_free_detail(data)
            detail_suffix = "" if detail.endswith((".", "!", "?")) else "."
            return False, (
                f"Existing slot {slot_id} for '{game_id}' could not be freed: "
                f"{detail}{detail_suffix} "
                "Restart the bridge/MCP session before launching."
            )
        if client_state is not None and bridge_url:
            remove_token = getattr(client_state, "remove_slot_token", None)
            if callable(remove_token):
                try:
                    remove_token(
                        bridge_url, slot_id,
                        reservation_id=slot.get("reservation_id"),
                    )
                except TypeError:
                    remove_token(bridge_url, slot_id)
                client_state.save()
    return True, ""


# ---------------------------------------------------------------------------
# State persistence
# ---------------------------------------------------------------------------


def user_data_dir() -> Path:
    """Per-user vnflight data directory (state, fallback logs).

    Runtime state must not live inside the package directory: for pip
    installs that is site-packages, which may be read-only and is wiped
    on reinstall.  Override with VNFLIGHT_DATA_DIR.
    """
    env = os.environ.get("VNFLIGHT_DATA_DIR")
    if env:
        return Path(env)
    system = platform.system()
    if system == "Windows":
        base = os.environ.get("LOCALAPPDATA")
        base_path = Path(base) if base else Path.home() / "AppData" / "Local"
        return base_path / "vnflight"
    if system == "Darwin":
        return Path.home() / "Library" / "Application Support" / "vnflight"
    base = os.environ.get("XDG_DATA_HOME")
    base_path = Path(base) if base else Path.home() / ".local" / "share"
    return base_path / "vnflight"


def _package_dir() -> Path:
    """Directory of this module — the legacy runtime-state location."""
    return Path(__file__).resolve().parent


def _single_file_artifact() -> Optional[Path]:
    """Path of the running single-file vnflight build, or None (package).

    In the package checkout this code runs as ``vnflight.lib``; in the
    built artifact every module body shares the artifact's globals, so
    ``__package__`` is empty and ``__file__`` is the artifact itself —
    a script that hosts the full CLI (subcommands, bridge, MCP).
    Deployment-aware subprocess spawns (CLI re-invocation, owned bridge)
    must use this file directly: there is no importable ``vnflight``
    package to ``-m`` into in a flat single-file deployment.
    """
    if (__package__ or "").startswith("vnflight"):
        return None
    try:
        candidate = Path(__file__).resolve()
    except (OSError, ValueError):
        return None
    if candidate.is_file():
        return candidate
    return None


def default_state_dir() -> str:
    """Directory for the persistent CLI state file.

    Prefers the per-user data dir; falls back to the historical
    package-adjacent location only if the data dir cannot be created.
    """
    data_dir = user_data_dir()
    try:
        data_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        return str(_package_dir())
    return str(data_dir)


class ClientState:
    """Persists cursor and session info across CLI invocations."""

    def __init__(
        self,
        state_dir: str,
        disabled: bool = False,
    ):
        self.disabled = disabled
        self.path = os.path.join(state_dir, STATE_FILENAME)
        self.data: dict = {}
        self._pending_mutations: List[Tuple[str, Tuple[str, ...], Any]] = []
        if not disabled:
            self._load()

    def _record_mutation(
        self, operation: str, path: Tuple[str, ...], value: Any = None,
    ) -> None:
        self._pending_mutations.append((operation, path, value))

    def _load(self) -> None:
        try:
            with open(self.path, "r", encoding="utf-8") as f:
                self.data = json.load(f)
            return
        except json.JSONDecodeError:
            self.data = {}
            return
        except FileNotFoundError:
            self.data = {}

    def save(self) -> None:
        if self.disabled:
            return
        target = Path(self.path)
        lock_path = Path(self.path + ".lock")
        thread_lock = _launch_write_lock(target)
        lock_fd: Optional[int] = None
        try:
            target.parent.mkdir(parents=True, exist_ok=True)
            with thread_lock:
                lock_fd, _warning = _acquire_launch_lockfile(
                    lock_path, LAUNCH_LOCK_ACQUIRE_WAIT,
                )
                if lock_fd is None:
                    return
                persisted: dict = {}
                try:
                    with target.open("r", encoding="utf-8") as f:
                        loaded = json.load(f)
                    if isinstance(loaded, dict):
                        persisted = loaded
                except (FileNotFoundError, json.JSONDecodeError, OSError):
                    pass

                if not self._pending_mutations:
                    merged = dict(self.data)
                else:
                    merged = persisted
                    for operation, path, value in self._pending_mutations:
                        if operation == "set_root":
                            merged = dict(value)
                            continue
                        parent = merged
                        for key in path[:-1]:
                            child = parent.get(key)
                            if not isinstance(child, dict):
                                child = {}
                                parent[key] = child
                            parent = child
                        key = path[-1]
                        if operation == "set":
                            parent[key] = value
                        elif operation == "delete":
                            parent.pop(key, None)
                        elif operation == "remove_slot_token":
                            tokens = parent.get(key)
                            if isinstance(tokens, dict):
                                slot_key = str(value.get("slot_key"))
                                expected_id = value.get("reservation_id")
                                candidate = tokens.get(slot_key)
                                if (
                                    candidate is not None
                                    and expected_id is not None
                                    and hashlib.sha256(
                                        str(candidate).encode("utf-8")
                                    ).hexdigest()[:16] != expected_id
                                ):
                                    continue
                                removed = tokens.pop(slot_key, None)
                                if removed:
                                    for alias, token in list(tokens.items()):
                                        if (
                                            not alias.startswith("slot:")
                                            and token == removed
                                        ):
                                            tokens.pop(alias, None)
                        elif operation == "append_unique":
                            values = parent.setdefault(key, [])
                            if not isinstance(values, list):
                                values = []
                                parent[key] = values
                            if value not in values:
                                values.append(value)
                tmp = target.with_name(
                    target.name
                    + ".tmp-%d-%d" % (os.getpid(), threading.get_ident())
                )
                with tmp.open("w", encoding="utf-8") as f:
                    json.dump(merged, f, indent=2, ensure_ascii=False)
                    f.flush()
                    os.fsync(f.fileno())
                os.replace(str(tmp), str(target))
                self.data = merged
                self._pending_mutations.clear()
        except Exception:
            pass
        finally:
            _release_launch_lockfile(lock_fd, lock_path)

    def get_cursor(self, bridge_url: str) -> int:
        return self.data.get(bridge_url, {}).get("cursor", 0)

    def has_cursor(self, bridge_url: str) -> bool:
        """Distinguish a saved continuation (including zero) from first attach."""
        return "cursor" in self.data.get(bridge_url, {})

    def set_cursor(self, bridge_url: str, cursor: int) -> None:
        if bridge_url not in self.data:
            self.data[bridge_url] = {}
        self.data[bridge_url]["cursor"] = cursor
        self._record_mutation("set", (bridge_url, "cursor"), cursor)

    def get_last_request_id(self, bridge_url: str) -> Optional[str]:
        return self.data.get(bridge_url, {}).get("last_request_id")

    def get_deferred_events(self, bridge_url: str) -> list:
        """Story rows a previous invocation polled past but never showed."""
        events = self.data.get(bridge_url, {}).get("deferred_events")
        return [e for e in events if isinstance(e, dict)] if isinstance(events, list) else []

    def set_deferred_events(self, bridge_url: str, events: list) -> None:
        if bridge_url not in self.data:
            self.data[bridge_url] = {}
        events = [e for e in (events or []) if isinstance(e, dict)]
        self.data[bridge_url]["deferred_events"] = events
        self._record_mutation("set", (bridge_url, "deferred_events"), events)

    def get_delivered_action_events(self, bridge_url: str) -> dict:
        """The client's delivered-action-events ledger from the last
        invocation: ``{"reset_generation": int|None,
        "ownership": [[generation|None, action_id, seq], ...]}``.

        An act's scoped receipt drain delivers the act's story rows and
        records them here without advancing the ordinary cursor; the
        ordinary poll filters by this ledger.  Without it every ``wait``
        after an act re-read the story the act had already printed."""
        payload = self.data.get(bridge_url, {}).get("delivered_action_events")
        if not isinstance(payload, dict):
            return {"reset_generation": None, "ownership": []}
        ownership = payload.get("ownership")
        return {
            "reset_generation": payload.get("reset_generation"),
            "ownership": [
                list(item) for item in (ownership or [])
                if isinstance(item, (list, tuple)) and len(item) == 3
            ],
        }

    def set_delivered_action_events(self, bridge_url: str, payload: dict) -> None:
        if bridge_url not in self.data:
            self.data[bridge_url] = {}
        payload = payload if isinstance(payload, dict) else {}
        clean = {
            "reset_generation": payload.get("reset_generation"),
            "ownership": [
                list(item) for item in (payload.get("ownership") or [])
                if isinstance(item, (list, tuple)) and len(item) == 3
            ],
        }
        self.data[bridge_url]["delivered_action_events"] = clean
        self._record_mutation(
            "set", (bridge_url, "delivered_action_events"), clean,
        )

    def set_last_request_id(self, bridge_url: str, rid: Optional[str]) -> None:
        if bridge_url not in self.data:
            self.data[bridge_url] = {}
        self.data[bridge_url]["last_request_id"] = rid
        self._record_mutation(
            "set", (bridge_url, "last_request_id"), rid,
        )

    def get_pids(self, bridge_url: str) -> dict:
        return self.data.get(bridge_url, {}).get("pids", {})

    def set_pids(self, bridge_url: str, pids: dict) -> None:
        if bridge_url not in self.data:
            self.data[bridge_url] = {}
        self.data[bridge_url]["pids"] = pids
        self._record_mutation("set", (bridge_url, "pids"), dict(pids))

    def get_admin_token(self, bridge_url: str) -> Optional[str]:
        token = self.data.get(bridge_url, {}).get("admin_token")
        return str(token) if token else None

    def set_admin_token(self, bridge_url: str, token: Optional[str]) -> None:
        if bridge_url not in self.data:
            self.data[bridge_url] = {}
        if token:
            self.data[bridge_url]["admin_token"] = token
            self._record_mutation(
                "set", (bridge_url, "admin_token"), token,
            )
        else:
            self.data[bridge_url].pop("admin_token", None)
            self._record_mutation(
                "delete", (bridge_url, "admin_token"),
            )

    def get_slot_token(self, bridge_url: str, game_id: Optional[str] = None) -> Optional[str]:
        """Most useful stored slot token for ``bridge_url``.

        Slot tokens are stored per game_id plus a ``_last`` (most recent
        launch) entry. With no ``game_id``, returns the last-launch token.
        """
        tokens = self.data.get(bridge_url, {}).get("slot_tokens", {})
        token = tokens.get(game_id) if game_id else tokens.get("_last")
        return str(token) if token else None

    def get_slot_tokens(self, bridge_url: str) -> dict:
        return dict(self.data.get(bridge_url, {}).get("slot_tokens", {}))

    def set_slot_token(
        self,
        bridge_url: str,
        game_id: str,
        token: Optional[str],
        slot_id: Optional[int] = None,
    ) -> None:
        if bridge_url not in self.data:
            self.data[bridge_url] = {}
        tokens = self.data[bridge_url].setdefault("slot_tokens", {})
        if token:
            tokens[game_id] = token
            tokens["_last"] = token
            self._record_mutation(
                "set", (bridge_url, "slot_tokens", game_id), token,
            )
            self._record_mutation(
                "set", (bridge_url, "slot_tokens", "_last"), token,
            )
            if slot_id is not None:
                slot_key = "slot:%s" % slot_id
                tokens[slot_key] = token
                self._record_mutation(
                    "set", (bridge_url, "slot_tokens", slot_key), token,
                )
        else:
            tokens.pop(game_id, None)
            self._record_mutation(
                "delete", (bridge_url, "slot_tokens", game_id),
            )

    def remove_slot_token(
        self,
        bridge_url: str,
        slot_id: int | str,
        reservation_id: Optional[str] = None,
    ) -> None:
        tokens = self.data.get(bridge_url, {}).get("slot_tokens", {})
        slot_key = "slot:%s" % slot_id
        removed = tokens.pop(slot_key, None)
        if removed:
            for key, value in list(tokens.items()):
                if not key.startswith("slot:") and value == removed:
                    tokens.pop(key, None)
        self._record_mutation(
            "remove_slot_token",
            (bridge_url, "slot_tokens"),
            {"slot_key": slot_key, "reservation_id": reservation_id},
        )

    def clear_slot_tokens(self, bridge_url: str) -> None:
        if bridge_url in self.data:
            self.data[bridge_url].pop("slot_tokens", None)
        self._record_mutation(
            "delete", (bridge_url, "slot_tokens"),
        )

    def get_launch_files(self, bridge_url: str) -> List[str]:
        return list(self.data.get(bridge_url, {}).get("launch_files", []))

    def add_launch_file(self, bridge_url: str, path: str) -> None:
        if bridge_url not in self.data:
            self.data[bridge_url] = {}
        files = self.data[bridge_url].setdefault("launch_files", [])
        if path not in files:
            files.append(path)
            self._record_mutation(
                "append_unique", (bridge_url, "launch_files"), path,
            )

    def clear_launch_files(self, bridge_url: str) -> None:
        if bridge_url in self.data:
            self.data[bridge_url].pop("launch_files", None)
        self._record_mutation(
            "delete", (bridge_url, "launch_files"),
        )

    def clear(self, bridge_url: Optional[str] = None) -> None:
        if bridge_url:
            self.data.pop(bridge_url, None)
            self._record_mutation("delete", (bridge_url,))
        else:
            self.data.clear()
            self._pending_mutations = [("set_root", tuple(), {})]


def resolve_stored_admin_token(bridge_url: Optional[str]) -> Optional[str]:
    """Admin token this machine persisted for ``bridge_url``, if any.

    Mirrors the CLI's ``_stored_admin_token`` (cli.py): a game launch stores
    the bridge admin token in :class:`ClientState` (keyed by bridge URL) so
    later CLI invocations — and the CLI subprocesses the MCP server spawns —
    can authenticate to a require-token bridge.  The long-lived MCP
    ``BridgeClient`` used for tool calls must resolve it the same way,
    otherwise its own ``launch`` succeeds (the subprocess reads the stored
    token) but its subsequent ``act``/``state``/``screenshot`` calls stay
    tokenless and 403.  The ``VNFLIGHT_TOKEN`` env fallback is left to the
    ``BridgeClient`` constructor.
    """
    if not bridge_url:
        return None
    try:
        state = ClientState(default_state_dir())
        return state.get_admin_token(bridge_url)
    except Exception:
        return None


def resolve_stored_slot_tokens(bridge_url: Optional[str]) -> List[str]:
    """Stored slot tokens for ``bridge_url``, most-recent launch first.

    A launch mints a per-slot token, hands it to the game (env + launch
    file) and persists it here. The bridge accepts it for that slot even
    when the stored ADMIN token is stale (open-mode bridge, or a bridge
    started by the harness with an admin token this machine never knew) —
    which is exactly the case where a client holding only the admin token
    403s on the slot it just launched.
    """
    if not bridge_url:
        return []
    try:
        state = ClientState(default_state_dir())
        tokens = state.get_slot_tokens(bridge_url)
        last = tokens.pop("_last", None)
        ordered = [last] if last else []
        ordered.extend(t for t in tokens.values() if t and t != last)
        return ordered
    except Exception:
        return []


# ---------------------------------------------------------------------------
# File utilities
# ---------------------------------------------------------------------------


def _get_file_hash(path: Path) -> str:
    """Return SHA-256 hash of a file."""
    if not path.exists() or not path.is_file():
        return ""
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            h.update(chunk)
    return h.hexdigest()


# ---------------------------------------------------------------------------
# Game path resolution
# ---------------------------------------------------------------------------


def _find_steam_game_path(app_id: str) -> Optional[Path]:
    """Find installation path for a Steam game by App ID."""
    if IS_WINDOWS and winreg:
        # Check 64-bit and 32-bit registry locations
        paths = [
            rf"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Steam App {app_id}",
            rf"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\Steam App {app_id}",
        ]
        for p in paths:
            try:
                with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, p) as key:
                    val, _ = winreg.QueryValueEx(key, "InstallLocation")
                    if val:
                        return Path(val)
            except Exception:
                continue
    elif platform.system() in ("Linux", "Darwin"):
        # Search for Steam installation
        if platform.system() == "Darwin":
            steam_roots = [Path.home() / "Library" / "Application Support" / "Steam"]
        else:
            steam_roots = [
                Path.home() / ".steam" / "steam",
                Path.home() / ".local" / "share" / "Steam",
                Path.home()
                / ".var"
                / "app"
                / "com.valvesoftware.Steam"
                / ".steam"
                / "steam",  # Flatpak
            ]

        for root in steam_roots:
            if not (root / "steamapps").is_dir():
                continue

            # 1. Check libraries defined in libraryfolders.vdf
            vdf = root / "steamapps" / "libraryfolders.vdf"
            lib_paths = [root]
            if vdf.exists():
                try:
                    content = vdf.read_text(encoding="utf-8")
                    # Extract "path" values using regex
                    lib_paths.extend(
                        [Path(p) for p in re.findall(r'"path"\s+"([^"]+)"', content)]
                    )
                except Exception:
                    pass

            # 2. Look for the manifest in each library
            for lib in lib_paths:
                manifest = lib / "steamapps" / f"appmanifest_{app_id}.acf"
                if manifest.exists():
                    try:
                        m_content = manifest.read_text(encoding="utf-8")
                        m = re.search(r'"installdir"\s+"([^"]+)"', m_content)
                        if m:
                            return lib / "steamapps" / "common" / m.group(1)
                    except Exception:
                        pass
    return None


def _find_gog_game_path(game_id: str) -> Optional[Path]:
    """Find installation path for a GOG game by Game ID."""
    if not IS_WINDOWS or not winreg:
        return None
    paths = [
        rf"SOFTWARE\GOG.com\Games\{game_id}",
        rf"SOFTWARE\WOW6432Node\GOG.com\Games\{game_id}",
    ]
    for p in paths:
        try:
            with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, p) as key:
                val, _ = winreg.QueryValueEx(key, "path")
                if val:
                    return Path(val)
        except Exception:
            continue
    return None


def _find_game_install_path(game_id: str, games_dir: Optional[str]) -> Optional[Path]:
    """Find installation directory for a game."""
    games = discover_games(games_dir)
    game = next((g for g in games if g["id"] == game_id), None)

    if game:
        launch_cmd = game.get("launch_cmd", "")
        # Check for Steam URL
        steam_match = re.search(r"steam://rungameid/(\d+)", launch_cmd)
        if steam_match:
            return _find_steam_game_path(steam_match.group(1))

        # Check for GOG URL
        gog_match = re.search(r"goggalaxy://launchGame/(\d+)", launch_cmd)
        if gog_match:
            return _find_gog_game_path(gog_match.group(1))

    if not game:
        # Not configured: the id may be a game directory itself.
        if Path(game_id).is_dir():
            return Path(game_id).resolve()
        return None

    launch_cmd = game.get("launch_cmd", "")
    game_dir = game.get("game_dir")
    if game_dir:
        p = Path(game_dir)
        if p.exists():
            return p
        root = Path(games_dir) if games_dir else _find_project_root()
        p = root / game_dir
        if p.exists():
            return p
    if not launch_cmd:
        # Check if it's a local subdirectory in the project root
        root = Path(games_dir) if games_dir else _find_project_root()
        local_path = root / game_id
        if local_path.is_dir():
            return local_path
        return None

    # Fallback: try to parse the launch command.  A Ren'Py SDK launch is
    # "<sdk>/renpy.exe <project dir>": the project DIRECTORY is the install
    # path, never the executable's parent (that is the SDK, which has a
    # game/ dir of its own -- an absolute SDK path used to get the shim
    # installed there).  Only an executable-only launch (a packaged game)
    # resolves to the executable's parent.
    parts = _parse_launch_cmd(launch_cmd)
    if parts:
        root = Path(games_dir) if games_dir else _find_project_root()

        def _existing(part: str) -> Optional[Path]:
            # Config-relative only.  The template promises that launch
            # paths are relative to vnflight.json, and launch_game runs the
            # command with the config directory as its cwd, so that is the
            # one place a relative part can mean anything.  Trying the
            # shell's cwd first (as this once did) made `install-shim` run
            # from another checkout write the shim into THAT checkout's
            # game when both had a "../my_game".  An absolute part joins
            # through unchanged (pathlib discards the root on the left).
            p = root / part
            return p if p.exists() else None

        found = [(part, _existing(part)) for part in parts[:3]]
        for _part, p in found:
            if p is not None and p.is_dir():
                return p
        for _part, p in found:
            if p is not None and p.is_file():
                return p.parent

    return None


# ---------------------------------------------------------------------------
# Launch-file handshake
# ---------------------------------------------------------------------------


def _launch_file_game_dir(install_root: Optional[Path]) -> Optional[Path]:
    """Locate the game's ``game/`` directory for the launch file."""
    if not install_root:
        return None
    game_dir = install_root / "game"
    if game_dir.is_dir():
        return game_dir
    if platform.system() == "Darwin":
        # Mirror install-shim's .app bundle probing.
        bundles = (
            [install_root]
            if install_root.suffix == ".app"
            else list(install_root.glob("*.app"))
        )
        for app in bundles:
            for sub in (
                "Contents/Resources/autorun/game",
                "Contents/Resources/game",
            ):
                cand = app / sub
                if cand.is_dir():
                    return cand
    return None


#: The one line ``install-shim --always-on`` rewrites in the INSTALLED copy.
_ALWAYS_ON_FROM = 'self.enabled = os.environ.get("VNFLIGHT_ENABLED") == "1"'
_ALWAYS_ON_TO = "self.enabled = True  # patched by install-shim --always-on"


def _shim_fingerprint(path: Path) -> str:
    """SHA-256 of a shim's text with line endings normalised.

    Not ``_get_file_hash``: raw bytes are the wrong comparison here. The
    installer rewrites the file through ``Path.write_text`` for ``--always-on``
    (which re-terminates every line), and this repo checks out with CRLF
    translation — so a byte hash reports "drifted" for files that are identical
    code. What we care about is whether the game is running the same SOURCE.
    """
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""
    norm = text.replace("\r\n", "\n").replace("\r", "\n")
    return hashlib.sha256(norm.encode("utf-8")).hexdigest()


def _expected_fingerprints(source: Path, always_on: bool) -> set:
    """Fingerprints an installed file may legitimately have.

    ``--always-on`` games (see ``install_shim_flags`` in the config) get one
    line rewritten at install time, so their correct installed shim does NOT
    match the source byte-for-byte. Accept BOTH forms: the installer only
    patches when the pristine line is present, so an unpatched copy is equally
    valid.
    """
    try:
        text = source.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return set()
    norm = text.replace("\r\n", "\n").replace("\r", "\n")
    out = {hashlib.sha256(norm.encode("utf-8")).hexdigest()}
    if always_on and _ALWAYS_ON_FROM in norm:
        patched = norm.replace(_ALWAYS_ON_FROM, _ALWAYS_ON_TO, 1)
        out.add(hashlib.sha256(patched.encode("utf-8")).hexdigest())
    return out


def shim_status(game_id: str, games_dir: Optional[str] = None) -> dict:
    """Compare the shim + mods INSTALLED in a game against the repo copies.

    A game keeps its own copy of ``vnflight.rpy`` (plus per-game mods), so the
    repo can move on while a game silently keeps running an old one. That is not
    hypothetical: on 2026-08-01 Mystic Café was four days behind and every
    ``act(..., wait:true)`` ran to its timeout ceiling while the click still
    landed — the game was missing the very commit that hardened the interaction
    path the wait settles on. Two separate investigations were spent on the
    symptom because nothing compared these files.

    Resolution deliberately mirrors ``cmd_install_shim`` (same config lookup,
    same ``_get_file_hash``) so the check can never disagree with the installer
    about which files belong to a game.

    Returns a dict — never raises, a broken check must not block a launch::

        {"checked": bool,          # False => could not determine (see "reason")
         "ok": bool,               # True  => everything matches
         "reason": str | None,     # why the check could not run
         "stale": [name, ...],     # installed but different from the repo
         "missing": [name, ...],   # configured but absent from the game
         "unchecked": [name, ...],  # configured but its SOURCE is absent here,
                                    # so nothing was compared (never silent)
         "files": [{"name","state","installed","expected"}, ...]}
    """
    result: dict = {"checked": False, "ok": True, "reason": None,
                    "stale": [], "missing": [], "unchecked": [], "files": []}
    try:
        root = Path(games_dir) if games_dir else _find_project_root()
        source_shim = shim_source_path(games_dir)
        if not source_shim.exists():
            result["reason"] = f"source shim not found at {source_shim}"
            return result
        install_root = _find_game_install_path(game_id, games_dir)
        game_dir = _launch_file_game_dir(install_root)
        if not game_dir:
            result["reason"] = f"could not locate the game/ directory for {game_id!r}"
            return result

        wanted: list = [(source_shim, "vnflight.rpy")]
        always_on = False
        config, config_error = _load_config_with_error(games_dir)
        if config_error:
            # Mods unknown — still worth checking the core shim, but say so.
            result["reason"] = f"game config unreadable ({config_error}); mods not checked"
        else:
            game_cfg = ((config or {}).get("games", {}) or {}).get(game_id, {}) or {}
            always_on = "--always-on" in (game_cfg.get("install_shim_flags") or [])
            # One truth for "which adapters belong to this game": the same
            # resolver install-shim uses (explicit list, or the mods-repo
            # manifest).  Hand-edited config: nothing can be assumed to be a
            # string, and a missing source used to crash the launch OUTSIDE
            # this function's guard.  The installer treats every problem as a
            # CONFIG ERROR; here a problem is REPORTED as unchecked, never
            # silently dropped (that would let a partial checkout approve an
            # arbitrary installed copy), and never blocks — see
            # stale_shim_error's fail-open rule.
            resolution = resolve_game_mods(config, game_id, game_cfg, root)
            for entry in resolution.entries:
                if entry["source"].exists():
                    wanted.append((entry["source"], entry["target"]))
                else:
                    # An explicit mod whose source is missing: the installer
                    # treats it as a config error; here it is visible as an
                    # unchecked target, not implied.
                    result["unchecked"].append(entry["target"])
            for problem in resolution.problems:
                result["unchecked"].append(f"<{problem}>")

        for src, name in wanted:
            installed = game_dir / name
            expected = _expected_fingerprints(
                src, always_on=(always_on and name == "vnflight.rpy")
            )
            if not installed.exists():
                result["missing"].append(name)
                result["files"].append({"name": name, "state": "missing",
                                        "installed": None,
                                        "expected": next(iter(expected), "")})
                continue
            got = _shim_fingerprint(installed)
            state = "ok" if got in expected else "stale"
            if state == "stale":
                result["stale"].append(name)
            result["files"].append({"name": name, "state": state,
                                    "installed": got,
                                    "expected": next(iter(expected), "")})
        result["checked"] = True
        result["ok"] = not result["stale"] and not result["missing"]
        if result["unchecked"]:
            note = ("could not verify "
                    + ", ".join(str(x) for x in result["unchecked"])
                    + " — mod source missing, or its config entry is malformed")
            result["reason"] = f"{result['reason']}; {note}" if result["reason"] else note
    except Exception as exc:  # noqa: BLE001 — a broken check must never block a launch
        result["reason"] = f"{type(exc).__name__}: {exc}"
    return result


def _env_enabled(name: str) -> bool:
    """True only for an explicitly affirmative value.

    A bare truthiness test made VNFLIGHT_ALLOW_STALE_SHIM=0 (and =false) DISABLE
    the safety gate — the opposite of what the operator wrote and of what the
    message documents.
    """
    return os.environ.get(name, "").strip().lower() in {"1", "true", "yes", "on"}


#: Set to 1 to launch anyway with a shim that does not match the repo (e.g. you
#: are deliberately testing a modified shim).
ALLOW_STALE_SHIM_ENV = "VNFLIGHT_ALLOW_STALE_SHIM"


def _shim_refusal(st: dict, game_id: str) -> Optional[str]:
    """Format a refusal from an already-computed status, or None to proceed."""
    if not st.get("checked") or st.get("ok"):
        return None
    lines = [f"REFUSED: {game_id} is running a stale shim — the game's copy has "
             f"drifted from the repo."]
    for f in st["files"]:
        if f["state"] == "ok":
            continue
        got = (f["installed"] or "")[:8] or "-"
        exp = (f["expected"] or "")[:8] or "-"
        lines.append(f"    {f['state']:8} {f['name']:24} installed {got}  repo {exp}")
    lines.append(f"  fix:      python vnflight.py install-shim {game_id}")
    lines.append(f"  override: {ALLOW_STALE_SHIM_ENV}=1")
    return chr(10).join(lines)


def _shim_note(st: dict, game_id: str) -> Optional[str]:
    """Format a warning for anything the check could NOT verify, or None.

    Every fail-open path belongs here, not just unchecked mods: a missing
    source shim, an unresolvable game directory and an unreadable config all
    mean "we did not actually confirm this game is current", and each used to
    proceed in complete silence — which is the failure this whole gate exists
    to end.
    """
    if not st.get("checked"):
        reason = st.get("reason") or "reason unknown"
        return (f"WARNING: {game_id} shim NOT verified — {reason}. "
                f"Proceeding; run `python vnflight.py install-shim {game_id}` "
                f"if the game misbehaves.")
    if st.get("unchecked"):
        # str() every item: this formatter runs OUTSIDE shim_status's exception
        # guard, so a stray non-string here would escape as a crashed launch.
        names = ", ".join(str(x) for x in st["unchecked"])
        return (f"WARNING: {game_id} shim check incomplete — "
                f"{names} not compared "
                f"(mod source missing from this checkout/release, or its "
                f"config entry is malformed).")
    if st.get("reason"):
        return f"WARNING: {game_id} shim check incomplete — {st['reason']}."
    return None


def shim_report(
    game_id: str, games_dir: Optional[str] = None
) -> Tuple[Optional[str], Optional[str]]:
    """Return ``(refusal, warning)`` for a game from ONE filesystem scan.

    Launch paths should call this rather than ``stale_shim_error`` +
    ``shim_warning``: those each re-scan, doubling the work and leaving a window
    in which the two answers could disagree about the same launch.

    A refusal means do not start (see ``_shim_refusal``); a warning means
    proceed but say so. Both can be None, and a refusal never comes with a
    warning worth printing on top of it.
    """
    st = shim_status(game_id, games_dir)
    refusal = None if _env_enabled(ALLOW_STALE_SHIM_ENV) else _shim_refusal(st, game_id)
    return refusal, _shim_note(st, game_id)


def stale_shim_error(game_id: str, games_dir: Optional[str] = None) -> Optional[str]:
    """Convenience wrapper: just the refusal. Prefer ``shim_report`` in launch
    paths, which gets the warning from the same scan."""
    return shim_report(game_id, games_dir)[0]


def shim_warning(game_id: str, games_dir: Optional[str] = None) -> Optional[str]:
    """Convenience wrapper: just the warning. See ``shim_report``."""
    return shim_report(game_id, games_dir)[1]


def _launch_file_awaiting_claim(
    target: Path, now: Optional[float] = None
) -> bool:
    """True when *target* holds a FRESH, UNCLAIMED launch file.

    That is the one state in which overwriting is unsafe: some game process
    was handed this file moments ago and has not yet booted far enough to
    read it.  Everything else — absent, unreadable, malformed, already
    claimed, or too old (a launch that never started, or a broken clock) —
    is fair game, because nothing is going to adopt it any more.
    """
    try:
        with open(target, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError):
        return False
    if not isinstance(data, dict):
        return False
    if "claimed_by" in data:
        return False  # a shim already adopted it; that launch is settled
    try:
        written_at = float(data.get("written_at") or 0)
    except (TypeError, ValueError):
        return False
    if written_at <= 0:
        return False
    age = (time.time() if now is None else now) - written_at
    # Symmetric horizon, mirroring the shim's freshness check: a timestamp
    # far in the future is a broken clock, not a live claim window.
    if age > LAUNCH_CLAIM_FRESH_HORIZON or age < -LAUNCH_CLAIM_FRESH_HORIZON:
        return False
    return True


def _launch_receipt_path(launch_file_path: str | Path, launch_id: str) -> Path:
    """Return the process-owned registration receipt path for one launch."""
    target = Path(launch_file_path)
    return target.with_name(f"{LAUNCH_RECEIPT_PREFIX}{launch_id}.json")


def _prune_stale_launch_receipts(game_dir: Path) -> None:
    """Remove abandoned per-launch receipts after their live retry horizon."""
    cutoff = time.time() - LAUNCH_CLAIM_FRESH_HORIZON
    for path in game_dir.glob(f"{LAUNCH_RECEIPT_PREFIX}*.json"):
        try:
            if path.stat().st_mtime < cutoff:
                path.unlink()
        except OSError:
            pass


_launch_tmp_counter = itertools.count()
_launch_write_locks: Dict[str, "threading.Lock"] = {}
_launch_write_locks_guard = threading.Lock()


def _launch_tmp_path(game_dir: Path) -> Path:
    """A tmp path that cannot collide with any other writer, anywhere.

    A pid-only suffix is NOT enough: the hub is threaded, so two writers in
    ONE process would share the path and interleave their writes into it.
    pid + thread ident + a process-wide counter is unique across processes,
    across threads, and across repeat calls on one thread (ident is recycled
    once a thread dies).
    """
    return game_dir / (
        LAUNCH_FILE_NAME
        + ".tmp-%d-%d-%d" % (
            os.getpid(), threading.get_ident(), next(_launch_tmp_counter)
        )
    )


def _launch_write_lock(target: Path) -> "threading.Lock":
    """The in-process lock guarding *target*, created on first use.

    Keyed on the normalized absolute path so two spellings of the same file
    (relative vs absolute, differing case on Windows) share one lock.
    """
    key = os.path.normcase(os.path.abspath(str(target)))
    with _launch_write_locks_guard:
        lock = _launch_write_locks.get(key)
        if lock is None:
            lock = threading.Lock()
            _launch_write_locks[key] = lock
        return lock


def _try_launch_file_lock(fd: int) -> bool:
    """Try to take the platform's non-blocking exclusive lock on *fd*."""
    try:
        if os.name == "nt":
            import msvcrt

            os.lseek(fd, 0, os.SEEK_SET)
            msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
        else:
            import fcntl

            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except (OSError, BlockingIOError):
        return False
    return True


def _acquire_launch_lockfile(
    lock_path: Path, _claim_wait: float
) -> Tuple[Optional[int], Optional[str]]:
    """Take the cross-process lock for a launch file.

    Returns ``(handle, warning)``.  ``handle`` is None when we could not take
    the lock; the caller then proceeds ANYWAY (a launch must never deadlock)
    with the returned warning, which — like the claim-timeout warning — is
    written to stand on its own, because callers branch on the returned path,
    not on warning text.

    The file is persistent; ownership is the OS advisory lock, not the
    pathname's existence.  POSIX ``flock`` and Windows byte-range locks are
    released automatically when the descriptor closes, including process
    death, so there is no stale file to identify or unlink.  That matters:
    check-then-unlink stale recovery cannot be made generation-safe when two
    contenders inspect the same abandoned pathname concurrently.
    """
    try:
        fd = os.open(str(lock_path), os.O_CREAT | os.O_RDWR, 0o644)
        # msvcrt.locking requires a real byte range.  Concurrent initializers
        # may both write the same sentinel byte; that is harmless.
        if os.fstat(fd).st_size == 0:
            os.write(fd, b"\0")
    except OSError as exc:
        try:
            os.close(fd)
        except (OSError, UnboundLocalError):
            pass
        return None, (
            f"the launch file WAS written, but without a cross-process "
            f"lock ({lock_path.name} could not be opened: {exc}); a second "
            f"launcher writing the same game at this moment could overwrite it"
        )

    deadline = time.monotonic() + LAUNCH_LOCK_ACQUIRE_WAIT
    while not _try_launch_file_lock(fd):
        if time.monotonic() >= deadline:
            try:
                os.close(fd)
            except OSError:
                pass
            return None, (
                f"the launch file WAS written, but only after waiting for "
                f"another launcher process to release {lock_path.name}, which "
                f"it never did; that launch and this one may now disagree "
                f"about which bridge this game talks to"
            )
        time.sleep(LAUNCH_LOCK_POLL)
    return fd, None


def _release_launch_lockfile(
    lock: Optional[int], lock_path: Path
) -> None:
    """Release the OS lock and close its descriptor.  Never raises."""
    if lock is None:
        return
    try:
        if os.name == "nt":
            import msvcrt

            os.lseek(lock, 0, os.SEEK_SET)
            msvcrt.locking(lock, msvcrt.LK_UNLCK, 1)
        else:
            import fcntl

            fcntl.flock(lock, fcntl.LOCK_UN)
    except OSError:
        pass
    try:
        os.close(lock)
    except OSError:
        pass


def _remove_launch_file_if_owned(
    launch_file: str,
    bridge_url: str,
    slot_token: Optional[str] = None,
) -> Tuple[bool, Optional[str]]:
    """Remove a handshake only if its current payload still belongs to us.

    ``vnflight_launch.json`` is one shared pathname per game.  An older slot
    therefore must not blindly unlink the path during teardown: a newer slot
    may already have written its own still-unclaimed handshake there.  Read
    and remove under the same writer locks used by ``_write_launch_file`` and
    require the current bridge URL plus, when available, the slot token to
    match the owner being stopped.

    Returns ``(removed, warning)``.  A missing or foreign file is a normal
    no-op; malformed/unreadable state and lock failures are reported but left
    untouched because ownership cannot be proved safely.
    """
    target = Path(launch_file)
    lock_path = target.parent / (LAUNCH_FILE_NAME + LAUNCH_LOCK_SUFFIX)
    with _launch_write_lock(target):
        lock, lock_warning = _acquire_launch_lockfile(lock_path, 0.0)
        if lock is None:
            return False, lock_warning
        try:
            try:
                with open(target, "r", encoding="utf-8") as f:
                    payload = json.load(f)
            except FileNotFoundError:
                return False, None
            except (OSError, ValueError) as exc:
                return False, (
                    f"could not verify ownership of {target}: {exc}"
                )
            if not isinstance(payload, dict):
                return False, (
                    f"could not verify ownership of {target}: invalid payload"
                )
            if str(payload.get("bridge_url") or "") != str(bridge_url):
                return False, None
            if (
                slot_token is not None
                and str(payload.get("slot_token") or "") != str(slot_token)
            ):
                return False, None
            try:
                os.remove(str(target))
            except FileNotFoundError:
                return False, None
            except OSError as exc:
                return False, f"could not remove {target}: {exc}"
            return True, None
        finally:
            _release_launch_lockfile(lock, lock_path)


def _await_launch_claim(target: Path, wait: float) -> Optional[str]:
    """Wait for a fresh, unclaimed *target* to be claimed; warn on timeout.

    The deadline starts HERE — i.e. when the caller entered the critical
    section, not when it called ``_write_launch_file`` — so a writer that
    queued behind another writer still gets its full claim wait for the
    file that writer left behind.
    """
    deadline = time.monotonic() + max(wait, 0.0)
    while _launch_file_awaiting_claim(target):
        if time.monotonic() >= deadline:
            return (
                f"the launch file WAS written, but only after waiting "
                f"{max(wait, 0.0):.0f}s for the previous launch of this game "
                f"to claim the existing {LAUNCH_FILE_NAME}; if that game is "
                f"still booting it may now read THIS bridge's URL"
            )
        time.sleep(LAUNCH_CLAIM_POLL)
    return None


def _write_launch_file(
    install_root: Optional[Path],
    bridge_url: str,
    slot_token: Optional[str] = None,
    save_slot: Optional[str] = None,
    claim_wait: Optional[float] = None,
    move_host_pointer: Optional[bool] = None,
    launch_id: Optional[str] = None,
    debug: Optional[bool] = None,
    debug_logs: Optional[str] = None,
) -> Tuple[Optional[str], Optional[str]]:
    """Atomically write ``game/vnflight_launch.json`` for the shim.

    Launcher-mediated games (steam://rungameid/..., goggalaxy://...) are
    started by the PLATFORM launcher, not by us — the environment set on
    the process we spawn (VNFLIGHT_BRIDGE_URL / VNFLIGHT_SLOT_TOKEN /
    VNFLIGHT_SAVE_SLOT) never reaches the game, so the shim would dial
    the default port tokenless and miss per-slot bridges entirely.  This
    file carries the same values through the filesystem; the shim treats
    a FRESH file (see its validity window) as this-launch intent that
    wins over possibly-stale env.

    Written for EVERY launch — for env-capable direct-exe games the
    values are identical to the env, so behavior is unchanged.

    CLAIM PROTOCOL.  There is exactly ONE such file per game, so two
    launches of the SAME game race: the second write can land inside the
    first game's multi-second Ren'Py boot window, and BOTH shims then read
    the second slot's bridge_url — one bridge sees no game, the other sees
    two.  The file therefore doubles as the serializer.  A shim that adopts
    a file rewrites it with ``claimed_by`` (its pid); this writer waits up
    to *claim_wait* seconds for a fresh, unclaimed file to pick up its
    claim before overwriting it.  Absent, malformed, already-claimed, and
    stale files (see ``_launch_file_awaiting_claim``) never wait.

    *claim_wait* defaults to ``LAUNCH_CLAIM_WAIT``; 0 disables waiting
    (the state is still inspected, so the caller still gets the warning).

    WRITER VS WRITER.  The claim protocol serializes a writer against a
    booting GAME; it does nothing about two WRITERS, which both observe a
    safe state and both write — and the hub is threaded and starts slots
    near-simultaneously.  So the whole inspect/wait/write section runs
    under two locks: a per-target ``threading.Lock`` (in-process, covering
    hub threads) and an OS advisory lock on a persistent file next to the
    target (cross-process, covering two CLIs or CLI+hub).  After waiting for
    the writer lock, a contender re-runs the claim loop against the previous
    writer's now-present fresh file.  Its full *claim_wait* starts only after
    it owns the writer lock, not when it called this function.

    Returns ``(path, warning)``: the written file path (None on failure)
    and a human-readable warning.  Note both can be set at once — waiting
    out the deadline writes anyway and warns — so the warning text is
    written to stand on its own rather than to imply "not written".
    """
    game_dir = _launch_file_game_dir(install_root)
    if game_dir is None:
        where = f" under {install_root}" if install_root else ""
        return None, f"could not locate the game's game/ directory{where}"
    target = game_dir / LAUNCH_FILE_NAME
    wait = max(
        LAUNCH_CLAIM_WAIT if claim_wait is None else float(claim_wait), 0.0
    )
    lock_path = game_dir / (LAUNCH_FILE_NAME + LAUNCH_LOCK_SUFFIX)
    notes: List[str] = []
    with _launch_write_lock(target):
        lock, lock_warning = _acquire_launch_lockfile(lock_path, wait)
        if lock_warning:
            notes.append(lock_warning)
        try:
            claim_warning = _await_launch_claim(target, wait)
            if claim_warning:
                notes.append(claim_warning)
            _prune_stale_launch_receipts(game_dir)
            path, write_warning = _write_launch_payload(
                game_dir,
                target,
                bridge_url,
                slot_token,
                save_slot,
                move_host_pointer,
                launch_id,
                debug=debug,
                debug_logs=debug_logs,
            )
        finally:
            _release_launch_lockfile(lock, lock_path)
    if write_warning:
        notes.append(write_warning)
    return path, ("; ".join(notes) if notes else None)


def _write_launch_payload(
    game_dir: Path,
    target: Path,
    bridge_url: str,
    slot_token: Optional[str],
    save_slot: Optional[str],
    move_host_pointer: Optional[bool],
    launch_id: Optional[str],
    debug: Optional[bool] = None,
    debug_logs: Optional[str] = None,
) -> Tuple[Optional[str], Optional[str]]:
    """tmp-write + atomic replace of the launch file itself.

    Call only while holding the target's locks (see ``_write_launch_file``).
    """
    payload: Dict[str, Any] = {
        # ALWAYS include the bridge URL (even the default) — a fresh file
        # must fully describe this launch, not depend on leftover env.
        "bridge_url": bridge_url,
        "written_at": time.time(),
    }
    if slot_token:
        payload["slot_token"] = slot_token
    if save_slot:
        payload["save_slot"] = save_slot
    if move_host_pointer is not None:
        payload["move_host_pointer"] = bool(move_host_pointer)
    if launch_id:
        payload["launch_id"] = launch_id
    if debug is not None:
        payload["debug"] = bool(debug)
    if debug_logs:
        payload["debug_logs"] = str(debug_logs)
    tmp = _launch_tmp_path(game_dir)
    replaced = False
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(payload, f)
        os.replace(str(tmp), str(target))
        replaced = True
    except OSError as exc:
        return None, f"could not write {target}: {exc}"
    finally:
        # Clean up after ANY failure, not just OSError — an unexpected
        # exception must not leave a half-written tmp file behind either.
        if not replaced:
            try:
                if tmp.exists():
                    tmp.unlink()
            except OSError:
                pass
    return str(target), None


def _probe_launch_file_writable(
    install_root: Optional[Path],
) -> Optional[str]:
    """Non-destructively verify that a mediated launch can write its handoff."""
    game_dir = _launch_file_game_dir(install_root)
    if game_dir is None:
        where = f" under {install_root}" if install_root else ""
        return f"could not locate the game's game/ directory{where}"
    target = game_dir / LAUNCH_FILE_NAME
    probe = _launch_tmp_path(game_dir)
    replaced = probe.with_name(probe.name + ".replaced")
    # This is an advisory directory/target permission probe, not a handoff
    # writer. Its temp paths are process-unique, so waiting behind the real
    # launch serializer only turns legitimate same-game contention into a
    # false "not writable" result.
    try:
        if target.exists():
            try:
                mode = target.stat().st_mode
            except OSError as exc:
                return f"could not inspect {target}: {exc}"
            if (
                os.name == "nt"
                and (not (mode & stat.S_IWRITE) or not os.access(target, os.W_OK))
            ):
                return f"existing launch file is not writable: {target}"
        with open(probe, "wb") as f:
            f.write(b"{}")
        os.replace(str(probe), str(replaced))
    except OSError as exc:
        return f"could not write in {game_dir}: {exc}"
    finally:
        for path in (probe, replaced):
            try:
                path.unlink()
            except OSError:
                pass
    return None


# ---------------------------------------------------------------------------
# Configuration & game discovery
# ---------------------------------------------------------------------------
#
# Games are configured in ``vnflight.json`` at the project root.
# The config maps game IDs to opaque launch commands so the LLM never
# sees source paths.
#
# Example config:
#
#   {
#     "bridge_script": "bridge/game_bridge.py",
#     "games": {
#       "echoes_of_tomorrow": {
#         "name": "Echoes of Tomorrow",
#         "launch": "renpy-8.5.2-sdk/renpy.exe echoes_of_tomorrow",
#         "briefing": "echoes_of_tomorrow/game_briefing.md"
#       },
#       "some_steam_game": {
#         "name": "Disco Elysium",
#         "launch": "steam://rungameid/632470",
#         "briefing_text": "An RPG about a detective with amnesia..."
#       }
#     }
#   }
#
# If no config exists, the tool falls back to auto-discovery (scans for
# directories containing ``game/vnflight.rpy`` and Ren'Py SDKs).


def _find_project_root() -> Path:
    """Walk up from this script to find the project root."""
    here = Path(__file__).resolve().parent
    candidates = [here, here.parent, here.parent.parent]
    # A source checkout contains both ``src/bridge`` and the actual project
    # config one level above ``src``.  Prefer an explicit config across the
    # whole search range before accepting the legacy bridge-directory marker,
    # otherwise MCP subprocesses load ``src`` as their root and see no games or
    # timing profiles.
    for candidate in candidates:
        if (candidate / CONFIG_FILENAME).exists():
            return candidate
    for candidate in candidates:
        if (candidate / "bridge").is_dir():
            return candidate
    return here


def shim_source_path(games_dir: Optional[str] = None) -> Path:
    """The ``vnflight.rpy`` that ships next to this code.

    An explicit ``--games-dir`` that carries its own ``vnflight.rpy`` is a
    full project root and wins, as before.  A config directory without one
    (the released layout: ``vnflight.json`` and games somewhere, the code
    elsewhere) falls back to where the code lives: the directory of the
    single-file ``vnflight.py``, or the checkout root above ``src/vnflight``.
    """
    here = Path(__file__).resolve().parent
    candidates = []
    if games_dir:
        candidates.append(Path(games_dir))
    candidates += [here, here.parent, here.parent.parent]
    for candidate in candidates:
        source = candidate / "vnflight.rpy"
        if source.exists():
            return source
    return (Path(games_dir) if games_dir else _find_project_root()) / "vnflight.rpy"


def _load_config_with_error(
    games_dir: Optional[str] = None,
) -> Tuple[Optional[dict], Optional[str]]:
    """Load ``vnflight.json``.

    Returns (config, error).  ``error`` is set when the config file exists
    but could not be read/parsed — callers that must not fail silently
    (install-shim) surface it instead of quietly proceeding without mods.
    """
    root = Path(games_dir) if games_dir else _find_project_root()
    config_path = root / CONFIG_FILENAME
    if config_path.exists():
        try:
            with open(config_path, "r", encoding="utf-8") as f:
                return json.load(f), None
        except (json.JSONDecodeError, OSError) as exc:
            return None, f"{config_path}: {exc}"
    return None, None


def _load_config(games_dir: Optional[str] = None) -> Optional[dict]:
    """Load ``vnflight.json`` if it exists.  Returns None otherwise."""
    return _load_config_with_error(games_dir)[0]


# ---------------------------------------------------------------------------
# Game adapters ("mods"): explicit list, or a mods-repo manifest
# ---------------------------------------------------------------------------

MODS_MANIFEST_KEY = "mods_manifest"
MODS_SNAPSHOT_KEY = "mods_snapshot"


def pinned_mods_snapshot(config: Optional[dict]) -> Optional[Tuple[str, str]]:
    """The (url, sha256) pinned under the top-level ``mods_snapshot`` key.

    The template ships the snapshot a release was tested with.  Only
    ``fetch-mods`` reads it, and only when run without explicit
    arguments; nothing downloads it implicitly.  ``None`` when the key is
    missing or malformed (callers say which key to fix).
    """
    entry = (config or {}).get(MODS_SNAPSHOT_KEY)
    if not isinstance(entry, dict):
        return None
    url = entry.get("url")
    digest = entry.get("sha256")
    if not isinstance(url, str) or not isinstance(digest, str):
        return None
    url, digest = url.strip(), digest.strip().lower()
    if not url or not digest:
        return None
    return url, digest


class ModResolution:
    """Where a game's adapters come from and what they are.

    ``entries``: ``[{"source": Path, "target": str, "label": str,
    "sha256": Optional[str]}]`` ready to install/compare.
    ``origin``: ``"explicit"`` (the game entry's own ``mods`` list),
    ``"manifest"`` (the mods-repo manifest named by the top-level
    ``mods_manifest`` key) or ``"none"``.
    ``problems``: human-readable reasons for entries that could NOT be
    resolved (malformed entry, missing file, manifest unreadable, sha256
    mismatch).  Callers decide whether a problem blocks (install-shim) or
    is reported and skipped (the fail-open stale-shim check).
    """

    def __init__(self, origin: str, entries: List[dict], problems: List[str],
                 manifest_path: Optional[Path] = None):
        self.origin = origin
        self.entries = entries
        self.problems = problems
        self.manifest_path = manifest_path

    def summary(self) -> str:
        n = len(self.entries)
        noun = "adapter" if n == 1 else "adapters"
        if self.origin == "explicit":
            base = f"{n} {noun} (config)"
        elif self.origin == "manifest":
            base = f"{n} {noun} (manifest)"
        else:
            base = "no adapters"
        if self.problems:
            # Say what the problem is; a bare count sends the user to
            # install-shim just to read the reason.
            base += f", {len(self.problems)} problem(s): " + "; ".join(self.problems)
        return base


def _resolve_manifest_path(config: dict, root: Path) -> Optional[Path]:
    raw = (config or {}).get(MODS_MANIFEST_KEY)
    if not isinstance(raw, str) or not raw.strip():
        return None
    p = Path(raw.strip()).expanduser()
    if not p.is_absolute():
        p = root / p
    return p


def resolve_game_mods(config: Optional[dict], game_id: str, game_cfg: dict,
                      root: Path) -> ModResolution:
    """Resolve a game's adapters.

    Order: a ``mods`` key on the game entry wins as written (an empty list
    means "none", the manifest is not consulted).  Without a ``mods`` key,
    the manifest named by the top-level ``mods_manifest`` (absolute, or
    relative to ``vnflight.json``; never a URL) supplies the files for the
    game id, or for the id named by the entry's ``adapters`` key (so a
    second config entry for the same game reuses one manifest entry).
    Manifest files are verified against their sha256 before use; a mismatch
    or a missing file is a problem, not an install.
    """
    game_cfg = game_cfg or {}
    problems: List[str] = []
    entries: List[dict] = []

    if "mods" in game_cfg:
        raw_mods = game_cfg.get("mods") or []
        if not isinstance(raw_mods, list):
            return ModResolution("explicit", [], [f"'mods' for {game_id!r} is not a list"])
        for mod in raw_mods:
            if not isinstance(mod, dict):
                problems.append(f"malformed mod entry for {game_id!r}: {mod!r}")
                continue
            source = mod.get("source")
            target = mod.get("target")
            if not isinstance(target, str) or not target.strip():
                problems.append(f"mod with invalid target for {game_id!r}: {target!r}")
                continue
            if not isinstance(source, str) or not source.strip():
                problems.append(f"mod {target!r} for {game_id!r} has no source")
                continue
            src = Path(source).expanduser()
            if not src.is_absolute():
                src = root / src
            entries.append({"source": src, "target": target, "label": source,
                            "sha256": None})
        return ModResolution("explicit", entries, problems)

    manifest_path = _resolve_manifest_path(config or {}, root)
    if manifest_path is None:
        return ModResolution("none", [], [])

    key = game_cfg.get("adapters") if isinstance(game_cfg.get("adapters"), str) else game_id
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return ModResolution("manifest", [], [f"mods manifest not found: {manifest_path}"],
                             manifest_path)
    except (OSError, json.JSONDecodeError) as exc:
        return ModResolution("manifest", [], [f"mods manifest unreadable: {manifest_path}: {exc}"],
                             manifest_path)
    games = manifest.get("games") if isinstance(manifest, dict) else None
    entry = (games or {}).get(key) if isinstance(games, dict) else None
    if not isinstance(entry, dict):
        # Not listed: a game the manifest does not know is simply a game
        # without adapters.
        return ModResolution("none", [], [], manifest_path)
    for mod in entry.get("mods") or []:
        if not isinstance(mod, dict):
            problems.append(f"malformed manifest entry for {key!r}: {mod!r}")
            continue
        name = mod.get("file")
        target = mod.get("target")
        expected = mod.get("sha256")
        if not isinstance(name, str) or not name.strip() or "/" in name or "\\" in name:
            problems.append(f"manifest entry for {key!r} has an invalid file name: {name!r}")
            continue
        if not isinstance(target, str) or not target.strip():
            problems.append(f"manifest entry {name!r} for {key!r} has an invalid target: {target!r}")
            continue
        src = manifest_path.parent / name
        if not src.exists():
            problems.append(f"adapter {name!r} listed for {key!r} is missing next to the manifest ({src})")
            continue
        if isinstance(expected, str) and expected.strip():
            actual = hashlib.sha256(src.read_bytes()).hexdigest()
            if actual.lower() != expected.strip().lower():
                problems.append(
                    f"adapter {name!r} for {key!r} does not match the manifest "
                    f"(sha256 {actual[:12]}... vs manifest {expected.strip()[:12]}...); "
                    "refusing to install it"
                )
                continue
        entries.append({"source": src, "target": target,
                        "label": f"{manifest_path.name}:{name}",
                        "sha256": expected if isinstance(expected, str) else None})
    return ModResolution("manifest", entries, problems, manifest_path)


def describe_game_mods(config: Optional[dict], game_id: str, game_cfg: dict,
                       root: Path) -> str:
    """One line for ``games``: where the adapters come from."""
    try:
        return resolve_game_mods(config, game_id, game_cfg, root).summary()
    except Exception as exc:  # noqa: BLE001 - listing must never fail on mods
        return f"adapters: error ({exc})"


def _read_briefing(root: Path, game_cfg: dict) -> Tuple[bool, str, str]:
    """
    Read briefing text for a game entry.

    Returns (has_briefing, full_text, short_description).
    """
    # Inline briefing text takes priority.
    inline = game_cfg.get("briefing_text", "")
    if inline:
        short = ""
        for line in inline.splitlines():
            line = line.strip()
            if line and not line.startswith("#"):
                short = line[:100]
                break
        return True, inline, short

    # Path-based briefing.
    briefing_rel = game_cfg.get("briefing", "")
    if briefing_rel:
        briefing_path = root / briefing_rel
        if briefing_path.exists():
            text = briefing_path.read_text(encoding="utf-8")
            short = ""
            for line in text.splitlines():
                line = line.strip()
                if line and not line.startswith("#"):
                    short = line[:100]
                    break
            return True, text, short

    return False, "", ""


# Game-entry keys (vnflight.json "games" values) that map to bridge-side
# GameState runtime config, pushed via POST /config after the game connects.
# This is THE lookup for per-game bridge config — the CLI launch path
# (launch_game below) and the harness vn plugin both go through
# extract_bridge_config so the key list lives in exactly one place.
BRIDGE_CONFIG_KEYS: Tuple[str, ...] = ("end_on_menu_return",)


def extract_bridge_config(game_cfg: dict) -> dict:
    """Return the bridge-side config overrides present in a game entry.

    e.g. Slay the Princess sets ``"end_on_menu_return": false`` because its
    live gameplay screens are classified as main_menu, which false-fires
    the return-to-menu playthrough-ended heuristic.
    """
    return {k: game_cfg[k] for k in BRIDGE_CONFIG_KEYS if k in game_cfg}


def discover_games(games_dir: Optional[str] = None) -> List[dict]:
    """
    Discover available games.

    First checks ``vnflight.json`` for explicit entries.  Falls back
    to scanning for directories containing ``game/vnflight.rpy``.
    """
    root = Path(games_dir) if games_dir else _find_project_root()
    config = _load_config(games_dir)

    games: List[dict] = []

    if config and "games" in config:
        # ---- Config-based discovery ----
        for game_id, game_cfg in config["games"].items():
            # The template carries a string-valued "_comment" under games
            # and "_example_*" entries: neither is a game.  A string
            # entry used to crash the listing ('str' has no .get).
            if not isinstance(game_cfg, dict) or str(game_id).startswith("_"):
                continue
            has_briefing, briefing, short_desc = _read_briefing(root, game_cfg)
            games.append(
                {
                    "id": game_id,
                    "name": game_cfg.get("name", game_id),
                    "launch_cmd": game_cfg.get("launch", ""),
                    "game_dir": game_cfg.get("game_dir"),
                    # Optional per-game shim diagnostics: debug (bool) turns
                    # on the shim's command/action log; debug_logs is the
                    # directory it writes per-session files into (default:
                    # the game's own directory). A launch may override debug.
                    "debug": game_cfg.get("debug"),
                    "debug_logs": game_cfg.get("debug_logs"),
                    "has_briefing": has_briefing,
                    "briefing": briefing,
                    "short_desc": short_desc,
                    "bridge_config": extract_bridge_config(game_cfg),
                    # Where the adapters come from: the entry's own mods
                    # list, the mods-repo manifest, or none.
                    "mods": describe_game_mods(config, game_id, game_cfg, root),
                    "_source": "config",
                }
            )
    else:
        # ---- Auto-discovery fallback ----
        for entry in sorted(root.iterdir()):
            if not entry.is_dir():
                continue
            marker = entry / "game" / "vnflight.rpy"
            if not marker.exists():
                continue

            briefing = ""
            short_desc = ""
            has_briefing = False
            briefing_path = entry / "game_briefing.md"
            if briefing_path.exists():
                has_briefing = True
                briefing = briefing_path.read_text(encoding="utf-8")
                for line in briefing.splitlines():
                    line = line.strip()
                    if line and not line.startswith("#"):
                        short_desc = line[:100]
                        break

            # Build a default launch command from auto-detected SDK.
            launch_cmd = _build_auto_launch_cmd(root, str(entry))

            games.append(
                {
                    "id": entry.name,
                    "name": entry.name,
                    "launch_cmd": launch_cmd,
                    "has_briefing": has_briefing,
                    "briefing": briefing,
                    "short_desc": short_desc,
                    "_source": "auto",
                }
            )

    return games


def _build_auto_launch_cmd(root: Path, game_path: str) -> str:
    """Build a launch command string from auto-detected SDK + game path."""
    sdks = _discover_sdks(root)
    if not sdks:
        return ""
    sdk = sdks[0]
    exe = sdk["exe"]
    # Build a command relative to root if possible.
    try:
        rel_exe = os.path.relpath(exe, root)
        rel_game = os.path.relpath(game_path, root)
    except ValueError:
        rel_exe = exe
        rel_game = game_path
    return f"{rel_exe} {rel_game}"


def _discover_sdks(root: Path) -> List[dict]:
    """Scan for Ren'Py SDKs (directories matching renpy-*-sdk/)."""
    sdks: List[dict] = []

    for entry in sorted(root.iterdir()):
        if not entry.is_dir():
            continue
        if not re.match(r"renpy-[\d.]+-sdk", entry.name):
            continue

        exe = entry / ("renpy.exe" if IS_WINDOWS else "renpy.sh")
        if not exe.exists():
            exe = entry / "renpy.py"
            if not exe.exists():
                continue

        m = re.search(r"renpy-([\d.]+)-sdk", entry.name)
        version = m.group(1) if m else "unknown"

        sdks.append(
            {
                "path": str(entry),
                "exe": str(exe),
                "version": version,
                "name": entry.name,
            }
        )

    sdks.sort(key=lambda s: s["version"], reverse=True)
    return sdks


_BRIDGE_MODULE_SENTINEL = "__vnflight_bridge_module__"


def _find_bridge_script(games_dir: Optional[str] = None) -> Optional[str]:
    """Locate the bridge server.

    Returns a path to a standalone bridge script (if configured), or the
    sentinel ``_BRIDGE_MODULE_SENTINEL`` to launch via
    ``python -m vnflight.bridge``.
    """
    root = Path(games_dir) if games_dir else _find_project_root()

    # Honour explicit config (e.g. custom bridge script).
    config = _load_config(games_dir)
    if config:
        script = config.get("bridge_script")
        if script:
            candidate = root / script
            if candidate.exists():
                return str(candidate)

    # Primary: use the package module.
    try:
        import vnflight.bridge  # noqa: F401
        return _BRIDGE_MODULE_SENTINEL
    except (ImportError, ModuleNotFoundError):
        pass
    # File-system fallback: locate bridge.py relative to this module.
    _bridge_py = Path(__file__).parent / "bridge.py"
    if _bridge_py.exists():
        return _BRIDGE_MODULE_SENTINEL
    # Built single-file: bridge symbols are in __main__.
    try:
        import __main__ as _main_mod
        if callable(getattr(_main_mod, "run_bridge_server", None)):
            return _BRIDGE_MODULE_SENTINEL
    except Exception:
        pass

    return None


# ---------------------------------------------------------------------------
# Process management (launch / stop)
# ---------------------------------------------------------------------------


def _is_process_alive(pid: int) -> bool:
    """Check if a process with the given PID is still running."""
    try:
        if IS_WINDOWS:
            # tasklist emits OEM-codepage bytes; decoding as UTF-8
            # (text=True's default) crashes the reader thread on bytes
            # like 0xff, leaving stdout=None -> "NoneType is not
            # iterable". errors="replace" keeps it safe (the PID digits
            # we match on are ASCII regardless). CSV output lets us match
            # the PID column exactly instead of a substring that could
            # hit 1234 for 123 or a memory-size column.
            result = subprocess.run(
                ["tasklist", "/FI", f"PID eq {pid}", "/NH", "/FO", "CSV"],
                capture_output=True,
                text=True,
                errors="replace",
                timeout=5,
            )
            out = result.stdout or ""
            for row in csv.reader(out.splitlines()):
                if len(row) >= 2 and row[1].strip() == str(pid):
                    return True
            return False
        else:
            os.kill(pid, 0)
            return True
    except (OSError, subprocess.TimeoutExpired):
        return False


def process_command_line(pid: int) -> Optional[str]:
    """Return "<image name> <command line>" for a live process, or None when
    it cannot be read (no such process, access denied, tool failure)."""
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        return None
    try:
        if IS_WINDOWS:
            script = (
                "$p = Get-CimInstance Win32_Process -Filter \"ProcessId = "
                + str(pid)
                + "\"; if ($p) { $p.Name; $p.CommandLine }"
            )
            result = subprocess.run(
                ["powershell", "-NoProfile", "-NonInteractive", "-Command", script],
                capture_output=True, text=True, errors="replace", timeout=15,
            )
            lines = [l.strip() for l in (result.stdout or "").splitlines() if l.strip()]
            return " ".join(lines) or None
        proc_cmdline = f"/proc/{pid}/cmdline"
        if os.path.exists(proc_cmdline):
            with open(proc_cmdline, "rb") as f:
                value = f.read().replace(b"\0", b" ").decode("utf-8", "replace").strip()
            if value:
                return value
        result = subprocess.run(
            ["ps", "-p", str(pid), "-o", "args="],
            capture_output=True, text=True, errors="replace", timeout=5,
        )
        return (result.stdout or "").strip() or None
    except Exception:
        return None


# Tokens too generic to identify a game process on their own.
_GENERIC_IDENTITY_TOKENS = {
    "python", "python3", "pythonw", "steam", "exe", "game", "games", "app",
    "bin", "lib", "sh", "run", "start", "launch", "x86", "x64", "windows",
    "linux", "mac", "macos",
}


def _identity_norm(text: str) -> str:
    """Case-fold and drop separators so 'Slay the Princess', 'slay_the_princess'
    and 'SlayThePrincess.exe' all compare on the same footing."""
    out = []
    for ch in str(text).lower():
        if ch.isalnum():
            out.append(ch)
    return "".join(out)


def _identity_token_ok(token: object) -> bool:
    if not isinstance(token, str):
        return False
    norm = _identity_norm(token)
    return len(norm) >= 4 and norm not in {_identity_norm(t) for t in _GENERIC_IDENTITY_TOKENS}


def normalize_identity_expectation(expect: object) -> list:
    """An expectation is a list of groups; every group must be satisfied by at
    least one of its alternatives (case-insensitive, separator-insensitive
    substring of the process's image name + command line).  A bare string or
    a flat list of strings is one group.  Empty/invalid -> []."""
    if isinstance(expect, str):
        expect = [[expect]]
    if not isinstance(expect, (list, tuple)):
        return []
    groups = []
    if expect and all(isinstance(e, str) for e in expect):
        expect = [list(expect)]
    for group in expect:
        if isinstance(group, str):
            group = [group]
        if not isinstance(group, (list, tuple)):
            continue
        alts = [str(a) for a in group if isinstance(a, str) and a.strip()]
        if alts:
            groups.append(alts)
    return groups


def process_matches(identity: Optional[str], expect: object) -> bool:
    """True when every expectation group has an alternative present in the
    process identity string.  No identity or no expectation -> False."""
    groups = normalize_identity_expectation(expect)
    if not identity or not groups:
        return False
    hay = _identity_norm(identity)
    for group in groups:
        if not any(_identity_norm(alt) and _identity_norm(alt) in hay for alt in group):
            return False
    return True


def _describe_expectation(expect: object) -> str:
    groups = normalize_identity_expectation(expect)
    return " AND ".join("(" + " | ".join(g) + ")" for g in groups) or "<nothing>"


def kill_process(pid: int, expect: object = None) -> bool:
    """Kill a process only when it still looks like the one we launched.

    ``expect`` describes the identity (see normalize_identity_expectation):
    groups of substrings that must appear in the process's image name or
    command line.  Without an expectation, with an unreadable identity, or
    with a mismatch the kill is REFUSED (False, with a stderr line): the
    per-user state file is shared by every checkout and can hold a stale
    pid that the OS has since given to an unrelated process.

    Returns True if the process was terminated or already dead, False if
    it was refused or termination failed.
    """
    if not _is_process_alive(pid):
        return True

    groups = normalize_identity_expectation(expect)
    if not groups:
        print(
            f"[vnflight] refused to kill pid {pid}: no identity expectation given",
            file=sys.stderr,
        )
        return False
    identity = process_command_line(pid)
    if identity is None:
        print(
            f"[vnflight] refused to kill pid {pid}: its command line could not be "
            f"read (expected {_describe_expectation(groups)})",
            file=sys.stderr,
        )
        return False
    if not process_matches(identity, groups):
        head = identity if len(identity) <= 120 else identity[:117] + "..."
        print(
            f"[vnflight] refused to kill pid {pid}: {head} does not look like "
            f"{_describe_expectation(groups)}",
            file=sys.stderr,
        )
        return False

    try:
        if IS_WINDOWS:
            # Use /T to kill child processes as well (needed for Steam games)
            subprocess.run(
                ["taskkill", "/F", "/T", "/PID", str(pid)],
                capture_output=True,
                timeout=5,
            )
        else:
            os.kill(pid, signal.SIGTERM)
        # Give it a moment to terminate
        time.sleep(0.2)
        return not _is_process_alive(pid)
    except Exception:
        return False


BRIDGE_IDENTITY: list = [["vnflight"], ["bridge"]]
# What a legacy pid record (no stored identity) is checked against: only
# that the process is a Ren'Py engine / a vnflight bridge at all.
LEGACY_GAME_IDENTITY: list = [["renpy"]]
LEGACY_BRIDGE_IDENTITY: list = [["vnflight"]]


def _shared_game_launcher(value: str) -> bool:
    name = value.lower()
    for suffix in (".exe", ".py", ".sh"):
        if name.endswith(suffix):
            name = name[:-len(suffix)]
            break
    return bool(re.fullmatch(r"renpy|pythonw?(?:\d+(?:\.\d+)*)?(?:t|_d)?", name))


def game_identity_expectation(
    game_id: str,
    game_cmd_parts: Optional[List[str]] = None,
    install_root: object = None,
    game_name: object = None,
) -> list:
    """Two groups: the process looks like an engine/exe we launched, AND it
    looks like THIS game (its id, install directory, project directory or
    display name), so a recycled pid belonging to another Ren'Py game is
    spared too."""
    engine: list = ["renpy"]
    this_game: list = []
    parts = [str(p) for p in (game_cmd_parts or []) if isinstance(p, str)]
    if parts and "://" not in parts[0]:
        exe = parts[0]
        stem = os.path.splitext(os.path.basename(exe.rstrip("/\\")))[0]
        if _identity_token_ok(stem):
            engine.append(stem)
            if not _shared_game_launcher(stem):
                this_game.append(stem)
        for arg in parts[1:]:
            if arg.startswith("-") or "://" in arg:
                continue
            base = os.path.basename(str(arg).rstrip("/\\"))
            if _shared_game_launcher(base):
                continue
            if _identity_token_ok(base):
                this_game.append(base)
    if install_root:
        base = os.path.basename(str(install_root).rstrip("/\\"))
        if _identity_token_ok(base):
            engine.append(base)
            if not _shared_game_launcher(base):
                this_game.append(base)
    if _identity_token_ok(game_id):
        this_game.append(str(game_id))
    if _identity_token_ok(game_name):
        this_game.append(str(game_name))
    seen: set = set()
    engine = [t for t in engine if not (t.lower() in seen or seen.add(t.lower()))]
    seen = set()
    this_game = [t for t in this_game if not (t.lower() in seen or seen.add(t.lower()))]
    return [engine, this_game] if this_game else [engine]


def pid_identity_from_record(pids: dict, name: str) -> Tuple[list, str]:
    """The expectation stored next to a pid in the state file, or the legacy
    default plus a note saying so."""
    stored = (pids or {}).get(f"{name}_expect")
    groups = normalize_identity_expectation(stored)
    if groups:
        return groups, ""
    if name == "bridge":
        return LEGACY_BRIDGE_IDENTITY, " (record predates identity tracking; checked only that it is a vnflight process)"
    return LEGACY_GAME_IDENTITY, " (record predates identity tracking; checked only that it is a Ren'Py process)"


def _launch_subprocess(
    cmd: List[str],
    cwd: Optional[str] = None,
    log_file: Optional[str] = None,
    extra_env: Optional[Dict[str, str]] = None,
) -> Tuple[Optional[int], str]:
    """
    Launch a subprocess detached from the current terminal.

    If *log_file* is given, stdout and stderr are redirected there.
    Otherwise output goes to ``os.devnull`` opened as a real file
    descriptor (more reliable than ``subprocess.DEVNULL`` on Windows
    when combined with ``CREATE_NEW_PROCESS_GROUP``).

    Returns (pid_or_None, error_message).
    """
    try:
        if log_file:
            os.makedirs(os.path.dirname(log_file) or ".", exist_ok=True)
            fh: Any = open(log_file, "w", encoding="utf-8")
        else:
            fh = open(os.devnull, "w")
        # Prevent the handle from being garbage-collected.
        _launch_log_handles.append(fh)

        # Pass environment variable to enable the shim
        env = os.environ.copy()
        env["VNFLIGHT_ENABLED"] = "1"
        if extra_env:
            env.update(extra_env)

        kwargs: Dict[str, Any] = {
            "stdin": subprocess.DEVNULL,
            "stdout": fh,
            "stderr": fh,
            "close_fds": True,
            "env": env,
        }
        if cwd:
            kwargs["cwd"] = cwd
        if IS_WINDOWS:
            # Both flags are needed for true detachment on Windows:
            # CREATE_NEW_PROCESS_GROUP prevents Ctrl+C propagation,
            # DETACHED_PROCESS prevents the child from dying when the
            # parent's console/shell session ends.
            DETACHED_PROCESS = 0x00000008
            kwargs["creationflags"] = (
                subprocess.CREATE_NEW_PROCESS_GROUP | DETACHED_PROCESS  # type: ignore[attr-defined]
            )
        else:
            kwargs["start_new_session"] = True

        proc = subprocess.Popen(cmd, **kwargs)
        return proc.pid, ""
    except FileNotFoundError as exc:
        # The OS text is localized and names nothing; say which
        # executable was asked for.
        return None, f"executable not found: '{cmd[0]}' ({exc})"
    except Exception as exc:
        return None, f"could not start '{cmd[0]}': {exc}"


def _runtime_log_dir(root: Path) -> Path:
    """Directory for bridge/game stdout logs.

    Project checkouts keep logs under ``<root>/bridge/logs`` as before.
    When root fell back to the package directory (pip install into
    site-packages, no project around), route logs to the per-user data
    dir instead of writing next to the package.
    """
    try:
        if root.resolve() == _package_dir():
            return user_data_dir() / "logs"
    except OSError:
        pass
    return root / "bridge" / "logs"


def _parse_launch_cmd(launch_cmd: str) -> List[str]:
    """
    Parse a launch command string into a list of arguments.

    Handles quoted arguments and protocol URLs (e.g., steam://, goggalaxy://).
    """
    if not launch_cmd:
        return []

    # Steam URLs or other protocol handlers.
    if "://" in launch_cmd and not launch_cmd.startswith(("/", ".", "\\")):
        if IS_WINDOWS:
            return ["cmd", "/c", "start", "", launch_cmd]
        elif platform.system() == "Darwin":
            return ["open", launch_cmd]
        else:
            return ["xdg-open", launch_cmd]

    # Split respecting quotes.  POSIX-mode shlex treats a backslash as an
    # escape, which silently mangles Windows paths ("C:\\Games\\x" ->
    # "C:Gamesx"); on Windows split non-POSIX and strip the quotes shlex
    # then leaves on quoted tokens.
    import shlex

    try:
        if IS_WINDOWS:
            parts = shlex.split(launch_cmd, posix=False)
            return [
                part[1:-1] if len(part) >= 2 and part[0] == part[-1] and part[0] in "\"'" else part
                for part in parts
            ]
        return shlex.split(launch_cmd)
    except ValueError:
        return launch_cmd.split()


def _registration_rejection_belongs_to_launch(
    rejection: Any,
    *,
    game_id: str,
    launch_id: str,
    launch_started_at: float,
) -> bool:
    """Return whether a token-owned diagnostic belongs to this launch."""
    if (
        not isinstance(rejection, dict)
        or not _game_ids_match(
            rejection.get("game_id"), game_id,
        )
    ):
        return False
    rejected_launch_id = rejection.get("launch_id")
    if rejected_launch_id is not None:
        return str(rejected_launch_id) == str(launch_id)
    try:
        rejected_at = float(rejection.get("rejected_at") or 0.0)
    except (TypeError, ValueError):
        return False
    # A pre-receipt shim cannot send launch_id. Bridge and launcher share the
    # host clock, and the attempt timestamp precedes writing the handoff, so a
    # current rejection cannot legitimately predate it.
    return rejected_at >= float(launch_started_at)


def _registration_rejection_matches(
    rejection: Any,
    *,
    game_id: str,
    launch_id: str,
    launch_started_at: float,
) -> bool:
    """Return whether a terminal refusal belongs to this launch attempt."""
    return (
        isinstance(rejection, dict)
        and rejection.get("transient") is not True
        and _registration_rejection_belongs_to_launch(
            rejection,
            game_id=game_id,
            launch_id=launch_id,
            launch_started_at=launch_started_at,
        )
    )


def launch_game(
    game_id: str,
    bridge_url: str,
    games_dir: Optional[str],
    fast_forward: bool,
    auto_advance: bool,
    client_state: ClientState,
    connect_timeout: Optional[float] = None,
    replace: bool = True,
    save_slot: Optional[str] = None,
    token: Optional[str] = None,
    reservation_token: Optional[str] = None,
    diagnostics: Optional[dict] = None,
    debug: Optional[bool] = None,
) -> Tuple[bool, str, Optional[int]]:
    """
    Launch the bridge server and a game.

    *debug* overrides the game's ``debug`` config for this launch (None =
    use the config). The effective value and the game's ``debug_logs``
    directory reach the shim through the environment and the launch file.

    *diagnostics*, when given, is populated in place (never via the return
    tuple, which many callers unpack positionally) with timing signals a
    caller can surface: ``connected_after_s`` (seconds from the start of the
    connect wait to the slot becoming ready) on success, or
    ``connect_failed_after_s`` on a connect-phase failure.

    The launch command comes from the config or auto-discovery.
    The LLM sees only the game ID and a success/failure message — never
    the underlying file paths.

    When *replace* is False, existing instances of the same game are kept
    alive and a new slot is allocated on the bridge (multi-instance mode).

    Returns (success, message).
    """
    # Local import to avoid module-level dependency on .client
    # (intra-package import stripped by build)
    pass
    # (intra-package import stripped by build)
    pass

    # Refuse a game whose installed shim has drifted from the repo — see
    # stale_shim_error(). Cheapest possible moment: nothing is running yet.
    # ONE scan yields both answers — calling the two wrappers would re-scan and
    # could disagree with itself about the same launch.
    _stale, _shim_note = shim_report(game_id, games_dir)
    if _stale:
        return False, _stale, None

    games = discover_games(games_dir)
    game = next((g for g in games if g["id"] == game_id), None)
    if not game:
        available = ", ".join(g["id"] for g in games) or "(none found)"
        return False, f"Game '{game_id}' not found.  Available: {available}", None

    launch_cmd = game.get("launch_cmd", "")
    if not launch_cmd:
        return False, (
            f"No launch command for '{game_id}'.  "
            "Add a 'launch' field in vnflight.json or place a Ren'Py SDK "
            "next to the game directory."
        ), None

    if connect_timeout is not None and float(connect_timeout) <= 0:
        return False, "Launch timeout must be greater than zero.", None

    game_cmd_parts = _parse_launch_cmd(launch_cmd)
    if not game_cmd_parts:
        return False, f"Empty launch command for '{game_id}'.", None
    if game_cmd_parts[0].endswith(".py"):
        game_cmd_parts = [sys.executable] + game_cmd_parts
    is_launcher = any(launch_cmd.startswith(p)
                      for p in ("steam://", "goggalaxy://", "com.epicgames."))
    install_root = _find_game_install_path(game_id, games_dir)
    # See _expected_shim_game_id: a config entry can point at a game_dir it
    # shares with another entry (Ren'Py-version variants), in which case the
    # shim reports the shared directory's name, not this config's own id.
    # Every slot/rejection match below must compare against that id.
    shim_game_id = _expected_shim_game_id(game, game_id)
    if is_launcher:
        launch_probe_error = _probe_launch_file_writable(install_root)
        if launch_probe_error:
            return False, (
                "Cannot launch through Steam/GOG without a writable vnflight "
                f"launch file: {launch_probe_error}. Fix the game install "
                "path or file permissions before retrying."
            ), None

    bridge_script = _find_bridge_script(games_dir)
    if not bridge_script:
        return False, "Cannot find bridge server (vnflight.bridge not importable)", None

    # Parse port from bridge_url.
    parsed = urllib.parse.urlparse(bridge_url)
    port = parsed.port or DEFAULT_BRIDGE_PORT
    host = parsed.hostname or "127.0.0.1"

    # Determine working directory (project root) for resolving relative paths.
    root = Path(games_dir) if games_dir else _find_project_root()

    get_admin_token = getattr(client_state, "get_admin_token", None)
    admin_token = token or (
        get_admin_token(bridge_url) if callable(get_admin_token) else None
    ) or os.environ.get("VNFLIGHT_TOKEN") or None

    # ---- Start bridge ----
    session = BridgeClient(bridge_url, token=admin_token)
    bridge_pid = None
    replacement_game_pids: set[int] = set()
    bridge_was_up = session.is_up()

    def bridge_protocol_error() -> Optional[str]:
        status_reader = getattr(session, "status", None)
        if not callable(status_reader):
            return None
        bridge_status = status_reader(timeout=3.0)
        if not isinstance(bridge_status, dict) or not bridge_status:
            return (
                "The running bridge answered its health check, but its "
                "protocol status could not be read. Retry the launch; if "
                "the bridge remains unavailable, restart the bridge/hub."
            )
        bridge_protocol = bridge_status.get("shim_protocol_version")
        if bridge_protocol == SHIM_PROTOCOL_VERSION:
            return None
        return (
            "Running bridge protocol does not match this vnflight build "
            f"(expected shim protocol {SHIM_PROTOCOL_VERSION}, got "
            f"{bridge_protocol!r}). Restart the bridge/hub from the "
            "current checkout before launching a game."
        )

    if bridge_was_up:
        protocol_error = bridge_protocol_error()
        if protocol_error:
            return False, protocol_error, None
        if replace:
            existing_slot_list = session.list_slots()
            if existing_slot_list is None:
                return False, (
                    "Could not list bridge slots before launching. "
                    "Restart the bridge/MCP session before launching."
                ), None
            replacement_game_pids = _same_game_slot_pids(
                existing_slot_list,
                shim_game_id,
            )
            # Bridge already running — free any stale slot for this game
            # (the shim will re-assign on connect). Don't reset other slots.
            ok, error = _free_existing_game_slot(
                session,
                game_id,
                existing_slots=existing_slot_list,
                client_state=client_state,
                bridge_url=bridge_url,
                match_id=shim_game_id,
            )
            if not ok:
                return False, error, None
    else:
        if admin_token is None:
            admin_token = secrets.token_urlsafe(16)
            session.token = admin_token
        # Start the bridge as a subprocess so it outlives the launcher.
        # Strategy 1: python <this_script> bridge --port N (built single-file)
        # Strategy 2: python -m vnflight.bridge --port N (package)
        # Strategy 3: python <explicit_script> --port N (config override)
        _extra_env: dict[str, str] = {
            # Keep the bridge alive across game restarts by default.
            # Without this, the bridge auto-shuts-down 10s after all
            # games disconnect, forcing each restart to bootstrap a
            # fresh bridge.  Interactive human-in-the-loop workflows
            # need the bridge to survive `stop` → `launch` cycles.
            "VNFLIGHT_KEEP_ALIVE": "1",
        }
        if bridge_script == _BRIDGE_MODULE_SENTINEL:
            # Prefer "self bridge" only for the actual built launcher. Library
            # callers such as diagnostics scripts have their own argv[0] and do
            # not implement the vnflight CLI subcommands.
            _self_script = Path(sys.argv[0]).resolve() if sys.argv else None
            if (
                _self_script
                and _self_script.exists()
                and _self_script.name == "vnflight.py"
            ):
                bridge_cmd = [sys.executable, str(_self_script), "bridge"]
            elif (root / "vnflight.py").exists():
                bridge_cmd = [sys.executable, str(root / "vnflight.py"), "bridge"]
            else:
                bridge_cmd = [sys.executable, "-m", "vnflight.bridge"]
                _src_dir = root / "src" / "vnflight"
                if _src_dir.is_dir():
                    _extra_env["PYTHONPATH"] = str(_src_dir.parent)
        else:
            bridge_cmd = [sys.executable, bridge_script]
        bridge_cmd += [
            "--host", host,
            "--port", str(port),
            "--token=" + admin_token,
        ]
        bridge_log = str(_runtime_log_dir(root) / "bridge_stdout.log")
        bridge_pid, err = _launch_subprocess(
            bridge_cmd, cwd=str(root), log_file=bridge_log,
            extra_env=_extra_env,
        )
        if not bridge_pid:
            return False, f"Failed to start bridge: {err}", None

        # Importing the 1.6 MB single-file artifact takes 4-5 s idle and
        # more on a loaded machine (a full test run alongside pushed it
        # past 10 s on Sep 5): a tight deadline reports a healthy bridge
        # as "did not become ready".
        readiness_deadline = time.monotonic() + BRIDGE_READINESS_TIMEOUT_S
        bridge_ready = False
        while True:
            remaining = readiness_deadline - time.monotonic()
            if remaining <= 0:
                break
            bridge_ready = session.is_up(timeout=min(2.0, remaining))
            if bridge_ready:
                break
            time.sleep(min(0.3, max(0.0, readiness_deadline - time.monotonic())))
        if not bridge_ready:
            kill_process(bridge_pid, BRIDGE_IDENTITY)
            return False, "Bridge server did not become ready in time.", None

        protocol_error = bridge_protocol_error()
        if protocol_error:
            kill_process(bridge_pid, BRIDGE_IDENTITY)
            return False, protocol_error, None

        set_admin_token = getattr(client_state, "set_admin_token", None)
        if callable(set_admin_token):
            set_admin_token(bridge_url, admin_token)
            client_state.save()

        session.reset_bridge()

    # Snapshot existing slot IDs before killing or launching processes.  This
    # lets replacement launch fail closed on slot-list errors without first
    # terminating the previous game.
    pre_launch_slot_list = session.list_slots()
    if pre_launch_slot_list is None:
        return False, (
            "Could not list bridge slots before launching. "
            "Restart the bridge/MCP session before launching."
        ), None
    replacement_game_pids.update(
        _same_game_slot_pids(pre_launch_slot_list, shim_game_id)
    )
    pre_launch_slots = {s.get("slot_id") for s in pre_launch_slot_list}

    # Stop any previous instance of THIS game (not other games).
    # In multi-game mode, other games may be running on the same bridge.
    # Skip when replace=False (multi-instance mode).
    if replace:
        pids = client_state.get_pids(bridge_url)
        if pids:
            # Only kill the old game PID if the bridge attributed it to this
            # game before slot cleanup. Don't touch the bridge — it may be
            # serving other games.
            old_game_pid = pids.get("game")
            try:
                old_game_pid_int = int(old_game_pid) if old_game_pid else None
            except (TypeError, ValueError):
                old_game_pid_int = None
            if (
                old_game_pid_int
                and old_game_pid_int in replacement_game_pids
                and _is_process_alive(old_game_pid_int)
            ):
                old_expect, _legacy_note = pid_identity_from_record(pids, "game")
                if not kill_process(old_game_pid_int, old_expect):
                    return False, (
                        f"Existing '{game_id}' process {old_game_pid_int} "
                        "is still alive after stop request. "
                        "Stop it manually before launching a replacement."
                    ), None

    # ---- Start game ----
    game_log = str(_runtime_log_dir(root) / "game_stdout.log")
    game_extra_env = {}
    if save_slot:
        game_extra_env["VNFLIGHT_SAVE_SLOT"] = save_slot
    # Pass bridge URL to the game so the shim connects to the right port.
    if port != DEFAULT_BRIDGE_PORT:
        game_extra_env["VNFLIGHT_BRIDGE_URL"] = bridge_url
    # Slot access token: the shim sends it as X-Slot-Token, and the bridge
    # reserves the game's slot with it at /slots/assign — after that,
    # reading state or consuming actions on the slot requires this token
    # or the bridge admin token.  ALWAYS minted and ALWAYS persisted in
    # ClientState: the stored admin token can be stale without anything
    # noticing (an open-mode bridge accepts admin ops regardless), and a
    # slot reserved under a stale admin token would otherwise lock out
    # every client on this machine — including the one that launched it.
    # Persisting the slot token is what keeps this launcher (and the
    # long-lived MCP client, via its 403 token refresh) inside its own
    # game on bridges whose admin token it doesn't actually hold, e.g. a
    # bridge started by the harness.
    slot_token: Optional[str] = (
        reservation_token or secrets.token_urlsafe(16)
    )
    launch_id = secrets.token_hex(16)
    # A warm protocol-launched game may consume the handoff before the URL
    # launcher subprocess is spawned, so the correlation window begins before
    # writing the launch file, not at Popen.
    launch_attempt_started_at = time.time()
    game_extra_env["VNFLIGHT_SLOT_TOKEN"] = slot_token
    game_extra_env["VNFLIGHT_LAUNCH_ID"] = launch_id
    # Shim diagnostics: per-game config, overridable per launch.
    effective_debug = (
        bool(debug) if debug is not None else bool((game or {}).get("debug"))
    )
    debug_logs_dir = (game or {}).get("debug_logs") or None
    if effective_debug:
        game_extra_env["VNFLIGHT_DEBUG"] = "1"
    if debug_logs_dir:
        game_extra_env["VNFLIGHT_DEBUG_LOGS"] = str(debug_logs_dir)
    set_slot_token = getattr(client_state, "set_slot_token", None)
    if callable(set_slot_token):
        set_slot_token(bridge_url, game_id, slot_token)
        client_state.save()

    # Launch-file handshake: launcher-mediated games (steam://, goggalaxy://)
    # do NOT inherit game_extra_env — the platform launcher starts the game
    # with ITS environment.  Write the same values into the game's game/
    # directory so the shim can pick them up regardless of launch path.
    launch_file_path, launch_file_warning = _write_launch_file(
        install_root,
        bridge_url,
        slot_token=slot_token,
        save_slot=save_slot,
        launch_id=launch_id,
        debug=effective_debug if (debug is not None or effective_debug) else None,
        debug_logs=debug_logs_dir,
    )
    # A warning no longer implies "not written": the claim-protocol timeout
    # writes the file AND warns, so branch on the path, not the warning.
    if launch_file_warning and not launch_file_path:
        if is_launcher:
            return False, (
                "Cannot launch through Steam/GOG without the vnflight launch "
                f"file: {launch_file_warning}. Fix the game install path or "
                "file permissions before retrying."
            ), None
        print(
            f"  Warning: launch file not written ({launch_file_warning}). "
            "Direct-exe launches still work via env, but Steam/GOG-mediated "
            "launches may not reach this bridge.",
            file=sys.stderr,
        )
    elif launch_file_warning:
        print(f"  Warning: {launch_file_warning}.", file=sys.stderr)
    if launch_file_path:
        add_launch_file = getattr(client_state, "add_launch_file", None)
        if callable(add_launch_file):
            add_launch_file(bridge_url, launch_file_path)
            client_state.save()

    game_pid, err = _launch_subprocess(
        game_cmd_parts, cwd=str(root), log_file=game_log,
        extra_env=game_extra_env if game_extra_env else None,
    )
    if not game_pid:
        return False, (
            f"Failed to start game: {err}. The command comes from the "
            f"'launch' key of '{game_id}' in {CONFIG_FILENAME}; check the "
            "executable path there."
        ), None

    # Save PIDs (cursor reset happens after slot assignment below). Preserve
    # the existing bridge PID when launching another game on an already-running
    # bridge; otherwise stop_game loses the bridge owner after mixed launches.
    pids: Dict[str, Any] = dict(client_state.get_pids(bridge_url) or {})
    pids["game"] = game_pid
    # Identity next to the pid: a later stop (possibly from another checkout
    # sharing this state file) kills only a process that still looks like
    # this game / this bridge.
    pids["game_expect"] = game_identity_expectation(
        game_id, game_cmd_parts, install_root, (game or {}).get("name"))
    if bridge_pid:
        pids["bridge"] = bridge_pid
    if pids.get("bridge"):
        # A preserved bridge pid from an earlier launch is a vnflight bridge
        # too; give it the identity if its record predates tracking.
        pids["bridge_expect"] = BRIDGE_IDENTITY
    client_state.set_pids(bridge_url, pids)
    client_state.save()

    # Wait for the game to connect to the bridge (appear in /slots). Treat
    # connect_timeout as a wall-clock bound: an iteration also contains HTTP,
    # so counting one-second sleeps can multiply the advertised timeout under
    # bridge contention.
    connect_wait_started_at = time.monotonic()
    effective_timeout = (
        90.0 if is_launcher else 30.0
    ) if connect_timeout is None else float(connect_timeout)
    connect_deadline = time.monotonic() + effective_timeout
    final_diagnostic_budget = min(2.0, effective_timeout / 4.0)
    poll_deadline = connect_deadline - final_diagnostic_budget

    def connect_timeout_message() -> str:
        message = "Game did not connect to the bridge in time."
        if is_launcher:
            message += (
                " Steam/GOG-mediated launches do not inherit the launcher's "
                "environment; the installed shim must understand the "
                f"{LAUNCH_FILE_NAME} handshake. If the game's shim predates "
                f"it, re-run `install-shim {game_id} --always-on`; an old "
                "installed shim ignores the launch file and dials the "
                "default bridge port."
            )
        return message

    reservation_id = hashlib.sha256(
        slot_token.encode("utf-8")
    ).hexdigest()[:16]
    receipt_path = (
        _launch_receipt_path(launch_file_path, launch_id)
        if launch_file_path else None
    )
    rejection_session = BridgeClient(bridge_url, token=slot_token)
    last_transient_registration_rejection: Optional[dict] = None

    def read_registration_receipt() -> dict:
        if receipt_path is None:
            return {}
        try:
            data = json.loads(receipt_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return {}
        return data if data.get("launch_id") == launch_id else {}

    def remove_registration_receipt() -> None:
        if receipt_path is not None:
            try:
                receipt_path.unlink()
            except OSError:
                pass

    def fail_connection(message: str, slot_id: Any = None):
        remove_registration_receipt()
        if diagnostics is not None:
            diagnostics["connect_failed_after_s"] = round(
                time.monotonic() - connect_wait_started_at, 3
            )
        return False, message, slot_id

    def current_registration_failure(
        rejection_timeout: float,
    ) -> Optional[dict[str, str]]:
        """Return a current launch failure from either diagnostic channel."""
        nonlocal last_transient_registration_rejection
        receipt = read_registration_receipt()
        if receipt.get("status") == "failed":
            reason = str(receipt.get("reason") or "shim registration failed")
            return {"source": "receipt", "reason": reason, "message": reason}
        read_rejection = getattr(
            rejection_session, "registration_rejection", None,
        )
        if callable(read_rejection) and rejection_timeout > 0:
            try:
                rejection_result = read_rejection(
                    timeout=rejection_timeout,
                    game_id=shim_game_id,
                    launch_id=launch_id,
                    launch_started_at=launch_attempt_started_at,
                )
            except TypeError:
                # Test/dummy clients may expose the pre-filter signature.
                rejection_result = read_rejection(timeout=rejection_timeout)
            rejection_read_succeeded = rejection_result is not None
            rejection = rejection_result or {}
            if _registration_rejection_belongs_to_launch(
                rejection,
                game_id=shim_game_id,
                launch_id=launch_id,
                launch_started_at=launch_attempt_started_at,
            ):
                if rejection.get("transient") is True:
                    last_transient_registration_rejection = dict(rejection)
                else:
                    last_transient_registration_rejection = None
            elif rejection_read_succeeded:
                last_transient_registration_rejection = None
            if _registration_rejection_matches(
                rejection,
                game_id=shim_game_id,
                launch_id=launch_id,
                launch_started_at=launch_attempt_started_at,
            ):
                reason = str(
                    rejection.get("reason") or "shim registration failed"
                )
                return {
                    "source": "bridge",
                    "reason": reason,
                    "message": str(rejection.get("message") or reason),
                }
        # The shim can write its process-owned receipt while the bridge read
        # above is in flight. Recheck the local channel before returning.
        receipt = read_registration_receipt()
        if receipt.get("status") == "failed":
            reason = str(receipt.get("reason") or "shim registration failed")
            return {"source": "receipt", "reason": reason, "message": reason}
        return None

    poll_i = 0
    our_slot = None
    registered_slot = None
    mismatched_slots: dict[Any, dict] = {}
    persisted_slot_id = None

    def observe_slot_list(slot_list: list[dict]) -> Optional[str]:
        """Update launch ownership from one authoritative slot snapshot."""
        nonlocal our_slot, registered_slot, persisted_slot_id
        collisions = _normalized_game_id_collision(slot_list, shim_game_id)
        if collisions:
            return (
                f"Ambiguous normalized game id for '{game_id}': "
                f"{', '.join(sorted(collisions))}. Use a slot id or resolve "
                "the bridge slot collision before launching."
            )
        registered_slot = next(
            (s for s in slot_list
             if _game_ids_match(s.get("game_id"), shim_game_id)
             and s.get("slot_id") not in pre_launch_slots
             and s.get("reservation_id") == reservation_id),
            None,
        )
        current_mismatches: dict[Any, dict] = {}
        for candidate in slot_list:
            candidate_id = candidate.get("slot_id")
            if (
                _game_ids_match(candidate.get("game_id"), shim_game_id)
                and candidate_id not in pre_launch_slots
                and candidate.get("reservation_id") != reservation_id
            ):
                current_mismatches[candidate_id] = candidate
        mismatched_slots.clear()
        mismatched_slots.update(current_mismatches)
        if (
            registered_slot
            and registered_slot.get("slot_id") is not None
            and registered_slot.get("slot_id") != persisted_slot_id
            and callable(set_slot_token)
        ):
            persisted_slot_id = registered_slot["slot_id"]
            try:
                set_slot_token(
                    bridge_url, game_id, slot_token,
                    slot_id=persisted_slot_id,
                )
            except TypeError:
                set_slot_token(bridge_url, game_id, slot_token)
            client_state.save()
        if registered_slot and registered_slot.get("event_counter", 0) > 0:
            our_slot = registered_slot
            session.slot_prefix = "/" + str(our_slot["slot_id"])
            game_reported_pid = our_slot.get("game_pid")
            if game_reported_pid:
                pids["game"] = game_reported_pid
                client_state.set_pids(bridge_url, pids)
                client_state.save()
        return None

    while time.monotonic() < poll_deadline:
        remaining = poll_deadline - time.monotonic()
        if remaining <= 0:
            break
        time.sleep(min(1.0, remaining))
        remaining = poll_deadline - time.monotonic()
        if remaining <= 0:
            break
        failure = current_registration_failure(min(1.0, remaining))
        if failure:
            remaining = poll_deadline - time.monotonic()
            if remaining > 0:
                failure_slots = None
                try:
                    failure_slots = session.list_slots(
                        timeout=min(3.0, remaining),
                    )
                except TypeError:
                    if remaining >= 3.0:
                        failure_slots = session.list_slots()
                if failure_slots is not None:
                    failure_slot_error = observe_slot_list(failure_slots or [])
                    if failure_slot_error:
                        return fail_connection(failure_slot_error)
                    if (
                        our_slot
                        and failure["source"] == "bridge"
                    ):
                        late_receipt = read_registration_receipt()
                        if late_receipt.get("status") == "failed":
                            reason = str(
                                late_receipt.get("reason")
                                or "shim registration failed"
                            )
                            return fail_connection(
                                f"Game shim registration failed: {reason}",
                                our_slot.get("slot_id"),
                            )
                        # An exact-reservation ready slot is authoritative. The
                        # successful assignment clears its own diagnostics
                        # atomically, so one read immediately before this
                        # snapshot was stale or belonged to a sibling process.
                        # Failed shim receipts remain authoritative.
                        break
            slot_id = (
                registered_slot.get("slot_id") if registered_slot else None
            )
            return fail_connection(
                f"Game shim registration failed: {failure['message']}", slot_id,
            )
        remaining = poll_deadline - time.monotonic()
        if remaining <= 0:
            break
        try:
            slot_list = session.list_slots(
                timeout=min(3.0, remaining))
        except TypeError:
            # Test/dummy clients may expose the pre-timeout signature. Never
            # start that fixed 3s request with less than its full budget.
            if remaining < 3.0:
                break
            slot_list = session.list_slots()
        if slot_list is not None:
            slot_error = observe_slot_list(slot_list or [])
            if slot_error:
                return fail_connection(slot_error)
        receipt = read_registration_receipt()
        if receipt.get("status") == "failed":
            reason = receipt.get("reason") or "shim registration failed"
            slot_id = (
                registered_slot.get("slot_id") if registered_slot else None
            )
            return fail_connection(
                f"Game shim registration failed: {reason}", slot_id,
            )
        if our_slot:
            break
        if poll_i == 15 and is_launcher:
            print(
                "  (waiting for launcher to start the game...)",
                file=sys.stderr,
            )
        poll_i += 1

    # Reserve a small piece of the advertised connect budget for one final,
    # gap-free observation. A rejection or receipt can land after the last
    # regular poll, and a slot can become ready during that diagnostic read.
    if not our_slot:
        remaining = max(0.0, connect_deadline - time.monotonic())
        final_slot_error = None
        if remaining > 0:
            final_slot_list = None
            slot_timeout = min(final_diagnostic_budget / 2.0, remaining)
            try:
                final_slot_list = session.list_slots(
                    timeout=slot_timeout,
                )
            except TypeError:
                # Compatibility for test/dummy clients with an unbounded
                # legacy signature. Do not violate the wall-clock contract.
                if slot_timeout >= 3.0:
                    final_slot_list = session.list_slots()
            if final_slot_list is not None:
                final_slot_error = observe_slot_list(final_slot_list or [])
        remaining = max(0.0, connect_deadline - time.monotonic())
        final_failure = current_registration_failure(remaining)
        if final_failure and not (
            our_slot and final_failure["source"] == "bridge"
        ):
            slot_id = (
                registered_slot.get("slot_id") if registered_slot else None
            )
            return fail_connection(
                "Game shim registration failed: "
                f"{final_failure['message']}",
                slot_id,
            )
        if final_slot_error:
            return fail_connection(final_slot_error)

    if our_slot:
        remove_registration_receipt()
    if not our_slot:
        if registered_slot and registered_slot.get("slot_id") is not None:
            slot_id = registered_slot["slot_id"]
            return fail_connection((
                f"Game registered as slot {slot_id}, but did not become "
                "ready before the connection deadline. Stop that slot "
                "before retrying launch."
            ), slot_id)
        receipt = read_registration_receipt()
        launched_pid = pids.get("game")
        receipt_pid = receipt.get("game_pid")
        owned_mismatch = next(
            (s for s in mismatched_slots.values()
             if s.get("game_pid") in (launched_pid, receipt_pid)
             and s.get("game_pid") is not None),
            None,
        )
        if owned_mismatch:
            return fail_connection((
                "Game connected without this launch reservation. Check that "
                "the launch file is writable and reinstall the shim before "
                "retrying."
            ), owned_mismatch.get("slot_id"))
        if mismatched_slots:
            return fail_connection(
                "A new same-game slot connected with a different launch "
                "reservation. It was not adopted or stopped; another launch "
                "may be running concurrently."
            )
        if last_transient_registration_rejection:
            first_seen = float(
                last_transient_registration_rejection.get("first_rejected_at")
                or last_transient_registration_rejection.get("rejected_at")
                or time.time()
            )
            pending_for = max(0, int(time.time() - first_seen))
            reason = (
                last_transient_registration_rejection.get("message")
                or last_transient_registration_rejection.get("reason")
                or "reservation handoff is still pending"
            )
            return fail_connection(
                "Game shim registration is still retrying a reservation "
                f"handoff after {pending_for}s: {reason} Stop the conflicting "
                "slot or restart its bridge before retrying launch."
            )
        return fail_connection(connect_timeout_message())

    # Connection and setup are separate phases. A slot may publish on the
    # final connection poll, but required bridge policy (and the requested
    # launch mode) must still be applied before launch can report success.
    # MCP callers reserve this five-second window in their child deadline.
    setup_deadline = time.monotonic() + 5.0
    assigned_slot = our_slot["slot_id"]
    if diagnostics is not None:
        diagnostics["connected_after_s"] = round(
            time.monotonic() - connect_wait_started_at, 3
        )
    def fail_post_connect_setup(message: str):
        """Report a partial launch without risking deadline-unsafe cleanup.

        Process liveness is not reliably tri-state on Windows: a timed-out
        tasklist probe looks the same as a dead process. Keep the known slot
        and persisted PID intact so the caller has a durable recovery target.
        """
        return False, (
            f"{message} Slot {assigned_slot} is connected but not ready; "
            "stop it before retrying launch."
        ), assigned_slot

    # Reset cursor for this slot's fresh session.
    state_key = bridge_url + session.slot_prefix
    client_state.set_cursor(state_key, 0)
    client_state.set_last_request_id(state_key, None)
    client_state.save()

    # Push per-game bridge config (POST /config) now that the slot exists —
    # e.g. end_on_menu_return=false for games whose gameplay screens are
    # classified as main_menu (Slay the Princess) so the return-to-menu
    # ending heuristic doesn't falsely end the run.
    bridge_config = game.get("bridge_config") or {}
    remaining = setup_deadline - time.monotonic()
    if bridge_config and remaining > 0:
        result = session.set_config(
            bridge_config, deadline=time.time() + remaining)
        if not result.get("ok"):
            return fail_post_connect_setup(
                f"Game connected, but required bridge config "
                f"{bridge_config!r} was not applied."
            )
    elif bridge_config:
        return fail_post_connect_setup(
            "Game connected, but bridge setup timed out.")

    remaining = setup_deadline - time.monotonic()
    if fast_forward and remaining > 0:
        ok, message = session._send_command(
            "fast_forward_on", timeout=min(15.0, remaining))
        if not ok:
            return fail_post_connect_setup(
                f"Game connected, but fast-forward setup failed: {message}")
    elif auto_advance and remaining > 0:
        ok, message = session._send_command(
            "auto_advance_on", timeout=min(15.0, remaining))
        if not ok:
            return fail_post_connect_setup(
                f"Game connected, but auto-advance setup failed: {message}")
    elif fast_forward or auto_advance:
        return fail_post_connect_setup(
            "Game connected, but launch-mode setup timed out.")

    msg = f"Launched '{game_id}'"
    if assigned_slot is not None:
        msg += f" (slot {assigned_slot})"
    if fast_forward:
        msg += " (fast-forward on)"
    if _shim_note:
        msg += f"\n{_shim_note}"
    return True, msg, assigned_slot


def stop_game(bridge_url: str, client_state: ClientState) -> Tuple[bool, str]:
    """Stop the running game and bridge."""
    # Local import to avoid module-level dependency on .client
    # (intra-package import stripped by build)
    pass

    get_admin_token = getattr(client_state, "get_admin_token", None)
    admin_token = get_admin_token(bridge_url) if callable(get_admin_token) else None
    session = (
        BridgeClient(bridge_url, token=admin_token)
        if admin_token
        else BridgeClient(bridge_url)
    )
    messages: list[str] = []

    # Snapshot liveness BEFORE the quit command: a process that dies
    # during the post-quit grace sleep exited because our quit worked —
    # that must read as a successful stop, not "already stopped".
    pids = client_state.get_pids(bridge_url) or {}
    alive_before_quit = {
        name: bool(pids.get(name) and _is_process_alive(pids.get(name)))
        for name in ("game", "bridge")
    }

    # Try sending quit command through the bridge.
    quit_sent = False
    if session.is_up():
        session._send_command("quit")
        quit_sent = True
        time.sleep(1.0)

    # Kill processes by PID.
    remaining_pids: dict = {}
    failed = False

    for name in ("game", "bridge"):
        pid = pids.get(name)
        if pid and _is_process_alive(pid):
            expect, legacy_note = pid_identity_from_record(pids, name)
            if kill_process(pid, expect):
                messages.append(f"Stopped {name} (PID {pid}){legacy_note}")
            else:
                failed = True
                remaining_pids[name] = pid
                stored_expect = pids.get(f"{name}_expect")
                if stored_expect:
                    remaining_pids[f"{name}_expect"] = stored_expect
                messages.append(
                    f"Failed to stop {name} (PID {pid}): process still alive "
                    f"or refused (not a matching process){legacy_note}"
                )
        elif pid:
            if quit_sent and alive_before_quit.get(name):
                messages.append(
                    f"Stopped {name} (PID {pid}) — exited cleanly on quit"
                )
            else:
                messages.append(f"{name.title()} (PID {pid}) already stopped")

    client_state.set_pids(bridge_url, remaining_pids if failed else {})
    if not failed:
        clear_slot_tokens = getattr(client_state, "clear_slot_tokens", None)
        if callable(clear_slot_tokens):
            clear_slot_tokens(bridge_url)
    client_state.save()

    # Launch-file hygiene: remove the handshake files written for this
    # bridge's launches.  Best-effort only — the shim's freshness window
    # is the real guard against a stale file steering a later launch.
    get_launch_files = getattr(client_state, "get_launch_files", None)
    if callable(get_launch_files):
        for launch_file in get_launch_files(bridge_url):
            _remove_launch_file_if_owned(launch_file, bridge_url)
        clear_launch_files = getattr(client_state, "clear_launch_files", None)
        if callable(clear_launch_files):
            clear_launch_files(bridge_url)
            client_state.save()

    if not messages:
        return True, "No processes to stop."
    return not failed, "; ".join(messages)


# ---------------------------------------------------------------------------
# Prompt generation
# ---------------------------------------------------------------------------


def generate_prompt(game: dict) -> str:
    """Generate a system prompt for an LLM agent playing a game."""
    briefing = game.get("briefing", "").strip()
    game_id = game.get("id", "unknown")
    game_name = game.get("name", game_id)

    lines = [
        f'You are about to play "{game_name}", a Ren\'Py visual novel.',
        "",
    ]

    if briefing:
        lines.append(briefing)
        lines.append("")

    lines.extend(
        [
            "## Instructions",
            "",
            "You are playing this visual novel using the `vnflight.py` command-line tool.",
            "Your available commands are:",
            "",
            "  python vnflight.py wait          — Watch the story unfold; stops when a choice is needed",
            "  python vnflight.py autoplay      — Enable auto-advance and watch the story unfold",
            "  python vnflight.py act <target> [--wait] — Pick a visible choice or screen button",
            "  python vnflight.py input <text> [--wait] — Provide text input when asked",
            "  python vnflight.py state          — Check current game state (stats, evidence, context)",
            "  python vnflight.py history         — Review recent dialogue",
            "  python vnflight.py cmd <name> [--wait] — Send a game command (start, save, load, etc.)",
            "",
            "## How to Play",
            "",
            "1. Start the game:",
            f"     python vnflight.py launch {game_id} --auto",
            "     python vnflight.py act start --wait",
            "",
            "2. Watch the story and make choices:",
            "     python vnflight.py wait",
            "     (read the output, then when a CHOICE REQUIRED appears:)",
            "     python vnflight.py act 1 --wait",
            "",
            "3. Repeat step 2 until the game ends.",
            "",
            "4. If the game shows buttons on screen (reported in 'state' or as screen_content events),",
            "   select them with the same command:",
            '     python vnflight.py act "Continue" --wait',
            "     python vnflight.py act 2 --wait          (by visible 1-based action index)",
            "",
            "## Important Rules",
            "",
            "- Read dialogue and narration carefully before making choices.",
            "- Consider character motivations and any evidence/stats provided.",
            "- Use 'state' to review your inventory and stats for difficult decisions.",
            "- Do NOT read any game source files (*.rpy, *.rpyc) — this would spoil the story.",
            "- All information you need comes through game events and this briefing.",
            "- Play authentically — make choices based on the narrative, not on trying",
            "  to find a 'best' ending.",
        ]
    )

    return "\n".join(lines)

# ======================================================================
# Module: format.py
# ======================================================================





_IS_WINDOWS = platform.system() == "Windows"

# ---------------------------------------------------------------------------
# ANSI colour helpers
# ---------------------------------------------------------------------------


def _colour(text: str, code: str) -> str:
    """Wrap *text* in ANSI colour codes (no-op if stdout is not a TTY)."""
    if not hasattr(sys.stdout, "isatty") or not sys.stdout.isatty():
        return text
    if _IS_WINDOWS:
        # Enable ANSI on Windows 10+ by setting the console mode.
        try:
            import ctypes

            kernel32 = ctypes.windll.kernel32  # type: ignore[attr-defined]
            kernel32.SetConsoleMode(kernel32.GetStdHandle(-11), 7)
        except Exception:
            return text
    return f"\033[{code}m{text}\033[0m"


def _green(t: str) -> str:
    return _colour(t, "32")


def _yellow(t: str) -> str:
    return _colour(t, "33")


def _red(t: str) -> str:
    return _colour(t, "31")


def _cyan(t: str) -> str:
    return _colour(t, "36")


def _dim(t: str) -> str:
    return _colour(t, "2")


def _bold(t: str) -> str:
    return _colour(t, "1")


def _display_text(value: Any) -> str:
    """Normalize Ren'Py escaped text for agent/CLI display."""
    return str(value).replace("%%", "%")


_RENPY_TEXT_TAG_RE = re.compile(r"\{/?[a-zA-Z_]+[^{}]*\}")


def _strip_renpy_text_tags(value: Any) -> str:
    """Drop Ren'Py text tags ({color=...}, {b}, {/i}, ...) from display text.

    Menu captions reach the bridge raw (the shim cleans selectable labels,
    not prompt lines), so an epilogue caption rendered as
    ``{color=#f6d6bd}Old Págos{/color}``. ``{{`` is Ren'Py's escaped brace.
    """
    text = str(value if value is not None else "")
    text = text.replace("{{", "\x00")
    text = _RENPY_TEXT_TAG_RE.sub("", text)
    return text.replace("\x00", "{")


def _story_echo_key(value: Any) -> str:
    """Comparison key for 'this prompt repeats that story line'."""
    return " ".join(_strip_renpy_text_tags(_display_text(value)).split()).lower()


def _normalize_input_prompt(prompt: Any) -> str:
    """Normalize input prompt text for display."""
    return _display_text(prompt if prompt is not None else "Enter text")


def _is_menu_prompt_echo(text: str) -> bool:
    """Return True for generic menu prompt lines repeated as dialogue."""
    lowered = text.strip().lower()
    if not lowered:
        return False
    exact_prompts = {
        "what do you do?",
        "what do i do?",
        "how do you respond?",
    }
    if lowered in exact_prompts:
        return True
    prompt_fragments = (
        "what do you do?",
        "what do i do?",
        "how do you respond?",
    )
    if any(fragment in lowered for fragment in prompt_fragments):
        return True
    if lowered.startswith("which ") and lowered.endswith(" do you choose?"):
        return True
    if lowered.endswith(" waits for your order."):
        return True
    return False


def _drop_menu_prompt_echoes(
    events: list[dict],
    pending: dict | None = None,
) -> list[dict]:
    """Drop prompt-like dialogue lines adjacent to choice prompts."""
    if not events:
        return events
    pending_is_choice = bool(
        pending and pending.get("type") in ("choice_request", "choices", "choice")
    )
    filtered: list[dict] = []
    for idx, ev in enumerate(events):
        etype = ev.get("type")
        if etype in ("dialogue", "narration"):
            text = ev.get("text") or ev.get("what") or ""
            if _is_menu_prompt_echo(_display_text(text)):
                next_ev = events[idx + 1] if idx + 1 < len(events) else None
                next_is_choice = bool(
                    next_ev
                    and next_ev.get("type") in ("choice_request", "choices")
                )
                if next_is_choice or (idx == len(events) - 1 and pending_is_choice):
                    continue
        filtered.append(ev)
    return filtered


# ---------------------------------------------------------------------------
# Wait result: raw events -> structured data
# ---------------------------------------------------------------------------

def build_wait_data(events: list[dict], pending: dict | None = None,
                    ended: bool = False) -> dict:
    """Build structured wait data from raw bridge events.

    This is the canonical intermediate format -- formatters consume
    this to produce output for different targets.
    """
    story: list[dict] = []
    status: dict[str, list] = {"stats": [], "auto_skipped": [], "resolved": []}
    buttons: list[dict] = []
    events = _drop_menu_prompt_echoes(events, pending)
    incremental_inventory_additions: list[str] = []

    for ev in events:
        etype = ev.get("type", "")
        source_id = ev.get("_source_id")
        source_seq = ev.get("_source_seq")
        bridge_seq = ev.get("_seq")
        occurrence_prefix = None
        if type(source_seq) is int:
            occurrence_prefix = (
                f"source:{source_id}:{source_seq}"
                if isinstance(source_id, str) and source_id
                else f"source:{source_seq}"
            )
        elif type(bridge_seq) is int:
            occurrence_prefix = f"bridge:{bridge_seq}"

        if etype == "dialogue":
            who = ev.get("character") or ev.get("who") or "Narrator"
            text = _display_text(ev.get("text") or ev.get("what", ""))
            user = ev.get("user_initiated", False)
            item = {"type": "dialogue", "character": who, "text": text,
                    **({"user": True} if user else {})}
            delivery_id = ev.get("overlay_delivery_id")
            if type(delivery_id) is int:
                item["overlay_delivery_id"] = delivery_id
                item["passive_overlay_snapshot"] = True
                item["_occurrence_id"] = f"overlay:{delivery_id}"
            if occurrence_prefix:
                item.setdefault("_occurrence_id", occurrence_prefix)
            if type(bridge_seq) is int:
                item["_bridge_seq"] = bridge_seq
            story.append(item)

        elif etype == "narration":
            text = _display_text(ev.get("text", ""))
            if text.strip():
                item = {"type": "narration", "text": text}
                delivery_id = ev.get("overlay_delivery_id")
                if type(delivery_id) is int:
                    item["overlay_delivery_id"] = delivery_id
                    item["passive_overlay_snapshot"] = True
                    item["_occurrence_id"] = f"overlay:{delivery_id}"
                if occurrence_prefix:
                    item.setdefault("_occurrence_id", occurrence_prefix)
                if type(bridge_seq) is int:
                    item["_bridge_seq"] = bridge_seq
                story.append(item)

        elif etype == "stats_update":
            if ev.get("post_terminal"):
                # Ren'Py reset its store on the return to the menu: every
                # stat "changed" back to its default.  The bridge tagged the
                # event; rendering the phantom deltas reads as an unearned
                # end-of-run reset (the same false report the game_state
                # freeze exists to prevent).
                continue
            changed = ev.get("changed", {})
            previous = ev.get("previous", {})
            removed = set(ev.get("removed") or [])
            full_stats = ev.get("stats")
            if (
                isinstance(full_stats, dict)
                and full_stats.get("_suppress_brief")
            ):
                # A game can retire its compact progress surface at a story
                # boundary. Suppress only keys removed by that teardown;
                # semantic Act 3 evidence/resource changes remain visible.
                teardown_names = removed | {
                    key for key in changed if key not in full_stats
                }
                changed = {
                    key: value for key, value in changed.items()
                    if key not in teardown_names
                }
                previous = {
                    key: value for key, value in previous.items()
                    if key in changed
                }
                removed = set()
                if not changed:
                    continue
            for k, v in changed.items():
                if k.startswith("_"):
                    continue
                entry: dict[str, Any] = {"stat": k, "value": v}
                if (
                    k in removed
                    or (isinstance(full_stats, dict) and k not in full_stats)
                    or (
                        not isinstance(full_stats, dict)
                        and k in previous
                        and previous[k] is not None
                        and v is None
                    )
                ):
                    # Null is a valid stat value. Explicit removal provenance
                    # (or absence from the accompanying full map) is what
                    # distinguishes a deleted key.
                    entry["delta"] = "removed"
                elif k in previous:
                    old = previous[k]
                    try:
                        entry["delta"] = v - old
                    except (TypeError, ValueError):
                        pass
                status["stats"].append(entry)

        elif etype == "auto_skipped":
            label = ev.get("label", ev.get("text", ""))
            if label:
                status["auto_skipped"].append(label)

        elif etype == "request_resolved":
            chosen = ev.get("value") or ev.get("chosen_label") or ev.get("label", ev.get("choice", ""))
            by = ev.get("by", "agent")
            if chosen:
                status["resolved"].append({"label": chosen, "by": by})

        elif etype == "user_choice":
            label = ev.get("label", "")
            if label:
                status["resolved"].append({"label": label, "by": "user"})

        elif etype == "anomaly":
            kind = ev.get("kind", "unknown")
            msg = ev.get("message", ev.get("details", {}).get("message", ""))
            # Anomalies go to status, not story — they're diagnostic noise.
            status.setdefault("anomalies", []).append("%s: %s" % (kind, msg))

        elif etype == "screen_text":
            # Modal screen text (dialog/confirm popups) — surface as narration.
            delivery_ids = ev.get("overlay_delivery_ids") or []
            for index, t in enumerate(ev.get("texts", [])):
                t = _display_text(t).strip()
                if t:
                    item = {"type": "narration", "text": t,
                            "source": "screen_text"}
                    if ev.get("passive_overlay_snapshot"):
                        item["passive_overlay_snapshot"] = True
                    if index < len(delivery_ids):
                        item["overlay_delivery_id"] = delivery_ids[index]
                        item["_occurrence_id"] = (
                            f"overlay:{delivery_ids[index]}")
                    elif occurrence_prefix:
                        item["_occurrence_id"] = (
                            f"{occurrence_prefix}:row:{index}")
                    if type(bridge_seq) is int:
                        item["_bridge_seq"] = bridge_seq
                    story.append(item)

        elif etype == "inventory_update":
            if ev.get("post_terminal"):
                # Post-menu-return store reset — see stats_update above.
                continue
            items = ev.get("changed")
            incremental = items is not None
            if items is None:
                items = ev.get("items")
            if items is None:
                # The live shim sends its full snapshot as `inventory`;
                # bridge/tests may use the normalized `items` spelling.
                items = ev.get("inventory", [])
            names = _inventory_display_names(items)
            if incremental:
                removed_names = _inventory_display_names(
                    ev.get("removed", []))
                unmatched_changed = list(names)
                unmatched_removed = []
                for name in removed_names:
                    if name in unmatched_changed:
                        # Same-name replacement is usually a quantity or
                        # metadata update, not an acquisition plus removal.
                        unmatched_changed.remove(name)
                    else:
                        unmatched_removed.append(name)
            if incremental:
                inventory_status = status.setdefault("inventory", [])
                # Inventory is state, not an occurrence transcript. A single
                # wait can observe an item being introduced and then replaced.
                # Net those transitions while retaining unmatched removals for
                # items that may predate this event batch.
                eligible_changed = list(unmatched_changed)
                for name in names:
                    removed_marker = name + " (removed)"
                    try:
                        prior_index = len(inventory_status) - 1 - list(
                            reversed(inventory_status)).index(removed_marker)
                    except ValueError:
                        pass
                    else:
                        del inventory_status[prior_index]
                    inventory_status.append(name)
                    if name in eligible_changed:
                        eligible_changed.remove(name)
                        incremental_inventory_additions.append(name)
                for name in unmatched_removed:
                    cancellable = name in incremental_inventory_additions
                    if cancellable:
                        incremental_inventory_additions.remove(name)
                    try:
                        prior_index = len(inventory_status) - 1 - list(
                            reversed(inventory_status)).index(name)
                    except ValueError:
                        prior_index = None
                    if prior_index is not None:
                        del inventory_status[prior_index]
                    if not cancellable:
                        inventory_status.append(name + " (removed)")
            else:
                # Legacy events carry complete snapshots; the newest one,
                # including an empty snapshot, supersedes any earlier one.
                status["inventory"] = names
                incremental_inventory_additions = []

    # Dedup buttons by label+screen.
    if buttons:
        seen: set[tuple[str, str]] = set()
        unique_buttons: list[dict] = []
        for b in buttons:
            key = (b["label"], b.get("screen", ""))
            if key not in seen:
                seen.add(key)
                unique_buttons.append(b)
        buttons = unique_buttons

    # A single wait can contain several updates for the same stat.  Report the
    # final value and net numeric delta once; rendering every intermediate
    # sample makes ordinary progress look like duplicated state.
    if status["stats"]:
        coalesced: dict[str, dict[str, Any]] = {}
        order: list[str] = []
        for entry in status["stats"]:
            name = entry["stat"]
            if name not in coalesced:
                coalesced[name] = dict(entry)
                order.append(name)
                continue
            merged = coalesced[name]
            merged["value"] = entry.get("value")
            old_delta = merged.get("delta")
            new_delta = entry.get("delta")
            if (
                isinstance(old_delta, (int, float))
                and isinstance(new_delta, (int, float))
            ):
                merged["delta"] = old_delta + new_delta
            elif "delta" in entry:
                merged["delta"] = new_delta
            else:
                # The final update re-added/retyped the stat without a
                # composable delta. Do not retain an earlier removal or
                # numeric transition that no longer describes its value.
                merged.pop("delta", None)
        status["stats"] = [coalesced[name] for name in order]

    # Strip empty status sections.
    status = {k: v for k, v in status.items() if v}

    out: dict[str, Any] = {"story": story}
    if status:
        out["status"] = status
    if pending:
        out["pending"] = _build_pending(pending)
        out["_pending_raw"] = pending
    if buttons:
        out["buttons"] = buttons
    if ended:
        out["ended"] = True
    if not out.get("story") and not out.get("pending") and not out.get("buttons"):
        pass  # Empty result -- caller decides what to show.
    return out


def _build_pending(raw: dict) -> dict:
    """Convert raw pending request to structured format."""
    ptype = raw.get("type", "")
    if ptype in ("choice_request", "choices"):
        choices = raw.get("choices", [])
        full_items = raw.get("full_items", [])
        pending_choices = []
        # Build choice ID lookup from choices list (may have {id, label}
        # dicts set by the augmenter pipeline). Key by the ENABLED-choice
        # ordinal — the same basis as choice_idx below — so a disabled or
        # caption row in `choices` (synthesized pendings where
        # choices == full_items) can't shift ids onto the wrong option.
        choice_ids: dict[int, str] = {}
        _cid_ordinal = 0
        for ch in choices:
            if isinstance(ch, dict):
                if _is_suppressed_pending_choice(ch):
                    continue
                if item_is_disabled(ch) or ch.get("is_caption"):
                    continue
                _cid_ordinal += 1
                if ch.get("id"):
                    choice_ids[_cid_ordinal] = str(ch["id"])
            else:
                _cid_ordinal += 1  # plain string = enabled choice
        # Use full_items when available — it includes disabled/caption
        # entries that choices list may omit.
        source = full_items if full_items else choices
        choice_idx = 0
        for i, item in enumerate(source):
            if _is_suppressed_pending_choice(item):
                continue
            if isinstance(item, dict):
                label = item.get("label", str(item))
                is_disabled = item_is_disabled(item)
                is_caption = item.get("is_caption", False)
                annotation = item.get("annotation")
            else:
                # Simple string from choices list.
                label = str(item)
                is_disabled = False
                is_caption = False
                annotation = None
            # Skip shim placeholder disabled entries (empty label or
            # literal "(disabled)" sentinel) — they carry no info.
            _stripped = (label or "").strip()
            if is_disabled and (not _stripped or _stripped == "(disabled)"):
                continue
            entry: dict[str, Any] = {"label": label}
            # Captions are menu prompt text, not selectable options — the
            # shim excludes them from its enabled-only numeric map, so they
            # must not consume an agent-visible number here either (doing so
            # shifted every following choice/button off by one).
            if is_disabled or is_caption:
                entry["disabled"] = bool(is_disabled)
                entry["index"] = None
            else:
                choice_idx += 1
                entry["index"] = choice_idx
                cid = choice_ids.get(choice_idx)
                if cid:
                    entry["id"] = cid
            if is_caption:
                entry["caption"] = True
            if annotation:
                entry["annotation"] = annotation
            pending_choices.append(entry)
        result = {"type": "choice", "id": raw.get("id", ""),
                  "choices": pending_choices}
        interactions = raw.get("interactions")
        if isinstance(interactions, list):
            promoted_actions = _promoted_actions_from_interactions(
                interactions
            )
            interaction_actions = _interaction_actions_from_interactions(
                interactions,
                display_index_offset=choice_idx,
            )
        else:
            promoted_actions = _promoted_actions_from_buttons(
                raw.get("promoted_buttons") or []
            )
            interaction_actions = []
        promoted_ids = {
            action.get("id")
            for action in promoted_actions
            if action.get("id") is not None
        }
        promoted_labels = {
            str(action.get("label") or "").strip()
            for action in promoted_actions
            if str(action.get("label") or "").strip()
        }
        for action in interaction_actions:
            action_id = action.get("id")
            label = str(action.get("label") or "").strip()
            if (
                (action_id is not None and action_id in promoted_ids)
                or (action_id is None and label in promoted_labels)
            ):
                continue
            promoted_actions.append(action)
        if promoted_actions:
            result["actions"] = promoted_actions
        # Carry game-registered category metadata (headers / compact flags)
        # so the pending renderer can group trailing non-choice actions under
        # their category header the same way state()'s screen rendering does.
        button_categories = raw.get("button_categories")
        if isinstance(button_categories, dict) and button_categories:
            result["_button_categories"] = button_categories
        # Tag auto-advancing choices so agents know not to act.
        # The shim is authoritative here; a single visible choice can still
        # require manual action when auto-skip is paused or blocked.
        if raw.get("_auto_advancing"):
            result["auto_advancing"] = True
        return result
    elif ptype == "input_request":
        default = (
            raw.get("default")
            or raw.get("value")
            or raw.get("current")
            or raw.get("text")
            or ""
        )
        return {"type": "input", "id": raw.get("id", ""),
                "prompt": _normalize_input_prompt(raw.get("prompt", "Enter text")),
                "default": default}
    return {"type": ptype}


def _promoted_actions_from_interactions(interactions: list) -> list[dict]:
    actions = []
    for interaction in interactions or []:
        if not isinstance(interaction, dict) or not interaction.get("promoted"):
            continue
        if _is_suppressed_pending_action(interaction):
            continue
        if item_is_default_focus_chrome(interaction):
            continue
        if item_is_disabled(interaction):
            continue
        label = _button_display_label(interaction)
        if not str(label).strip():
            continue
        action: dict[str, Any] = {"label": label}
        if interaction.get("annotation"):
            action["annotation"] = interaction["annotation"]
        if interaction.get("id") is not None:
            action["id"] = interaction["id"]
        actions.append(action)
    return actions


def _promoted_actions_from_buttons(buttons: list) -> list[dict]:
    actions = []
    for button in buttons or []:
        if not isinstance(button, dict):
            continue
        if _is_suppressed_pending_action(button):
            continue
        if item_is_default_focus_chrome(button):
            continue
        if item_is_disabled(button):
            continue
        label = _button_display_label(button)
        if not str(label).strip():
            continue
        action: dict[str, Any] = {"label": label}
        if button.get("annotation"):
            action["annotation"] = button["annotation"]
        if button.get("id") is not None:
            action["id"] = button["id"]
        actions.append(action)
    return actions


def _is_suppressed_pending_action(item: dict) -> bool:
    """Return True when a mod marked an auxiliary pending action as stale."""
    return bool(
        item.get("_suppress_pending_action")
        or item.get("suppress_pending_action")
    )


def _is_suppressed_pending_choice(item: Any) -> bool:
    """Return True when a mod marked a choice as a non-actionable container."""
    return isinstance(item, dict) and bool(
        item.get("_suppress_pending_choice")
        or item.get("suppress_pending_choice")
    )


def _interaction_actions_from_interactions(
    interactions: list,
    *,
    display_index_offset: int = 0,
) -> list[dict]:
    """Return non-choice visible interactions as agent-facing actions.

    Disabled non-choice interactions are kept (tagged disabled) so the
    pending renderer can show them grouped under their category header the
    same way state() does (e.g. a quick-menu "Wait (disabled)").  They are
    never counted as actionable — see _has_actionable_wait_pending, which
    guards on item_is_disabled.
    """
    non_choice = [
        interaction for interaction in interactions or []
        if (
            isinstance(interaction, dict)
            and interaction.get("type") != "choice"
            and not interaction.get("promoted")
            and not interaction.get("hidden")
            and not item_is_default_focus_chrome(interaction)
        )
    ]
    if not non_choice:
        return []
    buckets = _with_interaction_display_indices(non_choice)
    buckets = _apply_display_index_offset(buckets, display_index_offset)
    actions: list[dict] = []
    for category in _ordered_categories(buckets.keys()):
        if category == "info":
            continue
        for interaction in buckets.get(category) or []:
            label = (
                interaction.get("display_label")
                or interaction.get("label")
                or ""
            )
            if not str(label).strip():
                continue
            action: dict[str, Any] = {
                "label": label,
                "type": interaction.get("type", "other"),
                "category": category,
            }
            if interaction.get("display_index") is not None:
                action["index"] = interaction["display_index"]
            if interaction.get("id") is not None:
                action["id"] = interaction["id"]
            if interaction.get("annotation"):
                action["annotation"] = interaction["annotation"]
            if item_is_disabled(interaction):
                action["disabled"] = True
            actions.append(action)
    return actions


def _interaction_is_story_choice_candidate(itr: dict) -> bool:
    """Return True for story choices, not modal/menu buttons shaped as choices."""
    if not isinstance(itr, dict):
        return False
    if itr.get("source") == "choice":
        return True
    if itr.get("type") != "choice":
        return False
    category = str(itr.get("category") or "")
    if category == "choices":
        return True
    action_names = set(
        itr.get("action_names")
        or itr.get("actions")
        or itr.get("action_strs")
        or []
    )
    if "ChoiceReturn" in action_names:
        screen = str(itr.get("screen") or "")
        iid = str(itr.get("id") or "")
        return screen not in {"menu", "quick_menu"} and not iid.startswith((
            "menu:",
            "quick_menu:",
        ))
    # Legacy game_state snapshots may only expose type=choice for live
    # story choices.  Explicit button-sourced choices are screen actions
    # unless they met one of the story-choice checks above.
    return itr.get("source") != "button"


def _pending_from_choice_interactions(interactions: list[dict]) -> dict | None:
    """Build a choice pending block from live story-choice interactions."""
    items = []
    for itr in _normalize_interaction_disabled(interactions or []):
        if not _interaction_is_story_choice_candidate(itr):
            continue
        label = _button_display_label(itr)
        if not label:
            continue
        item: dict[str, Any] = {
            "label": label,
            "is_caption": bool(itr.get("caption")),
            "is_disabled": bool(
                itr.get("disabled") and not itr.get("caption")
            ),
        }
        if itr.get("annotation"):
            item["annotation"] = itr["annotation"]
        interaction_id = itr.get("id")
        # Button-backed focus-list choices synthesize internal IDs such as
        # "_focus_list:[Enter the basement.]". Those IDs are useful for
        # interaction resolution, but if copied into pending choices they
        # replace the numeric display key and leak as:
        # "_focus_list:[...]: [...]".
        if (
            interaction_id is not None
            and not (
                itr.get("source") == "button"
                and str(interaction_id).startswith("_focus_list:")
            )
        ):
            item["id"] = interaction_id
        items.append(item)
    if not items:
        return None
    return {
        "type": "choice_request",
        "id": "",
        "choices": items,
        "full_items": items,
    }


_ROADWARDEN_INVENTORY_DETAIL_FIELD = "item_detailedmenu"


def _is_roadwarden_inventory_detail_selector(
    btn: dict,
    interaction: dict | None,
) -> bool:
    """Return True for Roadwarden inventory buttons selecting an item."""
    action_strs = []
    if interaction:
        action_strs.extend(interaction.get("action_strs") or [])
    action_strs.extend(btn.get("action_strs") or [])
    return any(
        _ROADWARDEN_INVENTORY_DETAIL_FIELD in str(action)
        for action in action_strs
    )


def _looks_like_internal_label(label: str) -> bool:
    """Heuristic for raw ids such as ``goblinspear`` leaking as labels."""
    if not label:
        return False
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_")
    return all(ch in allowed for ch in label) and not any(ch.isspace() for ch in label)


def _is_uncategorized_roadwarden_inventory_selector(
    btn: dict,
    interaction: dict | None,
) -> bool:
    """Return True for raw inventory ids without game-provided display metadata.

    Roadwarden's inventory screen can expose helper buttons labelled with item
    ids (for example ``goblinspear``) when no category/display label is
    registered for them. They should remain actionable, but should not be
    mixed into ordinary navigation.
    """
    if _button_category_value(btn, interaction):
        return False
    label = str(btn.get("label") or (interaction or {}).get("display_label") or "").strip()
    return (
        _is_roadwarden_inventory_detail_selector(btn, interaction)
        and _looks_like_internal_label(label)
    )


def _button_category_value(
    btn: dict,
    interaction: dict | None = None,
) -> Any:
    """Return private or public button category metadata."""
    explicit = (
        btn.get("_category")
        or btn.get("category")
        or (interaction.get("category") if interaction else None)
    )
    if explicit:
        return explicit
    # The shim typed the matching interaction (its categorizer sees the
    # actions; the state button entry does not).  Navigation chrome such
    # as a quick menu's FileLoad ("Q.Load") must not fall through to a
    # numbered OTHER BUTTONS entry on every read.
    if interaction and interaction.get("type") == "nav":
        return "navigation"
    return None


def _button_display_label(btn: dict) -> str:
    """Return a cleaned display label for scraped screen buttons."""
    label = str(btn.get("label") or btn.get("display_label") or "").strip()
    if str(btn.get("screen") or "") == "_focus_list":
        while label.startswith("\u2022"):
            label = label[1:].strip()
    return label


def _mark_disabled(label: str) -> str:
    """Append the ``(disabled)`` marker unless the label already ends
    with one \u2014 Roadwarden's own unavailable options carry a game-side
    "(disabled)" suffix, and the doubled marker ("... (disabled)
    (disabled)") read as a render glitch in agent output."""
    if label.rstrip().endswith("(disabled)"):
        return label
    return f"{label} (disabled)"


def _is_pending_input_prompt_echo(text: Any, pending: dict | None) -> bool:
    """Return True when screen text duplicates the active input prompt."""
    if not pending or pending.get("type") not in ("input", "input_request"):
        return False
    prompt = _normalize_input_prompt(pending.get("prompt"))
    return _display_text(text).strip() == prompt.strip()


# ---------------------------------------------------------------------------
# Text formatting (for agents and CLI)
# ---------------------------------------------------------------------------

def format_wait_text(
    data: dict, fmt: str = "text", *, anomalies: str = "errors",
) -> dict:
    """Render wait data, attaching any agent-visible anomaly note.

    See ``anomaly_display_lines`` for what *anomalies* selects.
    """
    return _attach_anomaly_note(
        _format_wait_text_core(data, fmt), data, anomalies)


def _format_wait_text_core(data: dict, fmt: str = "text") -> dict:
    """Format structured wait data.

    fmt:
      "text"  — separate keys: text, status, pending, buttons (default)
      "json"  — structured dicts (topics, choices as lists)
      "quiet" — same as text but suppresses navigation/info/stats
    """
    if fmt == "json":
        return _format_wait_json(data)

    quiet = fmt == "quiet"
    out: dict[str, Any] = {}

    # Pending metadata.
    pending = data.get("pending")

    # Story text.  When an overlay is active and current overlay text is
    # available, drop historical screen_text events for that overlay; the
    # current screen snapshot is more authoritative and avoids modal repeats.
    story = data.get("story", [])
    story_seen_lines: set[str] = set()
    story_seen_occurrences: set[str] = set()
    story_seen_delivery_ids: set[int] = set()
    if story:
        lines = []
        render_sections = []
        skip_screen_text_story = bool(
            data.get("_overlay_active") and data.get("_screen_texts"))
        for item in story:
            if (
                skip_screen_text_story
                and item.get("source") == "screen_text"
                and not item.get("passive_overlay_snapshot")
            ):
                continue
            if (
                item.get("source") == "screen_text"
                and _is_pending_input_prompt_echo(item.get("text"), pending)
            ):
                continue
            itype = item.get("type", "")
            line = None
            if itype == "dialogue":
                prefix = "[user] " if item.get("user") else ""
                line = f"{prefix}[{item['character']}] {item['text']}"
            elif itype == "narration":
                line = item["text"]
            elif itype == "anomaly":
                line = item["text"]
            delivery_id = item.get("overlay_delivery_id")
            identified_overlay = (
                item.get("passive_overlay_snapshot")
                and type(delivery_id) is int
            )
            occurrence_id = item.get("_occurrence_id")
            identified_occurrence = isinstance(occurrence_id, str)
            append_line = False
            if line and identified_overlay:
                if delivery_id not in story_seen_delivery_ids:
                    story_seen_delivery_ids.add(delivery_id)
                    append_line = True
            elif line and identified_occurrence:
                if occurrence_id not in story_seen_occurrences:
                    story_seen_occurrences.add(occurrence_id)
                    append_line = True
            elif line and line not in story_seen_lines:
                story_seen_lines.add(line)
                append_line = True
            if append_line:
                lines.append(line)
                section = {"channel": "text", "text": line}
                if identified_overlay:
                    section["delivery_ids"] = [delivery_id]
                elif identified_occurrence:
                    section["occurrence_ids"] = [occurrence_id]
                if type(item.get("_bridge_seq")) is int:
                    section["_bridge_seq"] = item["_bridge_seq"]
                render_sections.append(section)
        if lines:
            out["text"] = "\n".join(lines)
            # Handlers merge promoted waits using this exact occurrence plan.
            # Older shims still fall back to the aggregate text reconstruction.
            out["_story_render_sections"] = render_sections

    # Status text (suppressed in quiet mode).
    if not quiet:
        status = data.get("status", {})
        if status:
            status_lines = []
            # Stats updates are diagnostics. The current state footer already
            # carries player-facing stats, so keep them in the status channel
            # rather than as raw story/event lines.
            if status.get("stats"):
                parts = []
                for stat in status["stats"]:
                    if not isinstance(stat, dict):
                        continue
                    name = stat.get("stat")
                    if not name:
                        continue
                    value = stat.get("value")
                    delta = stat.get("delta")
                    if isinstance(delta, (int, float)) and delta:
                        parts.append(f"{name}: {value} ({delta:+g})")
                    elif delta == "removed":
                        parts.append(f"{name}: removed")
                    else:
                        parts.append(f"{name}: {value}")
                if parts:
                    status_lines.append("(stats updated: " + ", ".join(parts) + ")")
            for label in status.get("auto_skipped", []):
                status_lines.append(f"(auto-advance: {label})")
            for r in status.get("resolved", []):
                label = r["label"]
                if label == "__aborted__":
                    continue  # Engine flow change — not a real choice.
                prefix = "[user chose]" if r.get("by") == "user" else "[chose]"
                status_lines.append(f"{prefix} {label}")
            if status.get("inventory"):
                status_lines.append("[inventory updated] " + ", ".join(status["inventory"]))
            if status_lines:
                out["status"] = "\n".join(status_lines)

    # Pending and buttons — handle overlay detection.
    btns = data.get("buttons", [])
    overlay_active = data.get("_overlay_active", False)

    has_actionable = False
    if pending and pending.get("type") == "choice":
        # Captions are prompt text, not selectable — must not count as
        # an actionable choice (matches format_pending_text's has_enabled).
        has_actionable = any(
            not c.get("disabled") and not c.get("caption")
            for c in pending.get("choices", [])
        )
    elif pending:
        has_actionable = True

    if pending and not overlay_active:
        seen_texts = {
            _story_echo_key(item.get("text"))
            for item in data.get("story") or []
            if isinstance(item, dict)
            and item.get("type") in ("narration", "dialogue")
            and str(item.get("text") or "").strip()
        }
        out["pending"] = format_pending_text(pending, seen_texts=seen_texts)
        out["_pending_raw"] = data.get("_pending_raw")
        if isinstance(data.get("_actionable_snapshot"), dict):
            out["_actionable_snapshot"] = data["_actionable_snapshot"]

    # Overlay screen texts (e.g. journal content, character stats).
    screen_texts = data.get("_screen_texts")
    if screen_texts:
        unique_screen_texts = []
        seen_screen_texts: set[str] = set()
        for text in screen_texts:
            if _is_pending_input_prompt_echo(text, pending):
                continue
            text = _display_text("\n".join(
                line for line in str(text).splitlines()
                if line not in story_seen_lines
            )).strip()
            if not text:
                continue
            if text not in seen_screen_texts:
                seen_screen_texts.add(text)
                unique_screen_texts.append(text)
        if unique_screen_texts:
            out["screen_text"] = "\n".join(unique_screen_texts)
            if out.get("_story_render_sections"):
                # A render plan owns both story channels. Keep the current
                # modal body in that plan when narration also arrived.
                out["_story_render_sections"].append({
                    "channel": "screen_text", "text": out["screen_text"],
                })

    note = hidden_menu_note(data)
    if note:
        out["overlay_note"] = note

    if btns:
        out["_buttons_raw"] = btns
        if not has_actionable or overlay_active:
            cats = categorize_buttons_indexed(btns)
            if quiet:
                cats = {k: v for k, v in cats.items()
                        if k not in ("navigation", "info")}
            formatted = format_categorized_buttons(
                cats, data.get("_button_categories"))
            if formatted:
                out["buttons"] = formatted
            out["_buttons_categorized"] = cats

    if _should_emit_wait_ended(data, pending, btns):
        out["ended"] = True
    footer = data.get("_footer")
    if footer and isinstance(footer, str):
        out["_footer"] = footer
    if not out:
        out["text"] = "(no new events)"
    return out


def _has_actionable_wait_buttons(buttons: Any) -> bool:
    if not isinstance(buttons, list):
        return False
    return any(
        isinstance(button, dict)
        and bool(str(button.get("label") or "").strip())
        and not item_is_disabled(button)
        for button in buttons
    )


def _has_actionable_wait_pending(pending: Any) -> bool:
    if not isinstance(pending, dict):
        return False
    actions = pending.get("actions") or []
    if any(
        isinstance(action, dict)
        and bool(str(action.get("label") or "").strip())
        and not item_is_disabled(action)
        for action in actions
    ):
        return True
    if pending.get("type") != "choice":
        return True
    choices = pending.get("choices") or []
    return any(
        isinstance(choice, dict)
        and not _is_suppressed_pending_choice(choice)
        and not choice.get("disabled")
        and not choice.get("caption")
        for choice in choices
    )


def _should_emit_wait_ended(data: dict, pending: Any, buttons: Any) -> bool:
    return bool(
        data.get("_game_terminal")
        or (
            data.get("ended")
            and not _has_actionable_wait_pending(pending)
            and not _has_actionable_wait_buttons(buttons)
        )
    )


def _format_wait_json(data: dict) -> dict:
    """Format wait data as structured JSON (no text rendering)."""
    out: dict[str, Any] = {}

    story = data.get("story", [])
    if story:
        out["story"] = [
            {
                key: value for key, value in item.items()
                if not str(key).startswith("_")
            }
            if isinstance(item, dict) else item
            for item in story
        ]

    status = data.get("status", {})
    if status:
        out["status"] = status

    pending = data.get("pending")
    if pending:
        out["pending"] = pending
        out["_pending_raw"] = data.get("_pending_raw")

    note = hidden_menu_note(data)
    if note:
        out["overlay_note"] = note

    btns = data.get("buttons", [])
    if btns:
        cats = categorize_buttons(btns)
        if cats:
            out["buttons"] = cats
        out["_buttons_raw"] = btns

    if _should_emit_wait_ended(data, pending, btns):
        out["ended"] = True
    return out


def _format_pending_action_groups(
    actions: list[dict],
    extra_categories: dict[str, dict] | None = None,
) -> list[str]:
    """Group categorized pending actions under `--- CATEGORY ---` headers.

    Mirrors format_interactions' per-category rendering (get_category_meta +
    compact/pipe vs. numbered) so the pending / wait() block shows trailing
    non-choice buttons (e.g. Roadwarden's quick-menu navigation) the same way
    state()'s screen rendering does, rather than as bare `act "label"` lines.
    """
    meta, _order = get_category_meta(extra_categories)
    buckets: Dict[str, List[dict]] = {}
    for action in actions:
        buckets.setdefault(action["category"], []).append(action)

    lines: list[str] = []
    for cat in _ordered_categories(buckets.keys(), extra_categories):
        entries = buckets.get(cat)
        if not entries:
            continue
        header_text, _hint, compact = meta.get(
            cat, (cat.upper(), 'act "<label>"', False))
        lines.append("")
        lines.append(f"--- {header_text} ---")
        if compact:
            parts = []
            for action in entries:
                label = action.get("label", "?")
                if item_is_disabled(action):
                    parts.append(_mark_disabled(label))
                else:
                    parts.append(label)
            lines.append("  " + "  |  ".join(parts))
        else:
            for action in entries:
                label = action.get("label", "?")
                annotation = action.get("annotation", "")
                ann_suffix = f" — {annotation}" if annotation else ""
                if item_is_disabled(action):
                    lines.append(f"  {_mark_disabled(label)}{ann_suffix}")
                elif action.get("index") is not None:
                    lines.append(f"  {action['index']}: {label}{ann_suffix}")
                else:
                    lines.append(f'  act "{label}"{ann_suffix}')
    return lines


def format_pending_text(
    pending: dict, *, seen_texts: set[str] | None = None,
) -> str:
    """Format structured pending data as text.

    *seen_texts* (story-echo keys of narration/dialogue already rendered
    in the same output) suppresses a caption that merely repeats one of
    them: Roadwarden's epilogue menu carries the paragraph as its own
    caption, so the agent read every paragraph twice.
    """
    if pending["type"] == "choice":
        choices = [
            c for c in pending.get("choices", [])
            if not _is_suppressed_pending_choice(c)
        ]
        auto_advancing = pending.get("auto_advancing", False)
        # Captions are prompt text, not selectable (index=None, caption=True).
        has_enabled = any(
            not c.get("disabled") and not c.get("caption") for c in choices)
        if auto_advancing:
            lines = ["--- CHOICE (auto-advancing) ---"]
        elif not has_enabled:
            lines = ["--- NO AVAILABLE CHOICES ---"]
        else:
            lines = ["--- CHOICE REQUIRED ---"]
        # Caption(s): the menu's prompt line(s), shown unnumbered up top.
        for c in choices:
            if c.get("caption"):
                raw = c.get("label") or ""
                cap = _strip_renpy_text_tags(raw).strip()
                if not cap:
                    continue
                # Key from the RAW label: keying the stripped caption would
                # strip a second time, turning an escaped brace ("{{b}" ->
                # "{b}") into a tag and erasing a distinct caption.
                if seen_texts and _story_echo_key(raw) in seen_texts:
                    continue
                lines.append(f"  | {cap}")
        # Enabled choices (numbered, or keyed by ID when available).
        for c in choices:
            if c.get("disabled") or c.get("caption"):
                continue
            key = c.get("id", c["index"])
            ann = c.get("annotation")
            suffix = f"  ({ann})" if ann and ann != str(key) else ""
            lines.append(f"  {key}: {c['label']}{suffix}")
        # Disabled choices (shown as unavailable hints).
        # Skip empty/whitespace labels and bare "(disabled)" sentinels —
        # they are placeholder entries that provide no information.
        def _is_real_disabled(c):
            lbl = (c.get("label") or "").strip()
            return bool(lbl) and lbl != "(disabled)"
        disabled = [c for c in choices
                    if c.get("disabled") and _is_real_disabled(c)]
        if disabled:
            lines.append("")
            lines.append("  Unavailable:")
            for c in disabled:
                label = c["label"]
                lines.append(f"  - {label}")
        # Trailing non-choice actions (promoted CTAs + screen navigation).
        # Uncategorized actions (mod-promoted story buttons) keep their bare
        # `act "label"` lines.  Categorized actions (e.g. quick-menu
        # navigation) are grouped under their `--- CATEGORY ---` header — the
        # same rendering state() uses — instead of reading as loose choices.
        actions = [
            action for action in pending.get("actions") or []
            if (
                isinstance(action, dict)
                and str(action.get("label") or "").strip()
                and not _is_suppressed_pending_action(action)
                and (action.get("category") or not item_is_disabled(action))
            )
        ]
        bare_actions = [a for a in actions if not a.get("category")]
        categorized_actions = [a for a in actions if a.get("category")]
        if bare_actions:
            lines.append("")
            for action in bare_actions:
                label = action.get("label", "?")
                annotation = action.get("annotation", "")
                if annotation:
                    lines.append(f'  act "{label}" — {annotation}')
                else:
                    lines.append(f'  act "{label}"')
        if categorized_actions:
            lines.extend(_format_pending_action_groups(
                categorized_actions, pending.get("_button_categories")))
        if auto_advancing:
            lines.append("")
            lines.append("This choice will auto-advance. Use wait() to continue.")
        elif not has_enabled:
            lines.append("")
            lines.append(
                "No enabled choices are currently available. "
                "Use a visible screen/navigation action if shown, "
                "or load/rollback if this is a dead end."
            )
        else:
            lines.append('Use act <N> or act "<label>" to respond.')
        return "\n".join(lines)
    elif pending["type"] == "input":
        prompt = pending.get("prompt", "Enter text")
        default = pending.get("default")
        if default not in (None, ""):
            prompt = f"{prompt} (default: {default})"
        return (
            f"--- INPUT REQUIRED ---\n{prompt}\n\n"
            "Use input_text('your text') in MCP, or "
            'python vnflight.py input "your text" in the CLI.'
        )
    return f"--- PENDING: {pending['type']} ---"


# ---------------------------------------------------------------------------
# Anomaly formatting
# ---------------------------------------------------------------------------

# Detail keys lifted from `details` into the rendered summary, ordered by
# importance. Skipped when missing / empty so summaries stay short.
ANOMALY_VISIBILITY_MODES = ("off", "errors", "all")

# Anomaly kinds that mean the GAME IS BROKEN, not that a scrape looked odd.
# Everything else (duplicate_buttons, choice_count_mismatch,
# empty_screen_with_choices, orphaned_choice_screen, menu_index_out_of_range)
# is diagnostic: it was interleaved with dialogue until 578c4247 moved all
# anomalies into the status channel, where nothing rendered them. Errors ride
# the agent-facing channel again; the noisy kinds stay opt-in.
ANOMALY_ERROR_KINDS = frozenset({"renpy_exception"})

_ANOMALY_NOTE_MAX_CHARS = 240
_ANOMALY_NOTE_MAX_LINES = 3


def anomaly_is_error(kind: Any, message: Any = "") -> bool:
    """True when this anomaly means the game itself failed."""
    if str(kind or "").strip().lower() in ANOMALY_ERROR_KINDS:
        return True
    lowered = str(message or "").lower()
    return "ren'py exception" in lowered or "renpy exception" in lowered


def _anomaly_kind_and_message(entry: Any) -> tuple[str, str]:
    """Split a status string ("kind: msg") or a raw anomaly event."""
    if isinstance(entry, dict):
        details = entry.get("details")
        details = details if isinstance(details, dict) else {}
        kind = (
            entry.get("kind")
            or entry.get("type")
            or details.get("type")
            or "unknown"
        )
        if str(kind) == "anomaly":
            kind = details.get("type") or entry.get("kind") or "unknown"
        kind = str(kind)
        # Same text as the wait path builds from the event stream
        # (build_wait_data: "kind: message"), so a latched copy of an
        # anomaly and its streamed original render as one line.
        message = entry.get("message") or details.get("message")
        if message:
            return kind, str(message)
        text = format_anomaly_text(entry)
        if text.startswith(kind):
            text = text[len(kind):].strip()
        return kind, text
    text = str(entry or "")
    kind, sep, message = text.partition(": ")
    if not sep:
        return "unknown", text
    return kind, message


def anomaly_display_lines(entries: Any, mode: str = "errors") -> list[str]:
    """Agent-facing lines for anomalies, per visibility mode.

    mode: "off" (render nothing), "errors" (game failures only, default),
    "all" (every anomaly, including scrape diagnostics).
    """
    if not entries or mode == "off":
        return []
    if mode not in ANOMALY_VISIBILITY_MODES:
        mode = "errors"
    if isinstance(entries, (str, dict)):
        entries = [entries]
    lines: list[str] = []
    for entry in entries:
        kind, message = _anomaly_kind_and_message(entry)
        is_error = anomaly_is_error(kind, message)
        if mode == "errors" and not is_error:
            continue
        flat = " ".join(str(message or "").split())
        if len(flat) > _ANOMALY_NOTE_MAX_CHARS:
            flat = flat[:_ANOMALY_NOTE_MAX_CHARS - 1].rstrip() + "…"
        label = "GAME ERROR" if is_error else "anomaly"
        line = f"{label} ({kind})"
        if flat:
            line += f": {flat}"
        if is_error:
            line = line.rstrip(". ")
            line += (
                ". The game may be showing its exception screen"
                " (Ignore continues, Rollback rewinds, Reload restarts);"
                " story choices will not respond until it is dismissed."
            )
        if line not in lines:
            lines.append(line)
    return lines[:_ANOMALY_NOTE_MAX_LINES]


def _anomaly_latch_is_current(anomaly: Any) -> bool:
    """True while a latched anomaly still describes the game's situation.

    The bridge marks the latch resolved when a later story event arrives
    (dialogue, menu, lifecycle boundary), so "current" means no story
    progress since the anomaly: an exception screen that is still up stays
    reported however long it has been up, and a recovered one goes quiet
    as soon as play continues. Age plays no part.
    """
    if not isinstance(anomaly, dict):
        return False
    if not isinstance(anomaly.get("_latched_at"), (int, float)):
        # Every bridge we ship stamps the latch (same artifact, same build).
        # An unstamped latch is malformed, not old.
        return False
    return "_resolved_at" not in anomaly


def _anomaly_entries_from_data(data: Any) -> list:
    """Collect anomaly entries from wait data or state data."""
    if not isinstance(data, dict):
        return []
    entries: list = []
    status = data.get("status")
    if isinstance(status, dict):
        found = status.get("anomalies")
        if isinstance(found, list):
            entries.extend(found)
    found = data.get("anomalies")
    if isinstance(found, list):
        entries.extend(found)
    elif isinstance(found, (str, dict)):
        entries.append(found)
    return entries


def _attach_anomaly_note(out: Any, data: Any, mode: str) -> Any:
    """Set out["anomaly_note"] when visible anomalies are present."""
    if not isinstance(out, dict):
        return out
    lines = anomaly_display_lines(_anomaly_entries_from_data(data), mode)
    if lines:
        out["anomaly_note"] = "\n".join(lines)
    return out


ANOMALY_DETAIL_KEYS = (
    "screen", "label", "kind", "request_id", "index", "expected", "actual",
    "exception", "message", "missing", "duplicates",
)


def format_anomaly_text(ev: dict) -> str:
    """Build a human-readable summary from a vnflight anomaly event.

    Anomaly events ship as ``{"type": "anomaly", "kind": "...", "details": {...}}``
    with no ``text`` field — the watchdog/shim layer assumes consumers
    render ``kind`` + ``details``. This helper is the single canonical
    formatter shared between the vnflight CLI / tool handlers and the
    harness VN plugin so all anomaly surfaces read the same way.
    """
    if not isinstance(ev, dict):
        return ""
    if ev.get("text"):
        return str(ev["text"])
    kind = ev.get("kind") or "unknown"
    details = ev.get("details") or {}
    parts: list = [str(kind)]
    if isinstance(details, dict):
        for key in ANOMALY_DETAIL_KEYS:
            val = details.get(key)
            if val in (None, "", [], {}):
                continue
            if isinstance(val, (list, tuple)):
                rendered = ", ".join(str(x) for x in val[:3])
                if len(val) > 3:
                    rendered += f", … (+{len(val) - 3})"
                parts.append(f"{key}=[{rendered}]")
            else:
                rendered = str(val)
                if len(rendered) > 80:
                    rendered = rendered[:77] + "..."
                parts.append(f"{key}={rendered}")
    return " ".join(parts)


def anomaly_summary(ev: dict) -> dict:
    """Compact dict shape used everywhere we surface an anomaly:
    {kind, summary, details}. Both consumers (cli.py + harness) read
    `summary` for user display and keep `details` for inspection /
    debugging."""
    if not isinstance(ev, dict):
        return {}
    return {
        "kind": ev.get("kind") or "unknown",
        "summary": format_anomaly_text(ev),
        "details": ev.get("details") or {},
    }


# ---------------------------------------------------------------------------
# State formatting
# ---------------------------------------------------------------------------

def build_state_data(raw: dict) -> dict:
    """Build structured state data from raw bridge /state response.

    Data priority: game_state (live, post-transform) > pending_request
    (snapshot from menu creation) > screen (cached screen_content) >
    transcript (historical).
    """
    status = raw.get("status", "unknown")
    lifecycle = classify_lifecycle(raw)
    data: dict[str, Any] = {
        "status": status,
        "_effective_status": lifecycle["effective_status"],
        "_lifecycle": lifecycle,
    }
    # The bridge latches the last anomaly on /state and /status. Keep it on
    # the state data so renderers (and JSON consumers) can see a crashed game
    # without diffing the event stream — but only while it is still current
    # (unresolved: no story progress since). A resolved latch is kept under
    # _stale_anomaly for diagnostics and never presented as happening now.
    sticky_anomaly = raw.get("anomaly")
    if isinstance(sticky_anomaly, dict) and sticky_anomaly:
        if _anomaly_latch_is_current(sticky_anomaly):
            data["anomalies"] = [sticky_anomaly]
        else:
            data["_stale_anomaly"] = sticky_anomaly

    game_state = raw.get("game_state") or {}
    screen = raw.get("screen")
    button_screen = None if lifecycle.get("stale_menu_overlay") else screen
    pending = raw.get("pending_request")
    if lifecycle.get("stale_main_menu_pending"):
        pending = None
    live_interactions_provided = False
    canonical_live_interactions_provided = False
    live_interactions = None
    if "interactions" in game_state:
        live_interactions_provided = True
        canonical_live_interactions_provided = True
        live_interactions = game_state["interactions"]
    elif isinstance(button_screen, dict) and "interactions" in button_screen:
        live_interactions_provided = True
        live_interactions = button_screen.get("interactions") or []

    # Stats: game_state (live) > pending (snapshot) > transcript. The bridge
    # deliberately freezes the terminal run snapshot while Ren'Py resets its
    # store, but that snapshot is historical once the main menu is visible and
    # must not be presented as live state.
    show_run_state = (
        lifecycle.get("context") not in ("main_menu", "menu")
        and raw.get("gameplay_seen") is not False
    )
    stats = {}
    if show_run_state:
        stats = game_state.get("stats") or {}
        if not stats:
            stats = raw.get("stats") or raw.get("config", {}).get("stats", {})
        if not stats and pending:
            stats = pending.get("stats", {})
        if not stats:
            for ev in reversed(raw.get("transcript", [])):
                ev_stats = ev.get("stats")
                if ev_stats and isinstance(ev_stats, dict):
                    stats = ev_stats
                    break
        if stats:
            summary = stats.get("_summary")
            if summary:
                data["_stats_summary"] = summary
            if stats.get("_suppress_brief"):
                data["_suppress_brief_stats"] = True
            inv_label = stats.get("_inventory_label")
            data["stats"] = {
                k: v for k, v in stats.items()
                if not str(k).startswith("_") and v is not None
            }
            if inv_label:
                data["_inventory_label"] = inv_label

    # Inventory: game_state (live) > raw.inventory.
    inv = game_state.get("inventory") if show_run_state else None
    if show_run_state and not inv:
        inv = raw.get("inventory")
    if inv:
        if isinstance(inv, list):
            data["inventory"] = [
                i if isinstance(i, str) else i.get("name", str(i))
                for i in inv
            ]
        elif isinstance(inv, dict):
            data["inventory"] = inv

    config = raw.get("config")
    if config:
        data["config"] = config

    # Pending: game_state is the canonical source for choice labels
    # and order (the shim's scraper runs the augmenter pipeline every
    # tick, so synthesized items and live sensitivity both flow
    # through).  Fall back to pending when game_state is empty.
    if pending:
        ptype = pending.get("type", "")
        if ptype in ("choice_request", "choices"):
            enriched = dict(pending)
            use_live_choice_rows = not _live_choices_duplicate_pending(
                pending,
                game_state,
            )
            if use_live_choice_rows and "choices" in game_state:
                enriched["choices"] = game_state["choices"]
            if use_live_choice_rows and "full_items" in game_state:
                enriched["full_items"] = game_state["full_items"]
            if live_interactions_provided:
                enriched["interactions"] = live_interactions
                has_live_choice_interactions = any(
                    isinstance(interaction, dict)
                    and (
                        interaction.get("source") == "choice"
                        or interaction.get("type") == "choice"
                    )
                    for interaction in (live_interactions or [])
                )
                has_pending_choice_interactions = any(
                    isinstance(interaction, dict)
                    and (
                        interaction.get("source") == "choice"
                        or interaction.get("type") == "choice"
                    )
                    for interaction in (pending.get("interactions") or [])
                )
                if (
                    canonical_live_interactions_provided
                    and not live_interactions
                    and not has_pending_choice_interactions
                    and "choices" not in game_state
                    and "full_items" not in game_state
                ):
                    enriched["choices"] = []
                    enriched["full_items"] = []
                elif (
                    canonical_live_interactions_provided
                    and live_interactions
                    and not has_live_choice_interactions
                    and not has_pending_choice_interactions
                    and "choices" not in game_state
                    and "full_items" not in game_state
                ):
                    enriched["choices"] = []
                    enriched["full_items"] = []
            elif game_state.get("promoted_buttons"):
                enriched["promoted_buttons"] = game_state["promoted_buttons"]
            if game_state.get("_auto_advancing"):
                enriched["_auto_advancing"] = True
            data["pending"] = _build_pending(enriched)
        elif ptype == "input_request":
            data["pending"] = _build_pending(pending)
        data["_pending_raw"] = pending

    # Screen buttons: game_state (post-transform, no ChoiceReturn) >
    # pending.screen_buttons (initial push) > screen.buttons (raw). At an
    # explicit main-menu boundary the separate screen read is newer than the
    # lagging game_state/context pair, so it becomes authoritative.
    interaction_lookup = _interaction_lookup(live_interactions or [])
    if lifecycle.get("screen_main_menu_boundary") and button_screen:
        btn_source = [
            b for b in button_screen.get("buttons", [])
            if "ChoiceReturn" not in b.get("actions", [])
        ]
    elif "screen_buttons" in game_state:
        btn_source = game_state["screen_buttons"]
    elif pending and pending.get("screen_buttons"):
        btn_source = pending["screen_buttons"]
    else:
        raw_btns = button_screen.get("buttons", []) if button_screen else []
        # Filter ChoiceReturn from raw screen (those are shown as choices).
        btn_source = [b for b in raw_btns
                      if "ChoiceReturn" not in b.get("actions", [])]
    if btn_source:
        buttons = []
        for btn in btn_source:
            if item_is_default_focus_chrome(btn):
                continue
            label = _button_display_label(btn)
            if label:
                interaction = interaction_lookup.get(
                    (btn.get("screen", ""), label))
                entry: dict[str, Any] = {"label": label}
                scr = btn.get("screen", "")
                if scr:
                    entry["screen"] = scr
                if _button_is_disabled(btn):
                    entry["disabled"] = True
                if btn.get("annotation"):
                    entry["annotation"] = btn["annotation"]
                idx = btn.get("index")
                if idx is None and interaction:
                    idx = interaction.get("index")
                if idx is not None:
                    entry["index"] = idx
                cat = _button_category_value(btn, interaction)
                if not cat and _is_uncategorized_roadwarden_inventory_selector(
                    btn,
                    interaction,
                ):
                    cat = "raw_item_actions"
                if cat:
                    entry["_category"] = cat
                buttons.append(entry)
        if buttons:
            data["buttons"] = buttons

    # Store interactions for downstream consumers (CLI, MCP).
    if live_interactions_provided:
        data["_interactions"] = _normalize_interaction_disabled(
            live_interactions or [])

    # Capture game-registered button categories from canonical state first,
    # falling back to screen_content for older shim snapshots.
    if game_state.get("button_categories"):
        data["_button_categories"] = game_state["button_categories"]
    elif button_screen and button_screen.get("button_categories"):
        data["_button_categories"] = button_screen["button_categories"]

    # Main-menu pages (About, Help, etc.) have no story-event counterpart.
    # Render their current text without treating gameplay HUD text as narration.
    if lifecycle.get("screen_main_menu_boundary") and button_screen:
        if button_screen.get("texts"):
            data["_screen_texts"] = button_screen["texts"]

    # Overlay detection: the shim sets overlay_active on screen_content
    # events and pending requests when a registered overlay screen is
    # visible.  If active, suppress pending choices and show live
    # screen buttons instead.
    # input_request is never suppressed (it IS the active screen).
    overlay = bool(
        (screen and (
            screen.get("overlay_active") or screen.get("modal_screens")
        ))
        or (pending and (
            pending.get("overlay_active") or pending.get("modal_screens")
        )))
    if overlay:
        ptype = pending.get("type", "") if pending else ""
        # A declared-modal overlay is a full-screen panel: the player sees it
        # INSTEAD of the scene. Record what it covers before the covered menu
        # is dropped, so the response can say so instead of silently
        # presenting a surface with one decision quietly missing.
        modal_tags = _declared_modal_overlay_tags(screen, game_state, pending)
        if modal_tags:
            data["_modal_overlay_screens"] = modal_tags
            # The agent-facing name of the panel, recorded whether or not it
            # covers a numbered menu.  A refusal aimed at a control on the
            # surface UNDERNEATH has no _hidden_menu to read the name from.
            data["_modal_overlay_panel"] = modal_overlay_panel_name(
                modal_tags, screen)
        # Suppress stale pending choices when an overlay is on top.
        if ptype in ("choice_request", "choices"):
            if modal_tags:
                hidden = _hidden_menu_record(
                    modal_tags, data.get("pending"), pending, screen,
                )
                if hidden:
                    data["_hidden_menu"] = hidden
            data.pop("pending", None)
            data.pop("_pending_raw", None)
        data["_overlay_active"] = True
        identity_source = (
            screen if screen and (
                screen.get("overlay_active") or screen.get("modal_screens")
            ) else pending or screen or {}
        )
        identity_tags = sorted({
            str(tag) for tag in (
                list(identity_source.get("modal_screens") or [])
                + list(identity_source.get("overlay_screens") or [])
            ) if str(tag)
        })
        if identity_tags:
            generations = identity_source.get("overlay_generations") or {}
            data["_overlay_snapshot_identity"] = (
                tuple(identity_tags),
                tuple(sorted(
                    (tag, str(generations[tag]))
                    for tag in identity_tags if tag in generations
                )),
            )
        # Show live screen buttons (post-transform from game_state).
        ov_btn_source = (game_state.get("screen_buttons")
                         or (screen.get("buttons", []) if screen else []))
        if ov_btn_source:
            overlay_buttons = []
            for btn in ov_btn_source:
                if item_is_default_focus_chrome(btn):
                    continue
                label = _button_display_label(btn)
                if label:
                    interaction = interaction_lookup.get(
                        (btn.get("screen", ""), label))
                    entry: dict[str, Any] = {"label": label}
                    scr = btn.get("screen", "")
                    if scr:
                        entry["screen"] = scr
                    if _button_is_disabled(btn):
                        entry["disabled"] = True
                    idx = btn.get("index")
                    if idx is None and interaction:
                        idx = interaction.get("index")
                    if idx is not None:
                        entry["index"] = idx
                    cat = _button_category_value(btn, interaction)
                    if not cat and _is_uncategorized_roadwarden_inventory_selector(
                        btn,
                        interaction,
                    ):
                        cat = "raw_item_actions"
                    if cat:
                        entry["_category"] = cat
                    overlay_buttons.append(entry)
            if overlay_buttons:
                data["buttons"] = overlay_buttons
        # Include text owned by the active modal as context (e.g. a confirm
        # prompt or shop resources).  Registered passive overlays may remain
        # visible behind a modal choice screen.  Their cumulative scrollback
        # is delivered chronologically from drainable screen_content events;
        # copying it here as modal context renders the same block a second
        # time and moves it after later narration.
        if screen:
            ov_texts = _modal_overlay_context_texts(screen)
            if ov_texts:
                data["_screen_texts"] = ov_texts

    if not data.get("pending") and not data.get("_overlay_active"):
        live_pending = _pending_from_choice_interactions(
            live_interactions or [])
        if live_pending:
            data["pending"] = _build_pending(live_pending)
            data["_pending_raw"] = live_pending

    # Drop screen buttons that duplicate a pending choice. A `call screen`
    # choice screen (plain Return() buttons) records each option as both a
    # choice-category screen button AND — once a pending choice block is
    # built or synthesized above — a pending choice, so without this the
    # same option renders twice (choices 1-N, then phantom buttons N+1..)
    # and act(N) ranges inflate. Runs after both pending paths so it covers
    # the synthesized case too. Skipped under overlay (pending is popped).
    _pending_block = data.get("pending")
    if (isinstance(_pending_block, dict)
            and _pending_block.get("type") == "choice"
            and data.get("buttons")):
        _choice_label_set = set()
        for _pc in _pending_block.get("choices") or []:
            # Only numbered (enabled, non-caption) choices shadow a button.
            # A button matching a *disabled* choice's label is still a real
            # action and must not be dropped (it would look unavailable).
            if (isinstance(_pc, dict)
                    and _pc.get("index") is not None
                    and not _pc.get("disabled")
                    and not _pc.get("caption")):
                _pcl = (_pc.get("label") or "").strip()
                if _pcl:
                    _choice_label_set.add(_pcl)
        if _choice_label_set:
            # Drop only buttons that are choice DUPLICATES — i.e. in the
            # "choices" category (call-screen Return() buttons the shim
            # tags that way; raw-screen ChoiceReturn buttons are already
            # filtered upstream). A coincidental same-label button in
            # another category (topics/nav/info) is a real action and is
            # kept, so numbered_button_count / act(N) range stay correct.
            def _is_choice_dup(b):
                return (
                    b.get("_category") == "choices"
                    and (b.get("label") or "").strip() in _choice_label_set
                )
            _deduped = [b for b in data["buttons"] if not _is_choice_dup(b)]
            if len(_deduped) != len(data["buttons"]):
                if _deduped:
                    data["buttons"] = _deduped
                else:
                    data.pop("buttons", None)

    return data


def _declared_modal_overlay_tags(*sources: dict | None) -> list:
    """Modal-presentation overlay tags shown, in panel order, first source wins.

    ``modal_overlay_screens`` is additive: a shim or mod that never declares
    one emits nothing, and every caller here degrades to the pre-existing
    layered presentation.
    """
    for source in sources:
        if not isinstance(source, dict):
            continue
        tags = []
        for raw in source.get("modal_overlay_screens") or []:
            tag = str(raw)
            if tag and tag not in tags:
                tags.append(tag)
        if tags:
            return tags
    return []


def modal_overlay_panel_name(tags: list, screen: dict | None) -> str:
    """The name to call the panel in agent-facing prose."""
    names = (screen or {}).get("screen_names")
    labelled = []
    for tag in tags:
        display = names.get(tag) if isinstance(names, dict) else None
        labelled.append(str(display) if display else str(tag))
    return " + ".join(labelled)


def _hidden_menu_record(
    tags: list,
    structured_pending: dict | None,
    raw_pending: dict | None,
    screen: dict | None,
) -> dict | None:
    """Describe the scene menu a modal panel is covering.

    The count is the number the menu WOULD have consumed, so the note and the
    restored numbering after the panel closes agree.
    """
    source = structured_pending or raw_pending
    count = pending_numbered_choice_count(source)
    labels = []
    for item in (
        (source or {}).get("choices") or (source or {}).get("full_items") or []
    ):
        if isinstance(item, dict):
            if item.get("disabled") or item.get("is_disabled"):
                continue
            if item.get("caption") or item.get("is_caption"):
                continue
            label = str(item.get("label") or "").strip()
        else:
            label = str(item).strip()
        if label and label not in labels:
            labels.append(label)
    if not count and not labels:
        return None
    return {
        "screens": list(tags),
        "panel": modal_overlay_panel_name(tags, screen),
        "count": count,
        "labels": labels,
    }


def hidden_menu_note(data: dict | None) -> str:
    """One line telling the agent a decision exists behind the open panel."""
    hidden = (data or {}).get("_hidden_menu")
    if not isinstance(hidden, dict):
        return ""
    panel = str(hidden.get("panel") or "the panel")
    count = hidden.get("count")
    if not isinstance(count, int) or count <= 0:
        return ""
    return (
        "Underlying menu hidden behind {}: {} choice{} "
        "(close the panel to act)".format(
            panel, count, "" if count == 1 else "s")
    )


def _modal_overlay_panel_texts(screen: dict) -> list:
    """Rows owned by the declared-modal panels, in panel order.

    A modal panel replaces the scene, so its body is the story text — the map
    and HUD rows still in the raw scrape are underneath it and are not what
    the player is reading.
    """
    tags = _declared_modal_overlay_tags(screen)
    by_screen = screen.get("overlay_texts_by_screen")
    if not tags or not isinstance(by_screen, dict):
        return []
    rows: list = []
    for tag in tags:
        raw_rows = by_screen.get(tag)
        if not isinstance(raw_rows, list):
            continue
        rows.extend(raw_rows)
    return rows


def _modal_overlay_context_texts(screen: dict) -> list:
    """Return visible text owned by the active blocking/modal layer.

    ``overlay_texts_by_screen`` identifies rows contributed by registered
    overlays.  A passive terminal can stay visible behind an unrelated modal
    choice screen, so those rows must be subtracted from the flattened
    ``texts`` scrape unless that contributor is itself the active modal.
    Older shims without contributor provenance retain the legacy fallback.
    """
    panel_rows = _modal_overlay_panel_texts(screen)
    if panel_rows:
        return panel_rows
    texts = list(screen.get("texts") or [])
    overlay_active = bool(screen.get("overlay_active"))
    modal_screens = {
        str(tag) for tag in (screen.get("modal_screens") or []) if str(tag)
    }
    raw_by_screen = screen.get("overlay_texts_by_screen")

    if not modal_screens or not isinstance(raw_by_screen, dict):
        return (
            list(screen.get("overlay_texts") or texts)
            if overlay_active else texts
        )

    passive_rows: dict[str, int] = {}
    modal_rows: list = []
    for raw_tag, raw_rows in raw_by_screen.items():
        tag = str(raw_tag)
        rows = list(raw_rows or []) if isinstance(raw_rows, list) else []
        if tag in modal_screens:
            modal_rows.extend(rows)
            continue
        for row in rows:
            key = str(row)
            passive_rows[key] = passive_rows.get(key, 0) + 1

    owned = []
    for row in texts:
        key = str(row)
        remaining = passive_rows.get(key, 0)
        if remaining:
            passive_rows[key] = remaining - 1
            continue
        owned.append(row)
    for row in modal_rows:
        if row not in owned:
            owned.append(row)
    return owned


def categorize_buttons(buttons: list[dict]) -> dict[str, list[str]]:
    """Group buttons by category (topics, navigation, info, etc.).

    Returns a dict of category -> list of labels. If a button has a
    ``_category`` field (set by game-specific screen transforms), that
    is used directly. Otherwise falls back to action-based heuristics
    via _categorize_button().
    """
    by_cat: dict[str, list[str]] = {}
    for b in buttons:
        if item_is_default_focus_chrome(b):
            continue
        cat = _button_category_value(b) or _categorize_button(b)
        if cat is None:
            continue
        label = _button_display_label(b)
        if not label.strip():
            continue
        if b.get("disabled"):
            label = _mark_disabled(label)
        by_cat.setdefault(cat, []).append(label)
    return by_cat


def categorize_buttons_indexed(buttons: list[dict]) -> dict[str, list[dict]]:
    """Like categorize_buttons but preserves each button's shim index.

    Returns {category: [{"label", "index", "disabled"}, ...]}. The raw
    index is preserved for diagnostics/fallbacks; rendering assigns separate
    display indices for visible clickable rows.
    """
    by_cat: dict[str, list[dict]] = {}
    for flat_idx, b in enumerate(buttons, 1):
        if item_is_default_focus_chrome(b):
            continue
        cat = _button_category_value(b) or _categorize_button(b)
        if cat is None:
            continue
        label = _button_display_label(b)
        if not label.strip():
            continue
        # Use the button's own index if present, else its position in
        # the input list (post-transform).
        idx = b.get("index", flat_idx)
        entry = {
            "label": label,
            "index": idx,
            "disabled": bool(b.get("disabled")),
        }
        if b.get("annotation"):
            entry["annotation"] = b["annotation"]
        by_cat.setdefault(cat, []).append(entry)
    return by_cat


def _ordered_categories(categories: Iterable[str], extra_categories: dict[str, dict] | None = None) -> list[str]:
    """Return formatter category order with unknown categories inserted sensibly."""
    _meta, order = get_category_meta(extra_categories)
    order = list(order)
    insert_idx = order.index("navigation") if "navigation" in order else len(order)
    for cat in categories:
        if cat not in order:
            order.insert(insert_idx, cat)
            insert_idx += 1
    if "raw_item_actions" in order:
        order.remove("raw_item_actions")
        raw_idx = order.index("navigation") if "navigation" in order else len(order)
        order.insert(raw_idx, "raw_item_actions")
    seen = set()
    return [cat for cat in order if not (cat in seen or seen.add(cat))]


def _numbered_category(cat: str, meta: dict[str, tuple]) -> bool:
    """Return whether this category renders numeric action targets."""
    if cat == "info":
        return False
    _header, _hint, compact = meta.get(cat, (cat.upper(), None, False))
    return not compact


def _with_display_indices(
    by_cat: dict[str, list],
    extra_categories: dict[str, dict] | None = None,
) -> dict[str, list]:
    """Clone categorized entries and assign contiguous visible indices.

    Raw shim indices can have gaps because hidden/info/disabled widgets still
    occupy positions.  Display indices are only for visible clickable rows; the
    raw ``index`` remains available for diagnostics and fallback matching.
    """
    meta, _base_order = get_category_meta(extra_categories)
    order = _ordered_categories(by_cat.keys(), extra_categories)
    out: dict[str, list] = {}
    display_idx = 1
    for cat in order:
        items = by_cat.get(cat)
        if not items:
            continue
        numbered = _numbered_category(cat, meta)
        cloned = []
        for item in items:
            if isinstance(item, dict):
                entry = dict(item)
                if numbered and not item_is_disabled(entry):
                    if entry.get("display_index") is None:
                        entry["display_index"] = display_idx
                    display_idx += 1
                cloned.append(entry)
            else:
                cloned.append(item)
                if numbered:
                    display_idx += 1
        out[cat] = cloned
    return out


def button_label_for_display_index(
    buttons: list[dict],
    idx: int | None,
    extra_categories: dict[str, dict] | None = None,
) -> str | None:
    """Return the label shown for a visible button display index."""
    if idx is None:
        return None
    cats = _with_display_indices(categorize_buttons_indexed(buttons), extra_categories)
    for items in cats.values():
        for item in items:
            if isinstance(item, dict) and item.get("display_index") == idx:
                label = str(item.get("label", "")).strip()
                return label or None
    return None


def numbered_button_count(
    buttons: list[dict] | None,
    extra_categories: dict[str, dict] | None = None,
) -> int:
    """How many buttons render with an agent-visible number.

    Disabled/info/compact-category rows don't get a number, so this is the
    button half of the visible-index range used to detect out-of-range acts.
    """
    if not buttons:
        return 0
    cats = _with_display_indices(categorize_buttons_indexed(buttons), extra_categories)
    return sum(
        1
        for items in cats.values()
        for item in items
        if isinstance(item, dict) and item.get("display_index") is not None
    )


def format_categorized_buttons(
    by_cat: dict[str, list],
    extra_categories: dict[str, dict] | None = None,
) -> str:
    """Render categorized buttons as text with headers and numbering.

    Accepts either {cat: [label_string]} (legacy — uses a continuous
    local counter) or {cat: [{"label", "index", "disabled"}]}. Dict entries
    render with contiguous visible display indices; raw shim indices remain
    available to resolvers as a fallback.
    """
    meta, _base_order = get_category_meta(extra_categories)
    by_cat = _with_display_indices(by_cat, extra_categories)
    order = _ordered_categories(by_cat.keys(), extra_categories)

    # Detect whether entries are dicts (indexed) or bare strings.
    _first_item = None
    for cat in order:
        items = by_cat.get(cat) or []
        if items:
            _first_item = items[0]
            break
    use_real_indices = isinstance(_first_item, dict)

    blocks = []
    num = 1  # Only used in legacy mode.
    for cat in order:
        items = by_cat.get(cat)
        if not items:
            continue
        cat_meta = meta.get(cat, (cat.upper(), None, False))
        header, _hint, compact = cat_meta
        lines = [f"--- {header} ---"]
        if compact:
            _labels = []
            for item in items:
                if isinstance(item, dict):
                    label = item["label"]
                    if item.get("annotation"):
                        label = f"{label} \u2014 {item['annotation']}"
                    if item.get("disabled"):
                        label = _mark_disabled(label)
                    _labels.append(label)
                else:
                    _labels.append(item)
            lines.append("  " + "  |  ".join(_labels))
        elif cat == "info":
            for item in items:
                label = item["label"] if isinstance(item, dict) else item
                lines.append(f"  {label}")
        else:
            for item in items:
                if isinstance(item, dict):
                    label = item["label"]
                    ann = f" \u2014 {item['annotation']}" if item.get("annotation") else ""
                    idx = item.get("display_index")
                    if item.get("disabled"):
                        lines.append(f"  -: {_mark_disabled(label)}{ann}")
                    elif idx is None:
                        lines.append(f"  -: {label}{ann}")  # disabled/unclickable
                    else:
                        lines.append(f"  {idx}: {label}{ann}")
                else:
                    lines.append(f"  {num}: {item}")
                    num += 1
        blocks.append("\n".join(lines))
    return "\n\n".join(blocks) if blocks else ""


def _format_categorized_buttons(buttons: list[dict]) -> str:
    """Categorize and format buttons in one step (convenience wrapper)."""
    return format_categorized_buttons(categorize_buttons(buttons))


def pending_numbered_choice_count(pending: dict | None) -> int:
    """Number of choices that consumed an agent-visible number.

    The single source of truth for the choice/button display boundary,
    used by the renderer (button offset) and the act resolver. Naming-
    agnostic across pending shapes so a caller can't slip disabled/caption
    rows into the count:
      * structured (post _build_pending): ``index`` (None = unnumbered),
        ``disabled``, ``caption``.
      * raw bridge / synthesized pending: ``is_disabled`` / ``is_caption``;
        plain-string entries are enabled.
    Counts ``choices`` when present, else falls back to ``full_items``.
    """
    pending = pending or {}
    source = pending.get("choices") or pending.get("full_items") or []
    n = 0
    for c in source:
        if _is_suppressed_pending_choice(c):
            continue
        if not isinstance(c, dict):
            n += 1  # plain string choice = enabled
            continue
        if c.get("disabled") or c.get("is_disabled"):
            continue
        if c.get("caption") or c.get("is_caption"):
            continue
        # Structured entries carry an explicit index; None means it
        # didn't consume an agent-visible number. Absent key (raw) is fine.
        if c.get("index", "_absent") is None:
            continue
        if not (c.get("label") or "").strip():
            continue
        n += 1
    return n


def _buttons_not_in_pending_actions(buttons: list, pending: dict) -> list:
    """Drop the buttons the pending block lists as actions (by id, else label)."""
    listed_ids: set[str] = set()
    listed_labels: set[str] = set()
    for action in (pending or {}).get("actions") or []:
        if not isinstance(action, dict):
            continue
        if action.get("id") is not None:
            listed_ids.add(str(action["id"]))
        label = str(action.get("label") or "").strip().lower()
        if label:
            listed_labels.add(label)
    if not listed_ids and not listed_labels:
        return buttons
    kept = []
    for btn in buttons:
        if not isinstance(btn, dict):
            kept.append(btn)
            continue
        bid = btn.get("id")
        if bid is not None and str(bid) in listed_ids:
            continue
        if str(_button_display_label(btn) or "").strip().lower() in listed_labels:
            continue
        kept.append(btn)
    return kept


def format_state_text(
    data: dict,
    verbose: bool = False,
    fmt: str = "text",
    *,
    include_details: bool = True,
    anomalies: str = "errors",
) -> dict:
    """Format structured state data, attaching any anomaly note."""
    return _attach_anomaly_note(
        _format_state_text_core(
            data, verbose, fmt, include_details=include_details),
        data,
        anomalies,
    )


def _format_state_text_core(
    data: dict,
    verbose: bool = False,
    fmt: str = "text",
    *,
    include_details: bool = True,
) -> dict:
    """Format structured state data for agents."""
    if fmt == "json":
        # Return structured data directly.
        out = dict(data)
        effective_status = out.pop("_effective_status", None)
        out.pop("_suppress_brief_stats", None)
        # Public JSON must retain screen context when internal keys are stripped.
        if out.get("_screen_texts"):
            out["screen_text"] = list(out["_screen_texts"])
        if effective_status is not None:
            raw_status = out.get("status")
            if raw_status != effective_status:
                out["_raw_status"] = raw_status
            out["status"] = effective_status
        btns = out.pop("buttons", None)
        if btns:
            out["buttons"] = categorize_buttons(btns)
        return out
    if not verbose:
        # Prefer the game mod's one-liner summary (e.g. "Day 3 | 12h
        # before dusk | Scholar, HP 3/4 | Food: hungry").
        summary = data.get("_stats_summary")
        if summary:
            brief_str = summary
        elif not data.get("_suppress_brief_stats"):
            parts = []
            stats = data.get("stats", {})
            if isinstance(stats, dict):
                for k, v in stats.items():
                    parts.append(f"{k}: {v}")
            inv = data.get("inventory")
            if isinstance(inv, list) and inv:
                parts.append(f"items: {', '.join(str(i) for i in inv[:10])}")
            elif isinstance(inv, dict):
                for k, v in inv.items():
                    if k == "version":
                        continue
                    if v in (None, "", [], {}):
                        continue
                    if k == "current" and isinstance(v, list):
                        parts.append(
                            f"items: {', '.join(str(i) for i in v[:10])}"
                        )
                    else:
                        parts.append(f"{k}: {v}")
            if parts:
                brief_str = " | ".join(parts)
            elif data.get("pending") or any(
                not b.get("disabled") for b in data.get("buttons") or []
            ):
                brief_str = ""
            else:
                brief_str = f"status: {data.get('_effective_status', data.get('status', 'unknown'))}"
        else:
            brief_str = ""
        out: dict[str, Any] = {}
        if brief_str:
            out["brief"] = brief_str
        pending = data.get("pending")
        if pending:
            out["pending"] = format_pending_text(pending)
            if isinstance(data.get("_pending_raw"), dict):
                out["_pending_raw"] = data["_pending_raw"]
            if isinstance(data.get("_actionable_snapshot"), dict):
                out["_actionable_snapshot"] = data["_actionable_snapshot"]
        note = hidden_menu_note(data)
        if note:
            out["overlay_note"] = note
        buttons = data.get("buttons")
        if buttons and not pending:
            enabled = [b for b in buttons if not b.get("disabled")]
            if enabled:
                cats = categorize_buttons_indexed(enabled)
                if cats:
                    out["buttons"] = format_categorized_buttons(
                        cats, data.get("_button_categories"))
            else:
                # Preserve the distinction between a known disabled surface
                # and missing button telemetry. Tests and structured callers
                # use it to retain the blocked status above.
                out["buttons"] = []
        return out

    pending = data.get("pending")
    status = data.get("_effective_status", data.get("status", "unknown"))
    # Only show status when there's no pending choice (redundant with
    # CHOICE REQUIRED header) and no overlay active (redundant with
    # overlay buttons).  Still useful for advancing, game_ended,
    # or input_request.
    out: dict[str, Any] = {}
    has_overlay = data.get("_overlay_active", False)
    if not pending and not has_overlay:
        buttons = data.get("buttons")
        quiet_statuses = {
            "waiting_for_input",
            "running",
            "idle",
            "playing",
            "menu",
            "setup",
            "screen_actions",
            "blocked_on_choice",
            "blocked_on_input",
        }
        if status not in quiet_statuses or not buttons:
            out["status"] = status
    # Overlay screen texts (post-transform context like shop resources).
    screen_texts = data.get("_screen_texts")
    if screen_texts:
        texts = [
            _display_text(text) for text in screen_texts
            if not _is_pending_input_prompt_echo(text, pending)
        ]
        if texts:
            out["text"] = "\n".join(texts)
    note = hidden_menu_note(data)
    if note:
        out["overlay_note"] = note
    if pending:
        out["pending"] = format_pending_text(pending)
        if isinstance(data.get("_pending_raw"), dict):
            out["_pending_raw"] = data["_pending_raw"]
        if isinstance(data.get("_actionable_snapshot"), dict):
            out["_actionable_snapshot"] = data["_actionable_snapshot"]
    buttons = data.get("buttons")
    extra_cats = data.get("_button_categories")
    if buttons and pending:
        # The pending block already renders the screen buttons that ride
        # along with the menu (quick-menu items, promoted CTAs) under their
        # own headers with the choice offset; rendering them again here
        # printed every such button twice ("4: Q.Load" under the choices
        # and again below).
        buttons = _buttons_not_in_pending_actions(buttons, pending)
    if buttons:
        cats = categorize_buttons_indexed(buttons)
        if cats:
            if pending:
                cats = _with_display_indices(cats, extra_cats)
                cats = _apply_display_index_offset(
                    cats,
                    pending_numbered_choice_count(pending),
                )
            out["buttons"] = format_categorized_buttons(cats, extra_cats)
            out["_buttons_categorized"] = cats
    # Stats summary footer (compact one-liner from game mod), then the
    # detail this mode exists for.  brief=False is documented as "full
    # inventory and config", but it used to render the same one-line
    # summary brief mode shows: the detailed stats dict and the inventory
    # entries sat in `data` and reached agents only through format="json",
    # so the flag read as a no-op.  The footer is the right channel — it
    # is the state block's own trailer, and render_tool_result_text()
    # passes it through while ignoring unknown top-level keys.
    summary = data.get("_stats_summary")
    inv = data.get("inventory")
    inv_label = data.get("_inventory_label", "Inventory")
    inv_names = _inventory_display_names(inv)
    footer_lines = []
    if summary:
        footer_lines.append(f"  {summary}")
    stats = data.get("stats")
    if include_details and isinstance(stats, dict):
        detail = [
            f"{k}: {v}" for k, v in stats.items()
            if not str(k).startswith("_") and v is not None
        ]
        if detail:
            footer_lines.append("  Stats: " + ", ".join(detail))
    config = data.get("config")
    if include_details and isinstance(config, dict):
        # Only the settings that were actually changed.  The bridge sends
        # its whole config map on every /state, so rendering all of it put
        # an identical "auto_advance: True, ..." line under every verbose
        # state for agents that never touch those knobs.  A default value
        # tells the agent nothing it could not assume, so the line earns
        # its place only where it reports a deviation.
        detail = [
            f"{k}: {v}" for k, v in config.items()
            if not str(k).startswith("_") and v is not None
            and _config_value_is_non_default(k, v)
        ]
        if detail:
            footer_lines.append("  Config: " + ", ".join(detail))
    if include_details and inv_names:
        footer_lines.append(f"  {inv_label} ({len(inv_names)}):")
        footer_lines.extend(f"    • {name}" for name in inv_names)
    elif include_details and summary:
        # Keep the old count line for inventory shapes with no names.
        inv_count = inv.get("current") if isinstance(inv, dict) else None
        if isinstance(inv_count, list):
            inv_count = len(inv_count) if inv_count else None
        if inv_count:
            footer_lines.append(f"  {inv_label}: {inv_count} items")
    if footer_lines:
        out["_footer"] = "\n".join(footer_lines)
    return out


# Bridge config defaults (BridgeHandler.__init__ in bridge.py); a value
# equal to its default is not worth a line in the state footer.
_CONFIG_DEFAULTS: dict[str, Any] = {
    "auto_advance": True,
    "auto_advance_delay": 0.3,
    "end_on_menu_return": True,
}


def _config_value_is_non_default(key: Any, value: Any) -> bool:
    """True when a bridge config entry deviates from its default.

    Unknown keys always report True: we cannot know their default, and a
    key we do not recognise is more likely deliberate than boilerplate.
    """
    if key not in _CONFIG_DEFAULTS:
        return True
    default = _CONFIG_DEFAULTS[key]
    if isinstance(default, bool):
        return bool(value) is not default
    if isinstance(default, float) and isinstance(value, (int, float)):
        return abs(float(value) - default) > 1e-9
    return value != default


def _inventory_display_names(inv: Any) -> list[str]:
    """Item names from either inventory shape (list, or dict['current'])."""
    items = inv
    if isinstance(inv, dict):
        items = inv.get("current")
    if not isinstance(items, list):
        return []
    names = []
    for item in items:
        if isinstance(item, dict):
            name = item.get("name") or item.get("label")
        else:
            name = item
        name = str(name).strip() if name is not None else ""
        if name:
            names.append(name)
    return names


# ---------------------------------------------------------------------------
# Event formatting (CLI display)
# ---------------------------------------------------------------------------


def format_event(
    event: dict, colour: bool = True, quiet: bool = False, show_stats: bool = True,
    verbose: bool = True, visible_labels: Optional[Set[str]] = None,
) -> Optional[str]:
    """Convert a bridge event dict into a human-readable line or block."""
    etype = event.get("type", "")

    # In quiet mode, hide certain events (but keep user actions visible)
    if quiet:
        if etype == "request_resolved" and event.get("by") != "user":
            return None
        if etype == "command_result":
            return None

    if etype == "dialogue":
        char = event.get("character", "???")
        text = _display_text(event.get("text", ""))
        user = event.get("user_initiated")
        prefix = _yellow("[user] ") if user and colour else "[user] " if user else ""
        if colour:
            return f"{prefix}{_cyan('[' + char + ']')} {text}"
        return f"{prefix}[{char}] {text}"

    if etype == "narration":
        text = _display_text(event.get("text", ""))
        user = event.get("user_initiated")
        prefix = _yellow("[user] ") if user and colour else "[user] " if user else ""
        if colour:
            return f"{prefix}  {text}"
        return f"{prefix}  {text}"

    if etype == "screen_text":
        # Overlay / modal panel text (Roadwarden's journal, Echoes' KIT-LOG-MAP
        # panels). This is real story content. Most screen_content remains
        # stateful (passive overlay snapshots are the narrow exception), but
        # this explicit event had no branch here and fell through to the unknown-type
        # tail and was dropped whenever verbose was off.  handle_transcript()
        # is the only caller that passes verbose=False, which is exactly how a
        # transcript full of panel text reported "(empty transcript)".
        texts = [
            _display_text(str(t)).strip()
            for t in (event.get("texts") or [])
        ]
        texts = [t for t in texts if t]
        if not texts:
            return None
        return "\n".join("  " + t for t in texts)

    if etype == "choice_request":
        choices = event.get("choices", [])
        full_items = event.get("full_items", [])
        visible_choices = [
            c for c in choices
            if not _is_suppressed_pending_choice(c)
        ]
        visible_full_items = [
            item for item in full_items
            if not _is_suppressed_pending_choice(item)
        ]
        has_enabled_choices = bool(visible_choices)
        if not has_enabled_choices and visible_full_items:
            has_enabled_choices = any(
                item
                and not item.get("is_caption")
                and not item.get("is_disabled")
                for item in visible_full_items
            )

        if quiet:
            # Quiet mode: just show the choices without the header
            lines = []
        else:
            header = (
                "--- CHOICE REQUIRED ---"
                if has_enabled_choices
                else "--- NO AVAILABLE CHOICES ---"
            )
            lines = [_bold(header) if colour else header]

        # Ren'Py menu captions give context to the choices.
        captions = [i["label"] for i in visible_full_items if i and i.get("is_caption")]
        if captions:
            for cap in captions:
                rendered_caption = f"| {cap}"
                lines.append(
                    f"  {_dim(rendered_caption) if colour else rendered_caption}"
                )

        # Build annotation map: choice label -> annotation from full_items.
        _ann_map: dict[str, str] = {}
        for item in visible_full_items:
            if item and item.get("annotation") and not item.get("is_caption") and not item.get("is_disabled"):
                _ann_map[item["label"]] = item["annotation"]

        # Display choices with IDs (string or integer) for identification.
        # When enriched dicts are present, use the id field.
        # Otherwise fall back to 1-based integer indexing.
        if visible_choices:
            for i, c in enumerate(visible_choices):
                if isinstance(c, dict):
                    display_id = c.get("id", i + 1)
                    c_label = c.get("label", "")
                else:
                    display_id = i + 1
                    c_label = c
                ann = _ann_map.get(c_label, "")
                suffix = f"  ({ann})" if ann else ""
                if colour:
                    lines.append(f"  {_yellow(str(display_id))}: {c_label}{_dim(suffix) if suffix else ''}")
                else:
                    lines.append(f"  {display_id}: {c_label}{suffix}")
        elif visible_full_items:
            idx = 1
            for item in visible_full_items:
                if not item or item.get("is_caption") or item.get("is_disabled"):
                    continue
                label = item["label"]
                ann = item.get("annotation", "")
                suffix = f"  ({ann})" if ann else ""
                if colour:
                    lines.append(f"  {_yellow(str(idx))}: {label}{_dim(suffix) if suffix else ''}")
                else:
                    lines.append(f"  {idx}: {label}{suffix}")
                idx += 1

        # Disabled choices: show as hints for options that may become available.
        # When visible_labels is provided, only show disabled choices whose
        # label is actually rendered on screen (some games hide insensitive
        # items entirely rather than dimming them).
        disabled_items = []
        for i in visible_full_items:
            if not i or not i.get("is_disabled") or i.get("is_caption"):
                continue
            lbl = i["label"]
            if lbl.endswith(" (disabled)"):
                lbl = lbl[:-len(" (disabled)")]
            if visible_labels is not None and lbl not in visible_labels:
                continue
            disabled_items.append(i)
        if disabled_items and not quiet:
            # Filter out empty/whitespace-only disabled labels.
            _vis_disabled = []
            for item in disabled_items:
                label = item["label"]
                if label.endswith(" (disabled)"):
                    label = label[:-len(" (disabled)")]
                if label.strip():
                    _vis_disabled.append(label)
            if _vis_disabled:
                lines.append("")
                dis_hdr = "Unavailable:"
                lines.append(f"  {_dim(dis_hdr) if colour else dis_hdr}")
                for label in _vis_disabled:
                    lines.append(f"  {_dim('- ' + label) if colour else '- ' + label}")

        # Non-choice interactions (topics, nav, promoted, etc.).
        # Use canonical interactions when available, fall back to legacy.
        _cr_interactions = event.get("interactions")
        if isinstance(_cr_interactions, list):
            if not quiet:
                # Promoted buttons from interactions.
                _promoted = [
                    i for i in _cr_interactions
                    if i.get("promoted") and not _is_suppressed_pending_action(i)
                ]
                if _promoted:
                    lines.append("")
                    for pi in _promoted:
                        pi_label = pi.get("display_label", "?")
                        pi_ann = pi.get("annotation", "")
                        if pi_ann:
                            entry = f'  act "{pi_label}" \u2014 {pi_ann}'
                        else:
                            entry = f'  act "{pi_label}"'
                        lines.append(_dim(entry) if colour else entry)

                # Non-choice interactions (topics, nav, shop, etc.).
                _non_choice = [
                    i for i in _cr_interactions
                    if i.get("type") != "choice" and not i.get("promoted")
                ]
                if _non_choice:
                    lines.append("")
                    _choice_index_offset = len(visible_choices) if visible_choices else sum(
                        1
                        for item in visible_full_items
                        if item
                        and not item.get("is_caption")
                        and not item.get("is_disabled")
                    )
                    itr_text = format_interactions(
                        _non_choice, colour=colour, quiet=False,
                        verbose=verbose, show_choices=False,
                        display_index_offset=_choice_index_offset,
                        extra_categories=event.get("button_categories"),
                    )
                    if itr_text:
                        lines.append(itr_text)
        else:
            # Legacy path: promoted_buttons + screen_buttons.
            promoted_buttons = event.get("promoted_buttons", [])
            if promoted_buttons and not quiet:
                visible_promoted = [
                    pb for pb in promoted_buttons
                    if not _is_suppressed_pending_action(pb)
                ]
                if visible_promoted:
                    lines.append("")
                for pb in visible_promoted:
                    pb_label = pb.get("label", "?")
                    pb_ann = pb.get("annotation", "")
                    if pb_ann:
                        entry = f'  act "{pb_label}" \u2014 {pb_ann}'
                    else:
                        entry = f'  act "{pb_label}"'
                    if colour:
                        lines.append(_dim(entry))
                    else:
                        lines.append(entry)

            screen_buttons = event.get("screen_buttons", [])
            if screen_buttons and not quiet:
                visible_sb = [
                    sb for sb in screen_buttons
                    if _categorize_button(sb) is not None
                ]
                if visible_sb:
                    lines.append("")
                    btn_text = format_screen_buttons(
                        visible_sb, colour=colour, quiet=False,
                        screen_categories=event.get("button_categories"),
                        verbose=verbose,
                    )
                    if btn_text:
                        lines.append(btn_text)

        if not quiet:
            if not has_enabled_choices:
                lines.append("")
                message = (
                    "No enabled choices are currently available. "
                    "Use a visible screen/navigation action if shown, "
                    "or load/rollback if this is a dead end."
                )
                lines.append(_dim(message) if colour else message)
            lines.append("---")

        # Include inventory/stats context if present (suppressed when
        # show_stats is False to reduce noise in --wait output).
        if show_stats:
            inv = event.get("inventory", [])
            stats = event.get("stats", {})
            inv_label = stats.pop("_inventory_label", "Evidence") if stats else "Evidence"
            # Strip metadata keys before display.
            if stats:
                stats = {k: v for k, v in stats.items() if not k.startswith("_")}
            if inv:
                lines.append("")
                hdr = f"{inv_label}:"
                lines.append(_dim(hdr) if colour else hdr)
                for item in inv:
                    name = item.get("name", str(item))
                    lines.append(f"  \u2022 {name}")
            if stats:
                lines.append("")
                lines.append(_dim("Stats:") if colour else "Stats:")
                for k, v in stats.items():
                    if k.endswith("_desc"):
                        continue
                    desc = stats.get(f"{k}_desc")
                    if desc:
                        lines.append(f"  {k}: {v} ({desc})")
                    else:
                        lines.append(f"  {k}: {v}")
        if quiet:
            # In quiet mode: show choices with numbers but without header/separator
            result_lines = []
            if visible_choices:
                for i, c in enumerate(visible_choices):
                    result_lines.append(f"  {i + 1}: {c}")
            elif visible_full_items:
                idx = 1
                for item in visible_full_items:
                    if not item or item.get("is_caption") or item.get("is_disabled"):
                        continue
                    label = item["label"]
                    result_lines.append(f"  {idx}: {label}")
                    idx += 1
            return "\n".join(result_lines) if result_lines else None
        return "\n".join(lines)

    if etype == "input_request":
        prompt = _normalize_input_prompt(event.get("prompt", "Enter text:"))
        if quiet:
            # Quiet mode: just show the prompt without the header
            return prompt
        if colour:
            return _bold(f"--- INPUT REQUIRED: {prompt} ---")
        return f"--- INPUT REQUIRED: {prompt} ---"

    if etype == "scene":
        if not verbose:
            return None
        name = event.get("name", "")
        if colour:
            return _dim(f"(scene: {name})")
        return f"(scene: {name})"

    if etype == "show":
        if not verbose:
            return None
        name = event.get("name", "")
        if colour:
            return _dim(f"(show: {name})")
        return f"(show: {name})"

    if etype == "hide":
        if not verbose:
            return None
        name = event.get("name", "")
        if colour:
            return _dim(f"(hide: {name})")
        return f"(hide: {name})"

    if etype == "text_overlay":
        text = event.get("text", "")
        if colour:
            return f"  {_bold(text)}"
        return f"  {text}"

    if etype == "pause":
        if quiet or not verbose:
            return None
        delay = event.get("delay")
        msg = f"(pause: {delay}s)" if delay is not None else "(pause)"
        return _dim(msg) if colour else msg

    if etype in ("nvl_show", "nvl_hide", "mod_loaded", "context"):
        # Hide these in quiet mode or non-verbose mode
        if quiet or not verbose:
            return None
        if colour:
            return _dim(f"[{etype}]")
        return f"[{etype}]"

    if etype == "nvl_clear":
        if not verbose:
            return None
        return _dim("---") if colour else "---"

    if etype == "context":
        if quiet or not verbose:
            return None
        ctx = event.get("context", "?")
        if colour:
            return _dim(f"[context \u2192 {ctx}]")
        return f"[context \u2192 {ctx}]"

    if etype == "game_started":
        # Hide in quiet mode or non-verbose
        if quiet or not verbose:
            return None
        name = event.get("name", "")
        if colour:
            return _green(f"\u25b6 Game started: {name}")
        return f"> Game started: {name}"

    if etype == "game_resumed":
        if quiet or not verbose:
            return None
        reason = event.get("reason", "load or rollback")
        line = f"Game resumed ({reason})"
        return _dim(line) if colour else line

    if etype == "game_ended":
        reason = event.get("reason", "")
        if event.get("terminal") is False:
            # A menu return the bridge ruled non-terminal for this game
            # (end_on_menu_return opt-out \u2014 e.g. Slay the Princess, whose
            # live gameplay screens are classified as main_menu).  Do NOT
            # render "Game ended": that phrase trips downstream terminal
            # phrase-heuristics into a false auto-end.  Tell the agent what
            # actually happened so it can keep playing.
            if event.get("suppressed") == "no_gameplay_seen":
                # This is the ordinary splash/title transition at launch, not
                # a return from a playthrough. Full transcripts can include it
                # beside the real ending much later, so name the chronology.
                line = "Reached the main menu before gameplay began."
            else:
                line = ("Returned to the main menu (not treated as an ending "
                        "for this game \u2014 continue or load to keep playing).")
            return _dim(line) if colour else line
        if colour:
            return _red(f"\u25a0 Game ended ({reason})")
        return f"X Game ended ({reason})"

    if etype == "request_resolved":
        by = event.get("by", "")
        if by == "user":
            value = event.get("value", "?")
            line = f"[user chose] {value}"
            return _yellow(line) if colour else line
        return None  # other resolutions are internal

    if etype in (
        "command_result", "observation_started", "observation_progress",
    ):
        return None  # internal, not shown to the player

    if etype == "user_choice":
        label = event.get("label", "?")
        line = f"[user chose] {label}"
        return _yellow(line) if colour else line

    if etype == "auto_skipped":
        label = event.get("label", "?")
        text = event.get("text")
        line = f"[auto-advance, no input needed] {label}"
        if text:
            line += f"\n  {text}"
        return _dim(line) if colour else line

    if etype == "inventory_update":
        inv = event.get("inventory", [])
        if not inv:
            return None
        # Non-verbose: only show if there's a "changed" field (incremental).
        changed = event.get("changed")
        if not verbose and changed is None:
            return None
        items = ", ".join(i.get("name", "?") for i in inv)
        line = f"[inventory] {items}"
        return _dim(line) if colour else line

    if etype == "stats_update":
        if not verbose:
            return None
        # Show only changed keys when available.
        changed = event.get("changed")
        stats = event.get("stats", {})
        if changed is not None and len(changed) < len(stats):
            # Incremental update -- show only what changed.
            # In non-verbose mode, skip metadata keys (prefixed with _).
            if verbose:
                parts = [f"{k}: {v}" for k, v in changed.items()]
            else:
                parts = [f"{k}: {v}" for k, v in changed.items()
                         if not k.startswith("_")]
            if not parts:
                return None
            line = "[stats] " + ", ".join(parts)
        elif stats:
            if not verbose:
                return None  # suppress full stats dump in non-verbose
            # Initial push or full reset -- just note the count.
            line = f"[stats] {len(stats)} stats tracked"
        else:
            return None
        return _dim(line) if colour else line

    if etype == "screen_content":
        texts = [_display_text(t) for t in event.get("texts", [])]
        buttons = event.get("buttons", [])
        screens = event.get("screens", [])
        user = event.get("user_initiated")
        if quiet and not texts and not buttons and not user:
            return None
        lines = []
        if user:
            parts = ["[user screen change]"]
            added = event.get("screens_added")
            removed = event.get("screens_removed")
            if added:
                parts.append("+" + ",".join(added))
            if removed:
                parts.append("-" + ",".join(removed))
            hint = " ".join(parts)
            lines.append(_yellow(hint) if colour else hint)
        screen_label = ", ".join(screens) if screens else "unknown"
        if not quiet and verbose:
            header = f"[screen: {screen_label}]"
            lines.append(_dim(header) if colour else header)
        _modal_set = set(event.get("modal_screens") or [])
        _text_sources = event.get("text_sources", [])
        if _modal_set and _text_sources and len(_text_sources) == len(texts):
            _base = [t for t, s in zip(texts, _text_sources) if s not in _modal_set]
            _modal: Dict[str, List[str]] = {}
            for t, s in zip(texts, _text_sources):
                if s in _modal_set:
                    _modal.setdefault(s, []).append(t)
            _screen_names = event.get("screen_names", {})
            for t in _base:
                lines.append(f"  {t}")
            for _ms, _mt in _modal.items():
                _ms_label = _screen_names.get(_ms, _ms)
                hdr = f"[{_ms_label}]"
                lines.append(_bold(hdr) if colour else hdr)
                for t in _mt:
                    lines.append(f"  {t}")
        else:
            for t in texts:
                lines.append(f"  {t}")
        interactions = event.get("interactions")
        if interactions:
            itr_text = format_interactions(
                interactions, colour=colour, quiet=quiet,
                verbose=verbose,
                extra_categories=event.get("button_categories"),
            )
            if itr_text:
                lines.append(itr_text)
        elif buttons:
            btn_text = format_screen_buttons(
                buttons, screens, colour=colour, quiet=quiet,
                screen_categories=event.get("button_categories"),
                verbose=verbose,
            )
            if btn_text:
                lines.append(btn_text)
        return "\n".join(lines) if lines else None

    if etype == "screenshot":
        return None

    if etype == "mod_loaded":
        if not verbose:
            return None
        config = event.get("config", {})
        if colour:
            return _dim(f"[mod_loaded] {config}")
        return f"[mod_loaded] {config}"

    # Unknown event type -- show raw for debugging in verbose mode only.
    if not verbose:
        return None
    return (
        _dim(f"[{etype}] {json.dumps(event, ensure_ascii=False)[:120]}")
        if colour
        else f"[{etype}] {json.dumps(event, ensure_ascii=False)[:120]}"
    )


def format_events(
    events: List[dict], colour: bool = True, quiet: bool = False,
    show_stats: bool = True, verbose: bool = True,
) -> str:
    """Format a list of events into a multi-line string."""
    lines: list[str] = []
    prev: Optional[str] = None
    for ev in events:
        formatted = format_event(ev, colour=colour, quiet=quiet,
                                 show_stats=show_stats, verbose=verbose)
        if formatted is not None and formatted != prev:
            lines.append(formatted)
            prev = formatted
    return "\n".join(lines)


def format_pending_request(
    pending: dict, colour: bool = True, quiet: bool = False, show_stats: bool = True,
    verbose: bool = True, visible_labels: Optional[Set[str]] = None,
) -> str:
    """Format a pending request for display (choice or input)."""
    return format_event(pending, colour=colour, quiet=quiet, show_stats=show_stats,
                        verbose=verbose, visible_labels=visible_labels) or ""


# ---------------------------------------------------------------------------
# Button classification
# ---------------------------------------------------------------------------

def _is_disabled_button(actions: List[str]) -> bool:
    """Return True if the button's actions indicate it is disabled / no-op."""
    return actions_are_disabled(actions)


def _button_is_disabled(btn: dict) -> bool:
    return item_is_disabled(btn)


# Screen name -> category mapping.  None = hide entirely.
_DEFAULT_SCREEN_CATEGORIES: Dict[str, Optional[str]] = {
    "doubleimage": None,
    "doubleimage2": None,
    "mundanejob": "rest_util",
    "tutorialtooltips": "info",
    "characterstatus": "info",
    "achievements": "info",
    "notifyimage": "info",
}

# Default category metadata: (header, hint, compact).
# compact=True renders labels pipe-separated on one line.
# Game-specific categories are registered via the shim's
# _vnf_register_button_category() and arrive in screen_content
# events as button_categories.  Use get_category_meta() to merge.
_CATEGORY_META: Dict[str, tuple] = {
    "choices":    ("CHOICES",        'act <N> or act "<label>"', False),
    "items":      ("ITEMS",          'act <N> or act "<label>"', False),
    "raw_item_actions": ("UNLABELED ITEM ACTIONS", 'act <N> or act "<raw id>"', False),
    "rest_util":  ("OPTIONS",        'act "<label>"',            False),
    "navigation": ("NAVIGATION",     'act "<label>"',            True),
    "info":       ("INFO",           None,                          False),
    "other":      ("OTHER BUTTONS",  'act "<label>"',            False),
}

# Default display order.  Game-specific categories are inserted
# before "navigation" when discovered.
_CATEGORY_ORDER = [
    "choices", "items", "raw_item_actions",
    "rest_util", "navigation", "other", "info",
]


def get_category_meta(
    extra: dict[str, dict] | None = None,
) -> tuple[dict[str, tuple], list[str]]:
    """Merge default and game-registered category metadata.

    Args:
        extra: button_categories dict from screen_content event.
               Each value: {"header": str, "compact": bool}.

    Returns:
        (meta_dict, order_list) — merged metadata and display order.
    """
    if not extra:
        return _CATEGORY_META, _CATEGORY_ORDER

    meta = dict(_CATEGORY_META)
    order = list(_CATEGORY_ORDER)
    # Insert game categories before "navigation".
    insert_idx = order.index("navigation") if "navigation" in order else len(order)
    for name, info in extra.items():
        if name not in meta:
            header = info.get("header", name.upper())
            compact = info.get("compact", False)
            meta[name] = (header, None, compact)
            order.insert(insert_idx, name)
            insert_idx += 1
    return meta, order

# Map interaction types (from shim) to display categories.
_INTERACTION_TYPE_TO_CATEGORY: Dict[str, str] = {
    "choice": "choices",
    "items":  "items",
    "topic":  "topics",
    "nav":    "navigation",
    "shop":   "shop",
    "info":   "info",
    "other":  "other",
}


def _categorize_button(btn: dict, screen_categories: Optional[dict] = None) -> Optional[str]:
    """Assign a display category to a button.

    Returns None to hide the button from display entirely.
    """
    if item_is_default_focus_chrome(btn):
        return None
    screen = btn.get("screen", "")
    actions = btn.get("actions", [])

    # Game-specific overrides first.
    cats = screen_categories or {}
    if screen in cats:
        return cats[screen]

    # Built-in screen mapping.
    if screen in _DEFAULT_SCREEN_CATEGORIES:
        return _DEFAULT_SCREEN_CATEGORIES[screen]

    # Action-based heuristics.
    action_set = set(actions)

    if "ChoiceReturn" in action_set:
        return "choices"
    if "Return" in action_set:
        return "navigation"
    if "shopscreen" in screen:
        return "shop"
    if action_set & {
        "ShowMenu", "QuickSave", "QuickLoad", "Save", "Load",
        "LoadMostRecent", "Quit", "OpenURL",
    }:
        return "navigation"
    # Quick-menu file actions ("Q.Load" = FileLoad) are navigation chrome;
    # the same actions on the save/load screens are the slot buttons.
    if action_set & _QUICK_FILE_ACTIONS and screen not in _FILE_SLOT_SCREENS:
        return "navigation"
    if screen == "menu":
        return "navigation"
    if screen == "quick_menu":
        return "navigation"
    if "Jump" in action_set and screen == "nvl":
        return "topics"

    # NullAction = informational.
    if _is_disabled_button(actions):
        return "info"

    return "other"


# ---------------------------------------------------------------------------
# Button and interaction formatting
# ---------------------------------------------------------------------------

def format_screen_buttons(
    buttons: List[dict],
    screens: Optional[List[str]] = None,
    colour: bool = True,
    quiet: bool = False,
    screen_categories: Optional[dict] = None,
    verbose: bool = True,
) -> str:
    """Format screen buttons grouped by category.

    Button indices match the original flat list so ``act <N>`` resolves
    correctly on the shim side.  In quiet mode only actionable
    categories (choices, topics, shop, other) are shown.
    """
    if not buttons:
        return ""

    # --- Bucket buttons by category, preserving original 1-based index ---
    buckets: Dict[str, List[Tuple[int, dict]]] = {}
    for flat_idx, b in enumerate(buttons, 1):
        cat = _button_category_value(b) or _categorize_button(b, screen_categories)
        if cat is None:
            continue
        buckets.setdefault(cat, []).append((flat_idx, b))

    if not buckets:
        return ""

    lines: list = []

    meta, order = get_category_meta(screen_categories)
    order = list(order)
    for cat in buckets:
        if cat not in order:
            insert_idx = order.index("navigation") if "navigation" in order else len(order)
            order.insert(insert_idx, cat)

    for cat in order:
        cat_entries = buckets.get(cat)
        if not cat_entries:
            continue
        header_text, hint, compact = meta.get(
            cat, (cat.upper(), 'act "<label>"', False))

        if quiet:
            # Quiet mode: only show actionable categories.
            if cat in ("info",):
                continue
            for flat_idx, b in cat_entries:
                label = _button_display_label(b) or "?"
                disabled = _button_is_disabled(b)
                suffix = (
                    ""
                    if not disabled or label.rstrip().endswith("(disabled)")
                    else f"  {_dim('(disabled)') if colour else '(disabled)'}"
                )
                if colour:
                    lines.append(f"  {_yellow(str(flat_idx))}: {label}{suffix}")
                else:
                    lines.append(f"  {flat_idx}: {label}{suffix}")
            continue

        # Verbose mode -- show header and buttons.
        hdr = f"--- {header_text} ---"
        lines.append(_bold(hdr) if colour else hdr)

        if compact:
            # Render as pipe-separated labels on one line.
            # Append "(disabled)" to grayed-out buttons so agents reading
            # plain text can distinguish clickable from not.  Colour
            # mode also dims the label for extra contrast.
            parts = []
            for _, b in cat_entries:
                lbl = _button_display_label(b) or "?"
                disabled = _button_is_disabled(b)
                if disabled:
                    marked = _mark_disabled(lbl)
                    parts.append(_dim(marked) if colour else marked)
                else:
                    parts.append(lbl)
            line = "  " + "  |  ".join(parts)
            lines.append(line)
        else:
            for flat_idx, b in cat_entries:
                label = _button_display_label(b) or "?"
                actions = b.get("actions", [])
                screen = b.get("screen", "")

                if cat == "info":
                    # Info items: just show text, no numbering.
                    lines.append(f"  {_dim(label) if colour else label}")
                elif verbose:
                    action_str = ", ".join(actions)
                    screen_hint = f"  [{screen}]" if screen else ""
                    if colour:
                        lines.append(
                            f"  {_yellow(str(flat_idx))}: {label}  "
                            f"{_dim('(' + action_str + ')' + screen_hint)}"
                        )
                    else:
                        lines.append(
                            f"  {flat_idx}: {label}  ({action_str}){screen_hint}"
                        )
                else:
                    if colour:
                        lines.append(f"  {_yellow(str(flat_idx))}: {label}")
                    else:
                        lines.append(f"  {flat_idx}: {label}")

        if hint:
            lines.append(_dim(f"Use: {hint}") if colour else f"Use: {hint}")

    return "\n".join(lines)


def _interaction_category(itr: dict) -> str:
    itype = itr.get("type", "other")
    cat = itr.get("category")
    if not cat:
        action_cat = _categorize_button({
            "screen": itr.get("screen", ""),
            "actions": itr.get("action_names", []),
        })
        if itr.get("source") == "button" and action_cat:
            cat = action_cat
    if not cat and itype != "other":
        cat = _INTERACTION_TYPE_TO_CATEGORY.get(itype)
    if not cat:
        cat = _categorize_button({
            "screen": itr.get("screen", ""),
            "actions": itr.get("action_names", []),
        }) or _INTERACTION_TYPE_TO_CATEGORY.get(itype, "other")
    return cat


def _categorize_interactions(interactions: list[dict]) -> dict[str, list[dict]]:
    buckets: Dict[str, List[dict]] = {}
    for itr in interactions:
        if item_is_default_focus_chrome(itr):
            continue
        buckets.setdefault(_interaction_category(itr), []).append(itr)
    return buckets


def _with_interaction_display_indices(
    interactions: list[dict],
    extra_categories: dict[str, dict] | None = None,
) -> dict[str, list[dict]]:
    meta, _base_order = get_category_meta(extra_categories)
    buckets = _categorize_interactions(interactions)
    order = _ordered_categories(buckets.keys(), extra_categories)
    out: dict[str, list[dict]] = {}
    display_idx = 1
    for cat in order:
        entries = buckets.get(cat)
        if not entries:
            continue
        numbered = _numbered_category(cat, meta)
        cloned = []
        for itr in entries:
            entry = dict(itr)
            if numbered and not item_is_disabled(entry):
                entry["display_index"] = display_idx
                display_idx += 1
            cloned.append(entry)
        out[cat] = cloned
    return out


def _apply_display_index_offset(
    buckets: dict[str, list[dict]],
    offset: int,
) -> dict[str, list[dict]]:
    if offset <= 0:
        return buckets
    adjusted: dict[str, list[dict]] = {}
    for cat, entries in buckets.items():
        adjusted_entries = []
        for itr in entries:
            entry = dict(itr)
            if entry.get("display_index") is not None:
                entry["display_index"] = entry["display_index"] + offset
            adjusted_entries.append(entry)
        adjusted[cat] = adjusted_entries
    return adjusted


def format_interactions(
    interactions: List[dict],
    colour: bool = True,
    quiet: bool = False,
    verbose: bool = False,
    show_choices: bool = True,
    display_index_offset: int = 0,
    extra_categories: dict[str, dict] | None = None,
) -> str:
    """Format a canonical interaction list grouped by type.

    When show_choices is False, choice-type interactions are skipped
    (they're rendered separately by format_event for choice_request).
    """
    if not interactions:
        return ""

    # Bucket by display category and assign contiguous visible indices.
    buckets = _with_interaction_display_indices(
        interactions, extra_categories=extra_categories)
    if not show_choices:
        buckets.pop("choices", None)
        buckets = _apply_display_index_offset(buckets, display_index_offset)

    if not buckets:
        return ""

    lines: list = []

    order = _ordered_categories(buckets.keys(), extra_categories)

    for cat in order:
        cat_entries = buckets.get(cat)
        if not cat_entries:
            continue
        meta, _base_order = get_category_meta(extra_categories)
        header_text, hint, compact = meta.get(
            cat, (cat.upper(), 'act "<label>"', False))

        if quiet:
            if cat in ("info",):
                continue
            for itr in cat_entries:
                label = itr.get("display_label", "?")
                disabled = item_is_disabled(itr)
                suffix = (
                    ""
                    if not disabled or label.rstrip().endswith("(disabled)")
                    else f"  {_dim('(disabled)') if colour else '(disabled)'}"
                )
                idx = itr.get("display_index", "?")
                if colour:
                    lines.append(f"  {_yellow(str(idx))}: {label}{suffix}")
                else:
                    lines.append(f"  {idx}: {label}{suffix}")
            continue

        hdr = f"--- {header_text} ---"
        lines.append(_bold(hdr) if colour else hdr)

        if compact:
            parts = []
            for itr in cat_entries:
                lbl = itr.get("display_label", "?")
                disabled = item_is_disabled(itr)
                if disabled:
                    marked = _mark_disabled(lbl)
                    parts.append(_dim(marked) if colour else marked)
                else:
                    parts.append(lbl)
            line = "  " + "  |  ".join(parts)
            lines.append(_dim(line) if colour else line)
        else:
            # Group items by subcategory when available.
            _has_subcats = (cat == "items"
                           and any(e.get("category") for e in cat_entries))
            if _has_subcats:
                # Bucket by subcategory, preserving order of first appearance.
                _sub_order: list = []
                _sub_buckets: Dict[str, list] = {}
                _no_cat: list = []
                for itr in cat_entries:
                    sc = itr.get("category", "")
                    if sc:
                        if sc not in _sub_buckets:
                            _sub_order.append(sc)
                            _sub_buckets[sc] = []
                        _sub_buckets[sc].append(itr)
                    else:
                        _no_cat.append(itr)
                _all_groups = [(sc, _sub_buckets[sc]) for sc in _sub_order]
                if _no_cat:
                    _all_groups.append(("Other", _no_cat))
                for _sc_name, _sc_items in _all_groups:
                    sc_hdr = f"  {_sc_name}:"
                    lines.append(_bold(sc_hdr) if colour else sc_hdr)
                    for itr in _sc_items:
                        label = itr.get("display_label", "?")
                        idx = itr.get("display_index", "?")
                        ann = itr.get("annotation", "")
                        ann_suffix = f" \u2014 {ann}" if ann else ""
                        if colour:
                            lines.append(f"    {_yellow(str(idx))}: {label}{_dim(ann_suffix) if ann_suffix else ''}")
                        else:
                            lines.append(f"    {idx}: {label}{ann_suffix}")
            else:
                for itr in cat_entries:
                    label = itr.get("display_label", "?")
                    disabled = item_is_disabled(itr)
                    idx = itr.get("display_index", "?")
                    ann = itr.get("annotation", "")

                    if cat == "info":
                        lines.append(f"  {_dim(label) if colour else label}")
                    elif verbose:
                        action_strs = itr.get("action_strs", [])
                        action_str = ", ".join(action_strs)
                        screen = itr.get("screen", "")
                        screen_hint = f"  [{screen}]" if screen else ""
                        if colour:
                            lines.append(
                                f"  {_yellow(str(idx))}: {label}  "
                                f"{_dim('(' + action_str + ')' + screen_hint)}"
                            )
                        else:
                            lines.append(
                                f"  {idx}: {label}  ({action_str}){screen_hint}"
                            )
                    else:
                        ann_suffix = f" \u2014 {ann}" if ann else ""
                        if disabled:
                            entry = f"  {_dim('- ' + label + ann_suffix) if colour else '- ' + label + ann_suffix}"
                            lines.append(entry)
                        elif colour:
                            lines.append(f"  {_yellow(str(idx))}: {label}{_dim(ann_suffix) if ann_suffix else ''}")
                        else:
                            lines.append(f"  {idx}: {label}{ann_suffix}")

        if hint:
            lines.append(_dim(f"Use: {hint}") if colour else f"Use: {hint}")

    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Session-dependent screen/interaction helpers
# ---------------------------------------------------------------------------

def _get_live_screen(session: Any) -> Optional[dict]:
    """Return the bridge's current /screen snapshot when available.

    Transcript screen_content can lag behind modal/screen transforms. The
    state command already prefers /screen; action rendering needs the same source
    when resolving overlay buttons.
    """
    getter = getattr(session, "_get", None)
    if not callable(getter):
        return None
    try:
        code, data = getter("/screen", timeout=2.0)
    except Exception:
        return None
    if code == 200 and data:
        screen = data.get("screen")
        if screen and not screen.get("_lightweight") and (
            "buttons" in screen
            or "interactions" in screen
            or isinstance(screen.get("screens"), list)
        ):
            return screen
    return None


def _get_latest_screen_buttons(session: Any) -> Optional[dict]:
    """Return the latest full screen snapshot, including a buttonless screen.

    A closed modal must not reappear just because it was the last screen with
    buttons. Lightweight say-progress events do not replace a full snapshot.
    ``session`` must support ``get_transcript(last_n=N)`` (duck-typed).
    """
    live_screen = _get_live_screen(session)
    if live_screen:
        return live_screen

    transcript = session.get_transcript(last_n=30)
    for ev in reversed(transcript):
        if (ev.get("type") == "screen_content" and not ev.get("_lightweight")
                and ("buttons" in ev or "interactions" in ev
                     or isinstance(ev.get("screens"), list))):
            return ev
    return None


def _has_choice_overlay(sc_ev: Optional[dict], pending: Optional[dict]) -> bool:
    """Return True when a pending choice exists but the choice buttons
    aren't currently visible on screen (an overlay covers them)."""
    if not pending or pending.get("type") != "choice_request":
        return False
    if not sc_ev:
        return False
    if not sc_ev.get("overlay_active") and not sc_ev.get("modal_screens"):
        sc_screens = set(sc_ev.get("screens") or [])
        sc_screens.discard("vnf_command_poller")
        sc_screens.discard("vnf_player_debug")
        sc_screens.discard("llm_command_poller")
        sc_screens.discard("llm_player_debug")
        if not (sc_screens and sc_screens <= {"menu"}):
            return False
    sc_buttons = sc_ev.get("buttons", [])
    # Choice buttons have a ChoiceReturn action.
    if any("ChoiceReturn" in str(b.get("action_strs", ""))
           for b in sc_buttons):
        return False
    return True


def _get_latest_interactions(
    session: Any,
    pending: Optional[dict] = None,
    overlay_active: bool = False,
    ignore_screen: bool = False,
) -> list:
    """Get the current canonical interaction list.

    When overlay_active is True and pending has choices, the choices are
    marked disabled and the current screen_content buttons are used
    instead of the stale button set from menu creation time.

    ``session`` must support ``get_transcript(last_n=N)`` (duck-typed).
    """
    # Find the most recent screen_content interactions.
    live_screen = None
    sc_interactions = None
    if not ignore_screen:
        live_screen = _get_latest_screen_buttons(session)
        if live_screen and "interactions" in live_screen:
            sc_interactions = _normalize_interaction_disabled(
                live_screen.get("interactions") or []
            )

    pending_interactions = None
    if pending and "interactions" in pending:
        pending_interactions = _normalize_interaction_disabled(
            pending.get("interactions") or [])

    if pending_interactions is None:
        return sc_interactions if sc_interactions is not None else []

    if sc_interactions == []:
        return []

    if sc_interactions is not None and live_screen and live_screen.get("overlay_active"):
        return sc_interactions

    if sc_interactions is not None and _live_choices_differ(
        sc_interactions,
        pending_interactions,
    ):
        return sc_interactions

    if not overlay_active or sc_interactions is None:
        if sc_interactions is not None:
            return _merge_pending_choices_with_live_buttons(
                pending_interactions,
                sc_interactions,
            )
        return pending_interactions

    # Overlay covers the choices -- drop them entirely and use the
    # overlay's buttons.
    merged = _reclassify_nav_items(sc_interactions, skip_choices=True)
    return merged


def _merge_pending_choices_with_live_buttons(
    pending_interactions: list,
    live_interactions: list,
) -> list:
    """Keep pending choices, but refresh non-choice buttons from /screen.

    Choice requests can outlive quick-menu/nav updates in Roadwarden. The
    pending request is still the source of truth for hidden or subset choices,
    but live /screen interactions are more reliable for buttons such as
    Sleep/Travel.
    """
    live_non_choices = [
        i for i in live_interactions
        if i.get("type") != "choice"
    ]
    if not live_non_choices:
        return pending_interactions

    pending_choices = [
        i for i in pending_interactions
        if i.get("type") == "choice"
    ]
    if not pending_choices:
        return live_interactions

    return pending_choices + live_non_choices


def _choice_source_items(raw: dict) -> list:
    """Return the selectable source rows used to render a choice request."""
    full_items = raw.get("full_items")
    if isinstance(full_items, list) and full_items:
        return full_items
    choices = raw.get("choices")
    if isinstance(choices, list):
        return choices
    return []


def _choice_item_label(item: Any) -> str:
    if isinstance(item, dict):
        return _display_text(item.get("label", ""))
    return _display_text(item)


def _choice_equivalence_key(item: Any) -> tuple[str, bool, bool]:
    """Return a display-equivalence key for comparing choice rows.

    The bridge pending request is the source consumed by wait().  State may
    also include live/screen-derived choices, and those can echo the same rows
    with lightweight list-marker chrome stripped.  Compare on the stable user
    text while keeping disabled/caption rows distinct.
    """
    if isinstance(item, dict):
        disabled = item_is_disabled(item)
        caption = bool(item.get("is_caption"))
    else:
        disabled = False
        caption = False
    label = _choice_item_label(item).strip()
    label = label.lstrip("\u2022\u2023\u25e6\u2043").strip()
    return (label, disabled, caption)


def _live_choices_duplicate_pending(
    pending: dict,
    game_state: dict,
) -> bool:
    """Return True when live choices are only a duplicate-expanded pending.

    In that case state should format the same pending request as wait(), not
    renumber the duplicate live rows as additional choices.
    """
    pending_items = _choice_source_items(pending)
    live_items = _choice_source_items(game_state)
    if not pending_items or len(live_items) <= len(pending_items):
        return False

    pending_keys = [_choice_equivalence_key(item) for item in pending_items]
    live_keys = [_choice_equivalence_key(item) for item in live_items]
    if live_keys[:len(pending_keys)] != pending_keys:
        return False
    pending_key_set = set(pending_keys)
    return all(key in pending_key_set for key in live_keys[len(pending_keys):])


def _normalize_interaction_disabled(interactions: list) -> list:
    normalized = []
    for itr in interactions:
        if not isinstance(itr, dict):
            normalized.append(itr)
            continue
        updated = dict(itr)
        if _button_is_disabled(updated):
            updated["disabled"] = True
        normalized.append(updated)
    return normalized


def _interaction_lookup(interactions: list) -> dict[tuple[str, str], dict]:
    lookup = {}
    for itr in _normalize_interaction_disabled(interactions):
        if not isinstance(itr, dict):
            continue
        label = _button_display_label(itr)
        if not label:
            continue
        lookup[(itr.get("screen", ""), label)] = itr
    return lookup


def _live_choices_differ(
    live_interactions: list,
    pending_interactions: list,
) -> bool:
    """Return True when the current screen has a newer choice set.

    Ren'Py screens can recompute sensitivity/labels after a modal action
    without issuing a fresh choice_request. In that case the pending request is
    stale, but /screen already contains the actual actionable choices.
    """
    live_choices = [
        i for i in live_interactions
        if i.get("type") == "choice"
    ]
    pending_choices = [
        i for i in pending_interactions
        if i.get("type") == "choice"
    ]
    if not live_choices or not pending_choices:
        return False
    if len(live_choices) < len(pending_choices):
        return False

    def _signature(items: list) -> list[tuple[str, bool]]:
        return [
            (
                str(i.get("display_label") or "").strip(),
                bool(i.get("disabled")),
            )
            for i in items
        ]

    return _signature(live_choices) != _signature(pending_choices)


_QUICK_FILE_ACTIONS = {"FileLoad", "FileSave", "FileTakeScreenshot"}
_FILE_SLOT_SCREENS = {"save", "load", "file_slots"}

# System nav actions that should stay as "nav" (compact display).
_SYS_NAV_ACTIONS = {
    "ShowMenu", "QuickSave", "QuickLoad", "Save", "Load",
    "LoadMostRecent", "Quit", "MainMenu", "OpenURL",
}


def _reclassify_nav_items(
    interactions: list,
    skip_choices: bool = False,
) -> list:
    """Reclassify non-system nav buttons as 'items' and re-index.

    Content buttons (inventory items, shop items, etc.) are categorized
    as 'nav' by the shim because they're on menu/quick_menu screens.
    This function splits them into 'items' type so they render as
    indexed entries instead of compact pipe-separated navigation.
    """
    result = []
    idx = 1
    for itr in interactions:
        if skip_choices and itr.get("source") == "choice":
            continue
        itr_copy = dict(itr)
        if itr_copy.get("type") == "nav":
            action_set = set(itr_copy.get("action_names", []))
            if not (action_set & _SYS_NAV_ACTIONS):
                itr_copy["type"] = "items"
        if not itr_copy.get("disabled"):
            itr_copy["index"] = idx
            idx += 1
        result.append(itr_copy)
    return result


# ---------------------------------------------------------------------------
# Quote normalization and interaction matching
# ---------------------------------------------------------------------------

def _normalize_quotes_client(s: str) -> str:
    """Fold Unicode quotes to ASCII for matching."""
    return (s
            .replace("\u201c", '"').replace("\u201d", '"')
            .replace("\u2018", "'").replace("\u2019", "'"))


def _interaction_aliases(itr: dict) -> list[str]:
    label = str(itr.get("display_label", "") or "")
    aliases = [label]
    iid = itr.get("id")
    if iid is not None and iid != "":
        aliases.extend([str(iid), f"{iid}: {label}"])
    ann = itr.get("annotation")
    if ann:
        aliases.extend([str(ann), f"{ann}: {label}"])
    aliases.extend(str(a) for a in itr.get("aliases", []) if a)
    return aliases


def _act_match_category(itr: dict) -> str:
    """'choice' for a story choice, 'control' for everything else.

    'control' covers screen buttons, nav rows, topics, items — anything a
    mod or the base game presents as a clickable UI control rather than a
    menu-arm decision.  The category is the unit precedence and ambiguity
    are judged against below.  Distinct from ``_interaction_category``
    (display-header categorization, e.g. "topics"/"items"/"other") — this
    one only ever distinguishes choice from everything else.
    """
    return "choice" if itr.get("source") == "choice" else "control"


def _exact_match_key(s: str) -> str:
    """Normalize a label for the EXACT-match tier only.

    Case, whitespace, and TRAILING punctuation are folded away so a target
    typed without the game's own trailing period/ellipsis ("Grab the
    toolkit" vs. the rendered "Grab the toolkit.") still counts as an
    exact hit rather than falling through to the stricter fuzzy tier.
    Containment (prefix/substring) matching is unaffected — it already
    tolerates a missing period by definition.
    """
    import re
    normalized = _normalize_quotes_client(str(s)).lower().strip()
    return re.sub(r"[\s.,!?:;…]+$", "", normalized)


def _label_exact_hit(target_key: str, itr: dict) -> bool:
    for alias in _interaction_aliases(itr):
        if _exact_match_key(alias) == target_key:
            return True
    return False


def _label_prefix_hit(target_lower: str, itr: dict) -> bool:
    for alias in _interaction_aliases(itr):
        if _normalize_quotes_client(alias).lower().strip().startswith(target_lower):
            return True
    return False


def _label_substring_hit(target_lower: str, itr: dict) -> bool:
    dl = _normalize_quotes_client(itr.get("display_label", "")).lower().strip()
    return bool(target_lower) and target_lower in dl


def _dedup_interactions(items: Iterable[dict]) -> list[dict]:
    seen: set[int] = set()
    out: list[dict] = []
    for itr in items:
        key = id(itr)
        if key in seen:
            continue
        seen.add(key)
        out.append(itr)
    return out


class InteractionMatch:
    """Outcome of resolving a label target against the interaction list.

    ``matched`` names the single control to act on.  ``ambiguous`` lists
    every candidate a tied exact match or a fuzzy hit found when the target
    did not resolve to exactly one — the caller fails closed and shows the
    list rather than guessing.  Neither is set when the target reached
    nothing at all.
    """

    __slots__ = ("matched", "ambiguous")

    def __init__(
        self,
        matched: Optional[dict] = None,
        ambiguous: Optional[list] = None,
    ) -> None:
        self.matched = matched
        self.ambiguous = ambiguous

    def __bool__(self) -> bool:
        return self.matched is not None


def _resolve_label_interaction(
    target: str,
    interactions: list,
    hidden_choice_labels: Optional[Set[str]] = None,
) -> "InteractionMatch":
    """Resolve *target* to exactly one interaction, or flag it ambiguous.

    Precedence: an id match is exact and unambiguous by construction (ids
    are internal identifiers, never player-typed labels, so they cannot
    collide across categories).  Failing that, an exact normalized
    label/alias match wins outright when it names interactions in exactly
    one CATEGORY — a story choice vs. any other screen control (see
    ``_act_match_category``) — even if a short administrative label
    (KIT, MAP, LOG) happens to be a SUBSTRING of an unrelated, much longer
    story choice: substring containment is fuzzy, not exact, so it never
    competes with a real exact hit.  A tie of exact hits ACROSS categories
    refuses instead of guessing which the caller meant.

    Targets of three characters or fewer require an exact hit. Only once
    nothing matches exactly does a longer target's fuzzy pass run (prefix
    first, substring only when no prefix candidate exists at all), and it
    is held to a stricter rule than the exact tier: it must land on
    exactly one interaction, in any category — two fuzzy hits in the same
    category are just as ambiguous as one in each.  Fleet R66:
    ``act(target="KIT")`` fuzzy-matched the unrelated story choice "The
    signal analysis toolkit..." because the old substring tier accepted
    any lone match regardless of what else was on the surface; a KIT
    button on the same surface must now win via the exact tier before
    fuzzy ever runs.

    *hidden_choice_labels* excludes story choices a modal panel currently
    covers from competing at all: the shim's raw interaction list keeps
    them for "hidden menu" bookkeeping even though the player cannot see
    or act on them, so a real, visible panel control sharing that label is
    not a genuine tie.  A target that reaches ONLY a hidden choice still
    resolves to nothing here — the caller's existing hidden-menu refusal
    names the panel instead of this function inventing a new one.
    """
    if not interactions:
        return InteractionMatch()
    hidden = hidden_choice_labels or set()

    def _visible(itr: dict) -> bool:
        if itr.get("source") != "choice":
            return True
        return _normalize_label(str(itr.get("display_label") or "")) not in hidden

    pool = [itr for itr in interactions if _visible(itr)]
    if not pool:
        return InteractionMatch()

    for itr in pool:
        if itr.get("id") == target:
            return InteractionMatch(matched=itr)

    target_lower = _normalize_quotes_client(str(target)).lower().strip()
    if not target_lower:
        return InteractionMatch()

    target_key = _exact_match_key(target)
    exact_by_category: dict[str, list[dict]] = {}
    for itr in pool:
        if _label_exact_hit(target_key, itr):
            exact_by_category.setdefault(_act_match_category(itr), []).append(itr)
    if exact_by_category:
        if len(exact_by_category) == 1:
            return InteractionMatch(matched=next(iter(exact_by_category.values()))[0])
        candidates = [itr for items in exact_by_category.values() for itr in items]
        return InteractionMatch(ambiguous=candidates)

    # Short control names must not become unrelated story fragments when
    # the control is absent (KIT -> toolkit, LOG -> logs).
    if len(target_lower) <= 3:
        return InteractionMatch()

    prefix_candidates = _dedup_interactions(
        itr for itr in pool if _label_prefix_hit(target_lower, itr))
    fuzzy_candidates = prefix_candidates or _dedup_interactions(
        itr for itr in pool if _label_substring_hit(target_lower, itr))
    if not fuzzy_candidates:
        return InteractionMatch()
    if len(fuzzy_candidates) == 1:
        return InteractionMatch(matched=fuzzy_candidates[0])
    return InteractionMatch(ambiguous=fuzzy_candidates)


def _match_interaction(
    target: str,
    interactions: list,
    display_index_offset: int = 0,
) -> Optional[dict]:
    """Match a target string or index against the interaction list.

    Returns the matched interaction dict, or None.  Label resolution
    delegates to ``_resolve_label_interaction`` for the category-aware
    exact/fuzzy precedence; an ambiguous outcome collapses to ``None``
    here, matching this function's legacy no-guess contract for callers
    that do not consume the candidate list.
    """
    if not interactions:
        return None

    # Integer index.
    try:
        idx = int(target)
        buckets = _with_interaction_display_indices(interactions)
        buckets = _apply_display_index_offset(buckets, display_index_offset)
        for entries in buckets.values():
            for itr in entries:
                if itr.get("display_index") == idx:
                    return itr
        # Fallback: accept raw shim indices for callers that already know them.
        for itr in interactions:
            if itr.get("index") == idx:
                return itr
        return None
    except (ValueError, TypeError):
        pass

    return _resolve_label_interaction(target, interactions).matched


# ---------------------------------------------------------------------------
# Main menu formatting
# ---------------------------------------------------------------------------

def format_main_menu(ctx: dict, colour: bool = True, quiet: bool = False) -> str:
    """Format main-menu available commands as a choice-like display."""
    commands = ctx.get("available_commands", [])
    if not commands:
        return ""
    if quiet:
        # Quiet mode: just show commands without headers
        return "\n".join(f"  \u2022 {cmd}" for cmd in commands)
    header = "--- MAIN MENU ---"
    lines = [_bold(header) if colour else header]
    for cmd in commands:
        if colour:
            lines.append(f"  \u2022 {_yellow(cmd)}")
        else:
            lines.append(f"  \u2022 {cmd}")
    lines.append("---")
    lines.append(
        _dim('Use: act "<command>"  (e.g. act "start")')
        if colour
        else 'Use: act "<command>"  (e.g. act "start")'
    )
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Choice matching helpers
# ---------------------------------------------------------------------------

def _choice_submit_key(choice: Any, positional_idx: int) -> Any:
    """Return the best key for submitting a choice: its ``id`` if present,
    its ``index`` field, or the 1-based positional index as fallback."""
    if isinstance(choice, dict):
        cid = choice.get("id")
        if cid is not None and cid != "":
            return cid
        cidx = choice.get("index")
        if cidx is not None:
            return cidx
    return positional_idx


def _choice_label_and_annotation(choice: Any) -> tuple[str, str]:
    """Return the actionable label and optional display annotation."""
    if isinstance(choice, dict):
        label = choice.get("label", choice.get("caption", ""))
        annotation = choice.get("annotation", "")
        return str(label or ""), str(annotation or "")
    return str(choice), ""


def _choice_id(choice: Any) -> str:
    if isinstance(choice, dict):
        cid = choice.get("id")
        if cid is not None and cid != "":
            return str(cid)
    return ""


def _normalise_choice_target(s: str) -> str:
    return _normalize_quotes_client(str(s)).lower().strip()


def _choice_rendered_aliases(label: str, annotation: str) -> list[str]:
    aliases = [label]
    if not annotation:
        return aliases
    aliases.extend([
        f"{label}  ({annotation})",
        f"{label} ({annotation})",
        f"{annotation}: {label}",
    ])
    return aliases


def _choice_candidates_for_target(target: str, choices: list) -> list[tuple[int, Any, str]]:
    target_norm = _normalise_choice_target(target)
    if not target_norm:
        return []
    matches = []
    for i, choice in enumerate(choices or [], 1):
        label, annotation = _choice_label_and_annotation(choice)
        aliases = _choice_rendered_aliases(label, annotation)
        cid = _choice_id(choice)
        if cid:
            aliases.extend([cid, f"{cid}: {label}"])
        if annotation:
            aliases.append(annotation)
        if any(target_norm == _normalise_choice_target(alias) for alias in aliases):
            matches.append((i, choice, label))
    return matches


def _unique_choice_prefix_match(target: str, choices: list) -> Optional[tuple[int, Any, str]]:
    target_norm = _normalise_choice_target(target)
    if len(target_norm) <= 3:
        return None
    matches = []
    for i, choice in enumerate(choices or [], 1):
        label, annotation = _choice_label_and_annotation(choice)
        aliases = _choice_rendered_aliases(label, annotation)
        cid = _choice_id(choice)
        if cid:
            aliases.extend([cid, f"{cid}: {label}"])
        if any(_normalise_choice_target(alias).startswith(target_norm) for alias in aliases):
            matches.append((i, choice, label))
    return matches[0] if len(matches) == 1 else None


def choice_target_to_action_label(target: str, choices: list) -> str:
    """Map a rendered annotated choice label back to its actionable label.

    Text renderers display annotations such as ``(friendly)`` to help agents
    reason about attitude choices, but Ren'Py's interaction label usually
    remains the raw dialogue.  This keeps copy/pasted rendered labels
    round-trippable without adding broad fuzzy matching.
    """
    candidates = _choice_candidates_for_target(target, choices)
    if len(candidates) == 1:
        return candidates[0][2]
    if candidates:
        # A choice can arrive through both pending.full_items and the live
        # interaction list. The latter commonly adds the stable choice ID,
        # making the two dicts unequal even though they describe one visible
        # row. Coalesce only when every match has the same actionable label
        # and the nonempty IDs do not conflict; genuinely duplicated labels
        # with different IDs remain ambiguous.
        labels = {
            _normalise_choice_target(label): label
            for _index, _choice, label in candidates
        }
        choice_ids = {
            _choice_id(choice)
            for _index, choice, _label in candidates
            if _choice_id(choice)
        }
        if len(labels) == 1 and len(choice_ids) <= 1:
            return next(iter(labels.values()))
    prefix = _unique_choice_prefix_match(target, choices)
    if prefix is not None:
        return prefix[2]
    return target


def _match_choice_target(target: str, choices: list) -> Optional[tuple]:
    """Try to match *target* against a list of enriched choices.

    Returns ``(submit_key, label)`` on match, else ``None``.
    *submit_key* is the choice's ``id``, ``index``, or 1-based positional
    index -- whichever the shim will accept.
    Matching order: integer index -> string ID -> exact label -> unique prefix
    -> unique substring. Targets of at most three characters are exact-only.
    """
    if not choices:
        return None

    # 1. Integer index (1-based positional).
    try:
        idx = int(target)
        if 1 <= idx <= len(choices):
            c = choices[idx - 1]
            lbl = c.get("label", c) if isinstance(c, dict) else str(c)
            return _choice_submit_key(c, idx), lbl
        return None
    except (ValueError, TypeError):
        pass

    target_lower = target.lower().strip()

    # 2. String ID (exact, case-insensitive).
    for i, c in enumerate(choices):
        if isinstance(c, dict):
            cid = str(c.get("id", "")).lower()
            if cid and cid == target_lower:
                return _choice_submit_key(c, i + 1), c.get("label", "")

    # 3. Exact label/rendered annotation match.
    exact_matches = _choice_candidates_for_target(target, choices)
    if len(exact_matches) == 1:
        i, c, lbl = exact_matches[0]
        return _choice_submit_key(c, i), lbl

    # 4. Unique prefix match against labels and rendered annotated labels.
    if len(target_lower) <= 3:
        return None
    prefix_match = _unique_choice_prefix_match(target, choices)
    if prefix_match is not None:
        i, c, lbl = prefix_match
        return _choice_submit_key(c, i), lbl

    # 5. Unique substring label match.  Ambiguous fragments should not pick
    # the first visible choice by accident.
    substring_matches = []
    for i, c in enumerate(choices):
        clabel = (c.get("label", "") if isinstance(c, dict) else str(c)).lower().strip()
        if clabel and target_lower in clabel:
            lbl = c.get("label", c) if isinstance(c, dict) else str(c)
            substring_matches.append((i + 1, c, lbl))
    if len(substring_matches) == 1:
        i, c, lbl = substring_matches[0]
        return _choice_submit_key(c, i), lbl

    return None


# ---------------------------------------------------------------------------
# UI Inspector formatting
# ---------------------------------------------------------------------------

def _format_inspect_result(data: dict, colour: bool = True, verify: bool = False,
                           focus_only: bool = False) -> str:
    """Format the inspect command_result into human-readable text."""
    lines: list[str] = []
    header = "=== UI INSPECT ==="
    lines.append(_cyan(header) if colour else header)

    sw = data.get("screen_width", 0)
    sh = data.get("screen_height", 0)
    lines.append(f"  Resolution: {sw}x{sh}")

    # Screens.
    if not focus_only:
        screens = data.get("screens", [])
        lines.append("")
        lines.append(f"SCREENS ({len(screens)} active):")
        if not screens:
            lines.append("  (none)")
        for s in screens:
            tag = s.get("tag", "?")
            zo = s.get("zorder", 0)
            flags = []
            if s.get("modal"):
                flags.append("modal")
            if s.get("transient"):
                flags.append("transient")
            flag_str = "  " + " ".join(flags) if flags else ""
            lines.append(f"  {tag:<24s} zorder={zo}{flag_str}")

    # Focus list (clickable regions).
    focus_list = data.get("focus_list", [])
    lines.append("")
    lines.append(f"CLICKABLE REGIONS ({len(focus_list)}):")
    if not focus_list:
        lines.append("  (none \u2014 focus list empty)")
    else:
        # Group by screen.
        by_screen: dict[str, list] = {}
        for i, item in enumerate(focus_list):
            scr = item.get("screen", "")
            by_screen.setdefault(scr, []).append((i, item))

        idx = 0
        for scr, items in by_screen.items():
            scr_header = f"  [{scr or '?'}]"
            lines.append(_dim(scr_header) if colour else scr_header)
            for _, item in items:
                idx += 1
                label = item.get("label", "")
                action = item.get("action_type", "")
                x, y = item.get("x", 0), item.get("y", 0)
                w, h = item.get("w", 0), item.get("h", 0)
                focused = item.get("is_focused", False)

                # Truncate long labels.
                disp_label = label if len(label) <= 50 else label[:47] + "..."
                focus_mark = "  *focused*" if focused else ""

                pos_str = f"@ ({x},{y}) {w}x{h}"
                line = f"    {idx}: \"{disp_label}\" ({action}) {pos_str}{focus_mark}"

                # Flag anomalies.
                anomalies = []
                if sw and sh:
                    if x + w < 0 or y + h < 0 or x > sw or y > sh:
                        anomalies.append("OFF-SCREEN")
                    if w >= sw - 10 and h >= sh - 10:
                        anomalies.append("FULL-SCREEN")
                if w < 5 or h < 5:
                    anomalies.append("TINY")
                if anomalies:
                    warn = " [" + ", ".join(anomalies) + "]"
                    line += (_red(warn) if colour else warn)
                lines.append(line)

    # Viewports.
    if not focus_only:
        viewports = data.get("viewports", [])
        if viewports:
            lines.append("")
            lines.append("VIEWPORTS:")
            for vp in viewports:
                scr = vp.get("screen", "?")
                pct = vp.get("scroll_percent", 0)
                val = vp.get("scroll_value", 0)
                rng = vp.get("scroll_range", 0)
                page = vp.get("scroll_page", 0)
                lines.append(f"  {scr}: scroll {pct}% (value={val}, range={rng}, page={page})")

    # Mouse.
    mouse = data.get("mouse", {})
    if mouse:
        mx = mouse.get("x", "?")
        my = mouse.get("y", "?")
        fl = mouse.get("focused_label", "")
        fs = mouse.get("focused_screen", "")
        if fl:
            lines.append("")
            lines.append(f"MOUSE: ({mx}, {my}) -> focused: \"{fl}\" [{fs}]")
        else:
            lines.append("")
            lines.append(f"MOUSE: ({mx}, {my}) -> no focus")

    # Cross-reference: scraped vs focus.
    if verify and not focus_only:
        scraped = data.get("scraped", {})
        scraped_buttons = scraped.get("buttons", [])
        scraped_screens = scraped.get("screens", [])

        lines.append("")
        verify_header = "SCRAPE vs FOCUS:"
        lines.append(_cyan(verify_header) if colour else verify_header)
        lines.append(f"  Scraped: {len(scraped_buttons)} buttons from {{{', '.join(scraped_screens)}}}")

        focus_screens = set(item.get("screen", "") for item in focus_list)
        lines.append(f"  Focus:   {len(focus_list)} clickable regions from {{{', '.join(sorted(focus_screens))}}}")

        # Match scraped buttons to focus entries by label substring.
        matched = 0
        unmatched_scraped = []
        for btn in scraped_buttons:
            btn_label = btn.get("label", "")
            found = False
            for fi in focus_list:
                fl_label = fi.get("label", "")
                if btn_label and fl_label and (btn_label in fl_label or fl_label in btn_label):
                    found = True
                    break
            if found:
                matched += 1
            else:
                unmatched_scraped.append(btn_label)

        # Focus entries not in scrape.
        focus_labels = set(fi.get("label", "") for fi in focus_list if fi.get("label"))
        scraped_labels = set(b.get("label", "") for b in scraped_buttons if b.get("label"))
        extra_focus = []
        for fl_label in focus_labels:
            if not any(fl_label in sl or sl in fl_label for sl in scraped_labels):
                extra_focus.append(fl_label)

        lines.append(f"  Match:   {matched}/{len(scraped_buttons)} scraped buttons found in focus list")

        if unmatched_scraped:
            warn = f"  Missing: {len(unmatched_scraped)} scraped buttons NOT in focus list:"
            lines.append(_red(warn) if colour else warn)
            for lbl in unmatched_scraped[:10]:
                disp = lbl if len(lbl) <= 60 else lbl[:57] + "..."
                lines.append(f"    - \"{disp}\"")
        if extra_focus:
            lines.append(f"  Extra:   {len(extra_focus)} focus regions not in scrape")
            for lbl in extra_focus[:10]:
                disp = lbl if len(lbl) <= 60 else lbl[:57] + "..."
                lines.append(f"    + \"{disp}\"")

    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Label and interaction normalization shared with the handler layer
# ---------------------------------------------------------------------------

def _normalize_label(s: str) -> str:
    """Normalize a label for comparison — fold quotes, strip bullets, collapse whitespace.

    Also strips all quote characters entirely so the agent can match
    'Thank you' against the game's "Thank you" without caring about
    punctuation.
    """
    import re
    for ch in "\u201c\u201d\u201e\u201f\u2033":
        s = s.replace(ch, '"')
    for ch in "\u2018\u2019\u201a\u201b\u2032":
        s = s.replace(ch, "'")
    s = s.replace("\u2014", "-").replace("\u2013", "-")
    s = s.replace("\u2026", "...")
    s = re.sub(r"^[\s\u2022\u25cf\u25e6\u2023\-\*]+", "", s)
    s = re.sub(r"^\d+[\.\)]\s*", "", s)
    # Drop all straight quotes so 'Thank you' == "Thank you".
    s = s.replace('"', "").replace("'", "")
    s = re.sub(r"\s+", " ", s).strip().lower()
    return s


def _choice_interactions(state: dict) -> list[dict]:
    return [
        interaction for interaction in (state.get("interactions") or [])
        if isinstance(interaction, dict)
        and (
            interaction.get("source") == "choice"
            or interaction.get("type") == "choice"
        )
    ]


def _raw_pending_labels(pending: dict | None) -> list[str]:
    """Normalize the actionable labels carried by private request metadata."""
    if not isinstance(pending, dict):
        return []
    labels = []
    for choice in pending.get("choices") or []:
        label = (
            choice.get("label") or choice.get("caption")
            if isinstance(choice, dict) else choice
        )
        if str(label or "").strip():
            labels.append(_normalize_label(str(label).strip()))
    return labels

# ======================================================================
# Module: overlay_presentation.py
# ======================================================================






@dataclass
class OverlayPresentationState:
    """Every occurrence ledger a handler session owns, and how it is cleared.

    These fields advance together. Pending queues, durable receipts,
    provisional look-ahead markers and recovered-occurrence keys are three
    views of the same rows: clearing one without the others either replays a
    row that was already presented or strands a row that never will be. The
    two lifecycle wipes are therefore defined once, here, instead of being
    re-spelled at every site that abandons a timeline.
    """

    # Later public calls may overlap while booking or claiming the same screen
    # snapshot. The full occurrence ledger is one-owner-at-a-time; helpers
    # re-enter this lock while merge/drain operations hold it.
    lock: Any = field(default_factory=threading.RLock, repr=False)
    # Last passive-overlay snapshot booked from the current screen or drained
    # screen_content events. Position matters: repeated rows are
    # legitimate terminal output and must not collapse by string value.
    text_snapshot: list[str] = field(default_factory=list, repr=False)
    screen_key: tuple[str, ...] = field(default_factory=tuple, repr=False)
    retain_generation: bool = field(default=False, repr=False)
    contributor_snapshots: dict[str, list[str]] = field(
        default_factory=dict, repr=False)
    contributor_keys: dict[str, str] = field(default_factory=dict, repr=False)
    retained_contributors: set[str] = field(default_factory=set, repr=False)
    schema_mode: str = field(default="", repr=False)
    # Occurrence identities are local to this handler session. They let an
    # output promotion transfer a rendered row without guessing from text.
    delivery_serial: int = field(default=0, repr=False)
    # Overlay occurrences drained during a wait but not yet handed to output.
    pending_deliveries: list[dict] = field(default_factory=list, repr=False)
    # Transaction reads are replayable until acknowledged. Bridge-authored
    # passive deltas therefore need an event occurrence receipt in addition
    # to their content delta, or two settle reads assign the same row two
    # local delivery IDs.
    durable_receipts: dict[tuple[str, str, int], None] = field(
        default_factory=dict, repr=False)
    # A latest-screen scrape can run ahead of the ordered event cursor. Rows
    # delivered from that look-ahead are provisional until their durable
    # passive_overlay_delta events arrive; reconcile them instead of assigning
    # a second occurrence identity to the same source row.
    provisional_deliveries: list[dict] = field(default_factory=list, repr=False)
    # Callback lines this context already printed that a passive overlay row
    # may mirror. The in-batch matcher can only pair a callback with an
    # overlay row drained in the SAME response; a look-ahead row of the same
    # occurrence is fenced and flushes a call later, where it would read as a
    # new terminal line. Entries are consumed once and retired one
    # presentation boundary after they were printed.
    presented_callback_lines: list[dict] = field(
        default_factory=list, repr=False)
    # Rows recovered from a later cumulative snapshot still have an original
    # durable event that may arrive through another read lane. Claim that
    # eventual event by sequence + text occurrence instead of rendering it
    # again under its durable receipt identity.
    recovered_occurrences: dict[tuple[int, str, int], None] = field(
        default_factory=dict, repr=False)
    last_bridge_seq: int = field(default=0, repr=False)
    # Story rows opportunistically read from transcript after a pending
    # boundary. They remain in the bridge's ordinary drain, so remember their
    # sequence ids until that drain catches up and suppress the second copy.
    transcript_rescued_seqs: set[int] = field(default_factory=set, repr=False)
    # A latest-screen fallback can render a screen_text occurrence before its
    # durable transaction drain catches up. Remember that occurrence by bridge
    # and shim-source provenance so replayable transaction reads cannot show it
    # again in a later scene.
    rendered_screen_event_receipts: dict[
        tuple[str, str, int], tuple[str, ...]
    ] = field(default_factory=dict, repr=False)
    # Exact ordinary-screen body last rendered to the caller. This is separate
    # from the client's actionable-screen hint: exposing choices proves a
    # decision was shown, not that persistent screen chrome was included in
    # the response that carried those choices.
    ordinary_screen_presentation_receipt: tuple | None = field(
        default=None, repr=False)
    # Highest shim source sequence observed per source identity. Lifecycle
    # markers can be replayed by scoped transaction reads, so source order is
    # what distinguishes a real new timeline from an old marker seen late.
    timeline_source_sequences: dict[str, int] = field(
        default_factory=dict, repr=False)
    # A scoped ending can remain applied while Ren'Py already exposes the
    # title menu. Own that title occurrence once per action/run so a required
    # nonce recovery does not repeat navigation and GAME ENDED.
    terminal_presentation_receipts: set[tuple[int, str]] = field(
        default_factory=set, repr=False)

    def baseline(self) -> None:
        """Drop the delivery ledger for a game generation that just began.

        A ``game_started``/``game_resumed`` marker invalidates every unclaimed
        occurrence and every receipt that would have suppressed its replay.
        The booked panel itself is retired separately, by ending the passive
        overlay generation, because a retained overlay may legitimately
        survive the restart.
        """
        with self.lock:
            self.pending_deliveries = []
            self.durable_receipts = {}
            self.provisional_deliveries = []
            self.recovered_occurrences = {}
            self.presented_callback_lines = []

    def reset(self) -> None:
        """Discard everything owned by an abandoned story timeline.

        Timeline source sequences deliberately survive: they are what proves a
        replayed lifecycle marker is older than the timeline that replaced it.
        """
        with self.lock:
            self.text_snapshot = []
            self.screen_key = ()
            self.retain_generation = False
            self.contributor_snapshots = {}
            self.contributor_keys = {}
            self.retained_contributors = set()
            self.schema_mode = ""
            self.baseline()
            self.last_bridge_seq = 0
            self.delivery_serial = 0
            self.transcript_rescued_seqs.clear()
            self.rendered_screen_event_receipts.clear()
            self.ordinary_screen_presentation_receipt = None
            self.terminal_presentation_receipts.clear()


def _reset_timeline_context(
    ctx: Any,
    *,
    clear_client_prefetch: bool = True,
    clear_client_action_delivery: bool = True,
    preserve_client_action_nonce: str | None = None,
    preserve_client_action_nonces: set[str] | None = None,
) -> None:
    """Discard handler/client state owned by an abandoned story timeline."""
    ctx.overlay.reset()
    client = ctx.client
    client.last_request_id = None
    client.last_choices = None
    client.last_actionable_snapshot = None
    client._last_delivered_actionable_screen = None
    client._last_delivered_actionable_screen_signature = ()
    client._acted_request_id = None
    retire_action_nonces = getattr(
        client, "retire_auto_action_nonces", None)
    if callable(retire_action_nonces):
        retire_action_nonces(
            "timeline_reset",
            preserve_nonce=preserve_client_action_nonce,
            preserve_nonces=preserve_client_action_nonces,
        )
    if clear_client_action_delivery:
        reset_action_delivery = getattr(
            client, "reset_action_event_delivery", None)
        if callable(reset_action_delivery):
            reset_action_delivery()
    if clear_client_prefetch:
        ActionDeliveryOwnership._clear_held_events(client)


# One public tool call can perform several internal waits and ordinary state
# polls. Those nested reads belong to the same presentation consumer: they
# must not make a latest-screen look-ahead row appear safe merely because a
# poll completed. This holds the id() of the HandlerContext whose public call
# owns the current thread, so an internal merge can tell itself apart from the
# serialized public boundary, and a re-entrant handle_tool() on the same
# context does not deadlock on the (non-reentrant) presentation-call lock.
# It is a marker, not an identity: the lane admits one public call per context
# at a time, so there is nothing left to distinguish between calls.
_ACTIVE_PRESENTATION_INVOCATION: ContextVar[int | None] = (
    ContextVar("vnflight_presentation_invocation", default=None)
)


def _get_screen(
    ctx: Any, *, timeout: float = 2.0,
) -> dict | None:
    """Get the bridge's timeout-aware screen snapshot."""
    try:
        code, data = ctx.client._get("/screen", timeout=max(0.0, timeout))
        if code == 200 and data:
            return data.get("screen")
    except Exception:
        pass
    return None


def _game_state_matches_pending_choice_surface(
    pending: dict | None,
    game_state: dict | None,
) -> bool:
    """Prove a fresh game-state menu resolves the pending request."""
    if not isinstance(pending, dict) or not isinstance(game_state, dict):
        return False
    pending_interactions = _choice_interactions(pending)
    live_interactions = _choice_interactions(game_state)
    if not pending_interactions or not live_interactions:
        return False

    pending_labels = _raw_pending_labels(pending)
    live_labels = _raw_pending_labels({
        "choices": game_state.get("choices") or [],
    })
    if not live_labels:
        live_labels = [
            _normalize_label(
                interaction.get("display_label")
                or interaction.get("label")
                or ""
            )
            for interaction in live_interactions
            if not interaction.get("disabled")
            and not interaction.get("is_disabled")
            and not interaction.get("caption")
            and not interaction.get("is_caption")
        ]
        live_labels = [label for label in live_labels if label]
    if not pending_labels or pending_labels != live_labels:
        return False

    pending_request = {
        "type": pending.get("type"),
        "choices": list(pending_labels),
        "interactions": pending_interactions,
    }
    live_request = {
        "type": pending.get("type"),
        "choices": list(live_labels),
        "interactions": live_interactions,
    }
    previous = actionable_state_snapshot({
        "pending_request": pending_request,
        "game_state": {"interactions": pending_interactions},
    })
    current = actionable_state_snapshot({
        "pending_request": live_request,
        "game_state": {"interactions": live_interactions},
    })
    return actionable_snapshots_equivalent(previous, current)


def _game_state_proves_overlay_closed(
    pending: dict | None,
    game_state: dict | None,
    *,
    overlay_screen: dict | None,
    previous_game_state: dict | None,
) -> bool:
    """Require a matching menu sample newer than the covered overlay."""
    fresh_position = _source_event_position(game_state)
    overlay_position = _source_event_position(overlay_screen)
    previous_position = _source_event_position(previous_game_state)
    if (
        isinstance(overlay_screen, dict)
        and (
            overlay_screen.get("overlay_active")
            or overlay_screen.get("modal_screens")
            or overlay_screen.get("modal_overlay_screens")
        )
        and overlay_position is None
    ):
        # A present legacy/custom screen is still authoritative. Without its
        # source position, no state sample can prove it predates that overlay.
        return False
    # A visible overlay sample is the authoritative boundary. The first state
    # read may already be a stable post-close menu and need not advance again.
    # Without such a screen sample, the prior masked game_state is the bound.
    boundary = (
        overlay_position if overlay_position is not None
        else previous_position
    )
    if (
        fresh_position is None
        or boundary is None
        or fresh_position[0] != boundary[0]
        or fresh_position[1] <= boundary[1]
    ):
        return False
    return _game_state_matches_pending_choice_surface(pending, game_state)


# Overlay occurrences owned by a rendered output. Each record carries a stable
# session-local id, its text, and the channel currently rendering it. This is
# deliberately identity-based: equal text can be two legitimate terminal rows.
_OVERLAY_DELIVERIES_KEY = "_overlay_deliveries"


# Ledger bookkeeping stamped on overlay delivery records while they are held
# or fenced. Public copies (result payloads, hub pushes) never carry them.
_OVERLAY_LEDGER_RECORD_KEYS = (
    "_durable_receipt",
    "_recovered_occurrence",
    "_cursor_fenced",
    "_cursor_fenced_poll_serial",
    "_cursor_fenced_source_id",
    "_cursor_fenced_source_seq",
)


_SCREEN_TEXT_BEFORE_STORY_KEY = "_screen_text_before_story"


_STORY_RENDER_SECTIONS_KEY = "_story_render_sections"


def _overlay_delivery_records(out: dict) -> list[dict]:
    return [
        dict(record)
        for record in (out.get(_OVERLAY_DELIVERIES_KEY) or [])
        if isinstance(record, dict)
        and type(record.get("id")) is int
        and isinstance(record.get("text"), str)
        and record.get("channel") in ("story", "screen_text")
    ]


def _merge_overlay_delivery_records(out: dict, records: list[dict]) -> None:
    """Merge ownership by identity in canonical occurrence order."""
    merged = _overlay_delivery_records(out)
    positions = {
        record["id"]: index for index, record in enumerate(merged)
    }
    for record in records:
        if (
            type(record.get("id")) is int
            and isinstance(record.get("text"), str)
            and record.get("channel") in ("story", "screen_text")
        ):
            clean = dict(record)
            position = positions.get(record["id"])
            if position is None:
                positions[record["id"]] = len(merged)
                merged.append(clean)
            else:
                merged[position] = clean
    if merged:
        out[_OVERLAY_DELIVERIES_KEY] = merged
    else:
        out.pop(_OVERLAY_DELIVERIES_KEY, None)


def _render_value_text(value: object) -> str:
    if isinstance(value, str):
        text = value.strip()
        return "" if text == "(no new events)" else text
    if isinstance(value, list):
        texts = [str(item).strip() for item in value if str(item).strip()]
        return "\n".join(
            text for text in texts if text != "(no new events)").strip()
    return ""


def _find_rendered_block(value: str, block: str) -> int:
    """Find a complete line/block occurrence, never a substring of a row."""
    start = 0
    while block:
        index = value.find(block, start)
        if index < 0:
            return -1
        end = index + len(block)
        before_boundary = index == 0 or value[index - 1] in "\r\n"
        after_boundary = end == len(value) or value[end] in "\r\n"
        if before_boundary and after_boundary:
            return index
        start = index + 1
    return -1


def _story_render_sections(out: dict) -> list[dict]:
    """Return the private chronological story presentation for an output."""
    existing = out.get(_STORY_RENDER_SECTIONS_KEY)
    if isinstance(existing, list):
        return [
            section for section in normalize_sections(existing)
            if _render_value_text(section.get("text"))
        ]

    deliveries = _overlay_delivery_records(out)
    order = ("screen_text", "text") if out.get(
        _SCREEN_TEXT_BEFORE_STORY_KEY
    ) else ("text", "screen_text")
    sections: list[dict] = []
    for channel in order:
        value = _render_value_text(out.get(channel))
        if not value:
            continue
        delivery_channel = "story" if channel == "text" else "screen_text"
        channel_deliveries = [
            record for record in deliveries
            if record.get("channel") == delivery_channel
        ]
        if channel_deliveries:
            # Delivery occurrences stay atomic. A section that combines an
            # old occurrence with fresh text cannot be safely deduplicated:
            # dropping the old id would drop the fresh suffix too. Match the
            # aggregate string directly so multiline terminal rows retain
            # their identity as well.
            remaining = value
            for record in channel_deliveries:
                index = _find_rendered_block(remaining, record["text"])
                if index < 0:
                    continue
                prefix = remaining[:index].strip()
                if prefix:
                    sections.append({"channel": channel, "text": prefix})
                sections.append({
                    "channel": channel,
                    "text": record["text"],
                    "delivery_ids": [record["id"]],
                    **(
                        {"_bridge_seq": record["_bridge_seq"]}
                        if type(record.get("_bridge_seq")) is int else {}
                    ),
                })
                remaining = remaining[index + len(record["text"]):]
            suffix = remaining.strip()
            if suffix:
                sections.append({"channel": channel, "text": suffix})
        else:
            section = {"channel": channel, "text": value}
            ids = [record["id"] for record in channel_deliveries]
            if ids:
                section["delivery_ids"] = ids
            sections.append(section)
    return sections


def _merge_story_render_sections_by_bridge_sequence(
    sections: list[dict], additions: list[dict],
) -> list[dict]:
    """Insert late-observed sections at their original bridge position.

    A passive overlay snapshot can reach the handler after newer narration has
    already been formatted. Its bridge sequence is still authoritative, so do
    not append that row merely because the latest-screen merge observed it
    last. Sections without sequence provenance keep their existing order.
    """
    return merge_sections_by_bridge_sequence(
        sections, additions, join_story_text=_join_story_text)


def _render_story_section_plan(section_plan: list[dict]) -> str:
    """Render atomic chronology sections without spacing terminal rows out."""
    return render_sections(section_plan)


def _order_overlay_deliveries_by_sections(
    out: dict, sections: list[dict],
) -> None:
    """Keep private ownership records in their rendered occurrence order."""
    records = _overlay_delivery_records(out)
    if not records:
        return
    by_id = {record["id"]: record for record in records}
    ordered: list[dict] = []
    seen: set[int] = set()
    for section in sections:
        for delivery_id in section.get("delivery_ids", []):
            record = by_id.get(delivery_id)
            if record is not None and delivery_id not in seen:
                ordered.append(record)
                seen.add(delivery_id)
    ordered.extend(record for record in records if record["id"] not in seen)
    out[_OVERLAY_DELIVERIES_KEY] = ordered


def _carry_overlay_deliveries_into(
    out: dict,
    deliveries: list[dict],
    *,
    as_list: bool,
) -> None:
    """Transfer specific overlay occurrences into a replacement output."""
    current = _overlay_delivery_records(out)
    current_ids = {record["id"] for record in current}
    carry = [record for record in deliveries if record["id"] not in current_ids]
    rows = [record["text"] for record in carry]
    existing = out.get("screen_text")
    existing_story = out.get("text")
    if rows:
        # Promotion replaces an older render with a later wait. If that wait
        # has story, these older rows happened before it. Preserve their API
        # channel and record the presentation order instead of folding screen
        # rows into narration.
        if isinstance(existing_story, str) and existing_story.strip():
            out[_SCREEN_TEXT_BEFORE_STORY_KEY] = True
        if isinstance(existing, list):
            out["screen_text"] = rows + existing
        elif isinstance(existing, str) and existing.strip():
            out["screen_text"] = "\n".join(rows) + "\n" + existing.lstrip("\n")
        elif as_list:
            out["screen_text"] = rows
        else:
            out["screen_text"] = "\n".join(rows)
    transferred = [
        {**record, "channel": "screen_text"}
        for record in carry
    ]
    _merge_overlay_delivery_records(out, transferred + current)


# Bound on occurrences held between decision points (a runaway log must not
# grow the session's memory without limit); the newest occurrences are kept.
_OVERLAY_PENDING_DELIVERY_LIMIT = 500


# Bound on printed callback lines a held overlay row may still be recognised
# as mirroring. Entries expire by presentation boundary; this only caps a
# single response that prints an implausible number of callbacks.
_PRESENTED_CALLBACK_LINE_LIMIT = 128


# One settle before believing a panel closed, so a scrape taken between two
# frames is not mistaken for the window closing.
_OVERLAY_CLOSE_CONFIRM_DELAY = 0.2


def _passive_overlay_rows(screen: dict | None) -> list[str]:
    """Non-empty registered-overlay rows carried by a screen snapshot."""
    if not isinstance(screen, dict):
        return []
    texts = screen.get("overlay_texts") or []
    return [line for line in (str(t).strip() for t in texts) if line]


def _passive_overlay_rows_by_screen(
    screen: dict | None,
) -> list[tuple[str, list[str]]]:
    """Return contributor-owned rows, including explicit empty panels."""
    if not isinstance(screen, dict):
        return []
    raw = screen.get("overlay_texts_by_screen")
    if not isinstance(raw, dict) or not raw:
        return []
    order = [str(tag) for tag in (screen.get("overlay_screens") or [])]
    order.extend(str(tag) for tag in raw if str(tag) not in order)
    contributors = []
    for tag in order:
        texts = raw.get(tag)
        if not isinstance(texts, list):
            continue
        rows = [line for line in (str(text).strip() for text in texts) if line]
        contributors.append((tag, rows))
    return contributors


def _passive_overlay_key(screen: dict | None) -> tuple[str, ...]:
    """Stable identity of the overlays that contributed a snapshot's rows.

    ``screens`` contains every scraped screen and changes when unrelated
    notifications, choices, or HUD panels appear.  New shims provide the
    registered overlays that actually contributed these rows; old shims omit
    the field and naturally share the empty fallback key, leaving the ordered
    content overlap to detect replacement.
    """
    if not isinstance(screen, dict):
        return ()
    generations = screen.get("overlay_generations") or {}
    if not isinstance(generations, dict):
        generations = {}
    return tuple(
        f"{tag}@{generations[tag]}" if tag in generations else str(tag)
        for tag in (screen.get("overlay_screens") or [])
    )


def _passive_overlay_retains_generation(screen: dict | None) -> bool:
    """Whether any contributor owns its close/reopen generation explicitly."""
    if not isinstance(screen, dict):
        return False
    contributors = set(screen.get("overlay_screens") or [])
    retained = set(screen.get("overlay_retained_screens") or [])
    return bool(contributors & retained)


def _passive_overlay_delta(previous: list[str], panel: list[str]) -> list[str]:
    """Return rows appended to an ordered, possibly rolling panel."""
    return passive_rows_delta(previous, panel)


def _book_passive_overlay_snapshot(
    ctx: Any,
    screen: dict | None,
    *,
    confirm_absent: bool = False,
) -> list[dict]:
    """Book a snapshot and return identified occurrences for its new rows.

    Delivery is based on ordered snapshot overlap rather than text membership.
    Repeated rows therefore remain distinct, while an append-only log costs
    each occurrence once.  A divergent snapshot starts a new panel generation,
    as a terminal clear/reset does.

    A snapshot that is a strict PREFIX of what the ledger already holds is a
    stale re-scrape of the same generation, not a rewrite: successive events
    may race with the bridge's latest screen, which serves whichever
    ``screen_content`` arrived last, so treating a short read as replacement
    would re-print the whole panel.  Such a snapshot books nothing and does
    not shrink the ledger; a genuine restart diverges from the old rows and
    is delivered from the divergence on.
    """
    bridge_seq = screen.get("_seq") if isinstance(screen, dict) else None

    def _delivery(
        row: str, row_seq: object = None, contributor: str | None = None,
    ) -> dict:
        ctx.overlay.delivery_serial += 1
        provenance = row_seq if type(row_seq) is int else bridge_seq
        return {
            "id": ctx.overlay.delivery_serial,
            "text": row,
            **({"_overlay_contributor": contributor} if contributor else {}),
            **({"_bridge_seq": provenance}
               if type(provenance) is int else {}),
        }

    raw_sequences = screen.get("passive_overlay_row_seqs_by_screen")
    sequences_by_screen = (
        raw_sequences if isinstance(raw_sequences, dict) else {}
    )
    raw_aggregate_sequences = screen.get("passive_overlay_row_seqs")
    aggregate_sequences = (
        raw_aggregate_sequences
        if isinstance(raw_aggregate_sequences, list) else []
    )

    def _deliver_delta(
        previous: list[str], rows: list[str], row_sequences: object,
        contributor: str | None = None,
    ) -> list[dict]:
        sequences = row_sequences if isinstance(row_sequences, list) else []
        return [
            _delivery(
                rows[index],
                sequences[index] if index < len(sequences) else None,
                contributor,
            )
            for index in passive_row_delta_indices(previous, rows)
        ]

    contributors = _passive_overlay_rows_by_screen(screen)
    panel = _passive_overlay_rows(screen)
    if not panel and not contributors:
        return []
    if contributors:
        generations = screen.get("overlay_generations") or {}
        if not isinstance(generations, dict):
            generations = {}
        active_tags = {tag for tag, _rows in contributors}
        current_retained = set(screen.get("overlay_retained_screens") or [])
        if ctx.overlay.schema_mode == "aggregate":
            # A running handler can outlive a shim replacement. The first
            # contributor-aware snapshot is a synchronization boundary: the
            # aggregate schema cannot tell us which contributor owned prior
            # rows, so replaying them would be less honest than seeding them.
            aggregate_previous = list(ctx.overlay.text_snapshot)
            ctx.overlay.contributor_snapshots = {
                tag: list(rows) for tag, rows in contributors}
            ctx.overlay.contributor_keys = {
                tag: (f"{tag}@{generations[tag]}"
                      if tag in generations else tag)
                for tag, _rows in contributors
            }
            ctx.overlay.retained_contributors = {
                str(tag) for tag in current_retained if str(tag) in active_tags}
            ctx.overlay.text_snapshot = list(panel)
            ctx.overlay.screen_key = _passive_overlay_key(screen)
            ctx.overlay.retain_generation = bool(
                ctx.overlay.retained_contributors)
            ctx.overlay.schema_mode = "contributors"
            return _deliver_delta(
                aggregate_previous, panel, aggregate_sequences)
        ctx.overlay.schema_mode = "contributors"
        missing_tags = {
            tag for tag in ctx.overlay.contributor_snapshots
            if tag not in active_tags
            and tag not in ctx.overlay.retained_contributors
        }
        deliveries = []
        for tag, rows in contributors:
            key = f"{tag}@{generations[tag]}" if tag in generations else tag
            prior_key = ctx.overlay.contributor_keys.get(tag)
            previous = (
                ctx.overlay.contributor_snapshots.get(tag, [])
                if prior_key == key
                else []
            )
            if (
                not rows
                and prior_key == key
                and tag in current_retained
            ):
                continue
            if rows and len(rows) < len(previous) and previous[:len(rows)] == rows:
                continue
            deliveries.extend(_deliver_delta(
                previous,
                rows,
                sequences_by_screen.get(tag),
                tag,
            ))
            ctx.overlay.contributor_snapshots[tag] = list(rows)
            ctx.overlay.contributor_keys[tag] = key
        ctx.overlay.retained_contributors.difference_update(active_tags)
        ctx.overlay.retained_contributors.update(
            str(tag) for tag in current_retained if str(tag) in active_tags)
        ctx.overlay.text_snapshot = list(panel)
        ctx.overlay.screen_key = _passive_overlay_key(screen)
        ctx.overlay.retain_generation = bool(
            ctx.overlay.retained_contributors)
        if confirm_absent and missing_tags:
            confirmed = _confirm_passive_overlay_closed(ctx)
            if confirmed is None:
                confirmed_active: set[str] = set()
            elif confirmed is _OVERLAY_CLOSE_UNKNOWN:
                confirmed_active = set(ctx.overlay.contributor_snapshots)
            else:
                confirmed_active = {
                    tag for tag, _rows in
                    _passive_overlay_rows_by_screen(confirmed)
                }
                deliveries.extend(_book_passive_overlay_snapshot(
                    ctx, confirmed))
            for tag in missing_tags - confirmed_active:
                ctx.overlay.contributor_snapshots.pop(tag, None)
                ctx.overlay.contributor_keys.pop(tag, None)
        return deliveries
    if ctx.overlay.schema_mode == "contributors":
        # The first legacy aggregate snapshot after a schema downgrade cannot
        # be apportioned safely. Seed it and let later aggregate deltas carry
        # news, avoiding replay of every contributor-owned row.
        aggregate_previous = list(ctx.overlay.text_snapshot)
        ctx.overlay.contributor_snapshots = {}
        ctx.overlay.contributor_keys = {}
        ctx.overlay.retained_contributors = set()
        ctx.overlay.text_snapshot = list(panel)
        ctx.overlay.screen_key = _passive_overlay_key(screen)
        ctx.overlay.retain_generation = _passive_overlay_retains_generation(
            screen)
        ctx.overlay.schema_mode = "aggregate"
        return _deliver_delta(
            aggregate_previous, panel, aggregate_sequences)
    ctx.overlay.schema_mode = "aggregate"
    screen_key = _passive_overlay_key(screen)
    previous = (
        ctx.overlay.text_snapshot
        if screen_key == ctx.overlay.screen_key
        else []
    )
    if len(panel) < len(previous) and previous[:len(panel)] == panel:
        return []
    deliveries = _deliver_delta(previous, panel, aggregate_sequences)
    ctx.overlay.text_snapshot = list(panel)
    ctx.overlay.screen_key = screen_key
    ctx.overlay.retain_generation = _passive_overlay_retains_generation(screen)
    return deliveries


def _end_passive_overlay_generation(ctx: Any) -> None:
    """Close the current panel generation; reopening redelivers its rows."""
    ctx.overlay.text_snapshot = []
    ctx.overlay.screen_key = ()
    ctx.overlay.retain_generation = False
    ctx.overlay.contributor_snapshots = {}
    ctx.overlay.contributor_keys = {}
    ctx.overlay.retained_contributors = set()
    ctx.overlay.schema_mode = ""


def _close_absent_overlay_contributors(ctx: Any) -> None:
    """Close non-retained contributors while preserving retained ledgers."""
    for tag in list(ctx.overlay.contributor_snapshots):
        if tag not in ctx.overlay.retained_contributors:
            ctx.overlay.contributor_snapshots.pop(tag, None)
            ctx.overlay.contributor_keys.pop(tag, None)
    if not ctx.overlay.contributor_snapshots:
        _end_passive_overlay_generation(ctx)
        return
    ctx.overlay.text_snapshot = [
        row
        for rows in ctx.overlay.contributor_snapshots.values()
        for row in rows
    ]
    ctx.overlay.screen_key = tuple(
        ctx.overlay.contributor_keys.values())
    ctx.overlay.retain_generation = True


def _hold_passive_overlay_deliveries(
    ctx: Any, deliveries: list[dict],
) -> None:
    if not deliveries:
        return
    with ctx.overlay.lock:
        hold_pending_deliveries(
            ctx.overlay.pending_deliveries,
            ctx.overlay.durable_receipts,
            ctx.overlay.provisional_deliveries,
            ctx.overlay.recovered_occurrences,
            deliveries,
            _OVERLAY_PENDING_DELIVERY_LIMIT,
        )


def _claim_passive_overlay_deliveries(ctx: Any) -> list[dict]:
    """Atomically transfer ownership of deferred rows to one public call."""
    with ctx.overlay.lock:
        claimed = ctx.overlay.pending_deliveries
        ctx.overlay.pending_deliveries = []
    return claimed


def _remember_presented_callback_lines(
    ctx: Any, callback_occurrences: dict[str, list[dict]],
) -> None:
    """Remember callback lines printed without an overlay row to mirror them.

    ``_book_drained_overlay_events_locked`` pairs a drained overlay row with
    the character callback of the same occurrence and transfers the overlay
    identity onto the callback, so the line prints once.  That matching is
    per-response: an overlay row observed by the look-ahead instead of the
    drain is fenced behind the cursor and flushes on a later call, where it
    reads as a brand new terminal line.  The callbacks left unpaired here are
    exactly the ones such a held row can still mirror.
    """
    for line, candidates in callback_occurrences.items():
        for candidate in candidates:
            if candidate.get("overlay_delivery_id") is not None:
                continue
            if candidate.get("passive_overlay_snapshot"):
                continue
            candidate_seq = candidate.get("_seq")
            ctx.overlay.presented_callback_lines.append({
                "line": line,
                "seq": candidate_seq if type(candidate_seq) is int else None,
                "aged": False,
            })
    overflow = (
        len(ctx.overlay.presented_callback_lines) - _PRESENTED_CALLBACK_LINE_LIMIT
    )
    if overflow > 0:
        del ctx.overlay.presented_callback_lines[:overflow]


def _claim_presented_callback_mirror(
    ctx: Any, record: dict,
) -> bool:
    """Consume the printed callback that a held overlay row merely mirrors."""
    text = record.get("text")
    if not text:
        return False
    record_seq = record.get("_bridge_seq")
    for index, entry in enumerate(ctx.overlay.presented_callback_lines):
        if entry["line"] != text:
            continue
        entry_seq = entry["seq"]
        if (
            type(entry_seq) is int
            and type(record_seq) is int
            and entry_seq > record_seq
        ):
            # A callback printed after this row is a different occurrence,
            # exactly as in the in-batch matcher.
            continue
        del ctx.overlay.presented_callback_lines[index]
        return True
    return False


def _age_presented_callback_lines(ctx: Any) -> None:
    """Retire mirror memory one presentation boundary after it was printed.

    A held row mirrors the callback of the response that printed it or of the
    one immediately before; beyond that the terminal is legitimately repeating
    itself, and repeating a line is the failure this layer accepts.  Entries
    are recorded before their own response's flush, survive it, and are
    dropped at the next one.
    """
    remaining = []
    for entry in ctx.overlay.presented_callback_lines:
        if entry["aged"]:
            continue
        entry["aged"] = True
        remaining.append(entry)
    ctx.overlay.presented_callback_lines = remaining


def _book_durable_passive_overlay_delta(
    ctx: Any, screen: dict, *, authoritative_drain: bool = False,
) -> list[dict] | None:
    """Book a bridge-authored delta, or return None for legacy snapshots."""
    durable_delta = screen.get("passive_overlay_delta")
    if not isinstance(durable_delta, list):
        return None
    screen_key = _passive_overlay_key(screen)
    previous_schema_mode = ctx.overlay.schema_mode
    previous_screen_key = ctx.overlay.screen_key
    previous_contributor_keys = dict(ctx.overlay.contributor_keys)
    had_baseline = bool(
        previous_schema_mode
        and (ctx.overlay.text_snapshot or ctx.overlay.contributor_snapshots)
    )
    # Always synchronize from the full panel. The returned local delta is
    # normally redundant with the bridge delta. A persistent handler can,
    # however, miss one durable event while another command is confirming.
    # Per-row bridge provenance lets the next cumulative snapshot recover that
    # older occurrence without making a fresh/one-shot handler replay history.
    local_delta = _book_passive_overlay_snapshot(ctx, screen)
    source_id = str(screen.get("_source_id") or "")
    source_seq = str(
        screen.get("_source_seq")
        if screen.get("_source_seq") is not None
        else screen.get("_seq", "")
    )
    event_seq = screen.get("_seq")
    sequenced = type(event_seq) is int
    fresh = []
    durable_occurrences = {}

    def _claim_held(receipt: tuple) -> dict | None:
        if not authoritative_drain:
            return None
        for index, record in enumerate(ctx.overlay.pending_deliveries):
            if record.get("_durable_receipt") == receipt:
                record = ctx.overlay.pending_deliveries.pop(index)
                if _claim_presented_callback_mirror(ctx, record):
                    return None
                for key in ("_cursor_fenced", "_cursor_fenced_poll_serial",
                            "_cursor_fenced_source_id", "_cursor_fenced_source_seq"):
                    record.pop(key, None)
                return record
        return None

    def _claim_provisional(row: str, row_seq: object) -> dict | None:
        for index, record in enumerate(ctx.overlay.provisional_deliveries):
            if record.get("text") != row:
                continue
            provisional_seq = record.get("_bridge_seq")
            if type(row_seq) is int and type(provisional_seq) is int:
                if provisional_seq != row_seq:
                    continue
            elif record.get("screen_key") != screen_key:
                continue
            return ctx.overlay.provisional_deliveries.pop(index)
        return None

    for row_index, value in enumerate(durable_delta):
        row = str(value).strip()
        if not row:
            continue
        occurrence_key = (event_seq, row)
        occurrence = durable_occurrences.get(occurrence_key, 0)
        durable_occurrences[occurrence_key] = occurrence + 1
        receipt = (source_id, source_seq, row_index)
        if not register_receipt(ctx.overlay.durable_receipts, receipt):
            # A live-screen read may have booked this row without rendering
            # it. Its ordered drain now owns delivery, not the older fence.
            held = _claim_held(receipt)
            if held is not None:
                fresh.append(held)
            continue
        recovered_key = (event_seq, row, occurrence)
        if sequenced and recovered_key in ctx.overlay.recovered_occurrences:
            ctx.overlay.recovered_occurrences.pop(recovered_key, None)
            for pending in ctx.overlay.pending_deliveries:
                if pending.get("_recovered_occurrence") == recovered_key:
                    pending.pop("_recovered_occurrence", None)
                    pending["_durable_receipt"] = receipt
                    break
            held = _claim_held(receipt)
            if held is not None:
                fresh.append(held)
            continue
        provisional = _claim_provisional(row, event_seq)
        if provisional is not None:
            # The latest-screen occurrence may still be fenced in the pending
            # queue. Transfer durable ownership onto that exact occurrence so
            # a later queue eviction can release the receipt for replay.
            provisional_id = provisional.get("id")
            for pending in ctx.overlay.pending_deliveries:
                if pending.get("id") == provisional_id:
                    pending["_durable_receipt"] = receipt
                    break
            held = _claim_held(receipt)
            if held is not None:
                fresh.append(held)
            continue
        if sequenced:
            # Negative IDs occupy a separate namespace from local positive
            # delivery serials and remain stable across replayed reads.
            delivery_id = -(event_seq * 10000 + row_index + 1)
        else:
            ctx.overlay.delivery_serial += 1
            delivery_id = ctx.overlay.delivery_serial
        fresh.append({
            "id": delivery_id,
            "text": row,
            "_durable_receipt": receipt,
            **({"_bridge_seq": event_seq} if sequenced else {}),
        })
    if had_baseline and sequenced and local_delta:
        local_occurrences = {}
        for record in local_delta:
            row_seq = record.get("_bridge_seq")
            if type(row_seq) is not int:
                continue
            contributor = record.get("_overlay_contributor")
            if contributor:
                generations = screen.get("overlay_generations") or {}
                if not isinstance(generations, dict):
                    generations = {}
                current_key = (
                    f"{contributor}@{generations[contributor]}"
                    if contributor in generations else contributor
                )
                if previous_contributor_keys.get(contributor) != current_key:
                    continue
            elif (
                previous_schema_mode != "aggregate"
                or previous_screen_key != screen_key
            ):
                continue
            key = (row_seq, record["text"])
            occurrence = local_occurrences.get(key, 0)
            local_occurrences[key] = occurrence + 1
            if occurrence < durable_occurrences.get(key, 0):
                continue
            if _claim_provisional(record["text"], row_seq) is not None:
                continue
            recovered_key = (row_seq, record["text"], occurrence)
            ctx.overlay.recovered_occurrences[recovered_key] = None
            record["_recovered_occurrence"] = recovered_key
            fresh.append(record)
        if fresh and all(type(record.get("_bridge_seq")) is int for record in fresh):
            fresh.sort(key=lambda record: record["_bridge_seq"])
    trim_oldest(
        ctx.overlay.durable_receipts,
        limit=4096,
        protected={
            record.get("_durable_receipt")
            for record in ctx.overlay.pending_deliveries
            if isinstance(record.get("_durable_receipt"), tuple)
        },
    )
    trim_oldest(
        ctx.overlay.recovered_occurrences,
        limit=4096,
        protected={
            record.get("_recovered_occurrence")
            for record in ctx.overlay.pending_deliveries
            if isinstance(record.get("_recovered_occurrence"), tuple)
        },
    )
    return fresh


def _remember_provisional_overlay_deliveries(
    ctx: Any,
    records: list[dict],
    screen: dict,
) -> None:
    """Remember rows observed by latest-screen look-ahead before the cursor."""
    screen_key = _passive_overlay_key(screen)
    ctx.overlay.provisional_deliveries.extend({
        "id": record["id"],
        "text": record["text"],
        "screen_key": screen_key,
        **(
            {"_bridge_seq": record["_bridge_seq"]}
            if type(record.get("_bridge_seq")) is int else {}
        ),
    } for record in records)
    _trim_provisional_overlay_ownership(
        ctx, incoming_ids={record.get("id") for record in records})


def _trim_provisional_overlay_ownership(
    ctx: Any,
    *,
    incoming_ids: set[object] | None = None,
) -> None:
    """Bound provisional claims while retaining pending/in-flight owners."""
    trim_provisional_deliveries(
        ctx.overlay.provisional_deliveries,
        limit=500,
        protected_ids={
            record.get("id")
            for record in ctx.overlay.pending_deliveries
        } | (incoming_ids or set()),
    )


def _passive_overlay_ahead_of_presentation(
    ctx: Any, bridge_seq: object,
) -> bool:
    """Return whether a latest-state row is ahead of visible chronology.

    ``GameClient.cursor`` is a fetch high-water mark: command polling may
    advance it while preserving older rows in ``_prefetched_events`` for the
    next visible wait.  A live ``/screen`` sample must not leapfrog that
    backlog merely because the network cursor has crossed its sequence.
    Cursor zero is likewise an unknown/fresh timeline, not proof that a
    positive-sequence row is ready to present.
    """
    if type(bridge_seq) is not int:
        return False
    cursor = getattr(ctx.client, "cursor", None)
    if type(cursor) is not int or cursor <= 0 or bridge_seq > cursor:
        return True
    for event in list(getattr(ctx.client, "_prefetched_events", []) or []):
        if not isinstance(event, dict):
            continue
        event_seq = event.get("_seq")
        if type(event_seq) is int and event_seq <= bridge_seq:
            return True
        if type(event_seq) is not int and event.get("type") in {
            "dialogue", "narration", "screen_text", "auto_skipped",
        }:
            # An unsequenced visible row cannot be proven newer. Preserve the
            # duplicate-side bias until the ordinary lane consumes it.
            return True
    return False


def _passive_overlay_fence_still_active(
    ctx: Any,
    record: dict,
    *,
    release_owner_fences: bool = True,
) -> bool:
    """Keep a look-ahead row behind known or not-yet-polled chronology."""
    bridge_seq = record.get("_bridge_seq")
    if type(bridge_seq) is not int:
        return False
    if not release_owner_fences:
        # Internal settle results may be promoted, replaced, or discarded.
        # A cursor-fenced occurrence can leave the ledger only at the
        # serialized public boundary where its destination is final.
        return True
    for event in list(getattr(ctx.client, "_prefetched_events", []) or []):
        if not isinstance(event, dict):
            continue
        event_seq = event.get("_seq")
        if type(event_seq) is int and event_seq <= bridge_seq:
            return True
        if type(event_seq) is not int and event.get("type") in {
            "dialogue", "narration", "screen_text", "auto_skipped",
        }:
            return True
    source_id = record.get("_cursor_fenced_source_id")
    source_seq = record.get("_cursor_fenced_source_seq")
    source_position_unseen = bool(
        isinstance(source_id, str)
        and source_id
        and type(source_seq) is int
        and source_seq > ctx.overlay.timeline_source_sequences.get(source_id, 0)
    )
    cursor = getattr(ctx.client, "cursor", None)
    if (
        not source_position_unseen
        and type(cursor) is int
        and cursor > 0
        and bridge_seq <= cursor
    ):
        # The ordinary lane has reached this row's chronology.
        return False
    fenced_poll = record.get("_cursor_fenced_poll_serial")
    current_poll = getattr(ctx.client, "_state_poll_serial", None)
    if (
        type(fenced_poll) is int
        and type(current_poll) is int
        and current_poll > fenced_poll
    ):
        # A later successful ordinary poll found no predecessor to retain.
        # This is the bounded escape for a durable screen event that was
        # pruned or otherwise absent from the transcript.  The presentation
        # lane admits one public call per context, so "later poll" and "later
        # call" cannot disagree here: every poll this fence can observe was
        # either taken by the call that fenced the row -- which reaches this
        # branch only at its own serialized flush, where its destination is
        # final -- or by a call that started after that one returned.
        return False
    return True


def _fence_latest_passive_overlay_deliveries(
    ctx: Any, records: list[dict], screen: dict,
) -> None:
    """Mark latest-state rows that are not yet safe to present."""
    screen_source_id = str(screen.get("_source_id") or "")
    screen_source_seq = screen.get("_source_seq")
    source_position_unseen = bool(
        screen_source_id
        and type(screen_source_seq) is int
        and screen_source_seq > ctx.overlay.timeline_source_sequences.get(
            screen_source_id, 0)
    )
    for record in records:
        record_seq = record.get("_bridge_seq")
        if not (
            source_position_unseen
            or _passive_overlay_ahead_of_presentation(ctx, record_seq)
        ):
            continue
        record["_cursor_fenced"] = True
        record["_cursor_fenced_poll_serial"] = getattr(
            ctx.client, "_state_poll_serial", 0)
        if source_position_unseen:
            record["_cursor_fenced_source_id"] = screen_source_id
            record["_cursor_fenced_source_seq"] = screen_source_seq


def _book_drained_overlay_events(
    ctx: Any, result: object,
) -> list[dict]:
    """Book a drained batch under the context's occurrence-ledger lock."""
    with ctx.overlay.lock:
        return _book_drained_overlay_events_locked(ctx, result)


def _book_drained_overlay_events_locked(
    ctx: Any, result: object,
) -> list[dict]:
    """Turn drained overlay deltas into chronologically placed story events.

    The bridge retains changed passive ``screen_content`` snapshots in its
    sequenced stream while keeping ordinary screen state latest-only. This
    books those snapshots through the same ledger.  Fresh rows replace their
    source snapshot with a synthetic ``screen_text`` event in the same list
    position.  That keeps terminal output between the narration/dialogue that
    actually surrounded it instead of appending the whole panel at the end of
    the formatted response.

    Return identified occurrences owned by this response's text channel, so a
    later wait-output promotion can transfer them without matching strings.
    """
    events = getattr(result, "events", None)
    if not isinstance(events, list):
        return []
    inline_with_story = any(
        isinstance(event, dict)
        and event.get("type") in {"dialogue", "narration", "screen_text"}
        and not event.get("passive_overlay_snapshot")
        for event in events
    )
    transaction = getattr(result, "transaction", None)
    transaction = transaction if isinstance(transaction, dict) else {}
    transaction_action_id = transaction.get("action_id")
    transaction_source_id = transaction.get("_source_id")
    transaction_source_after = transaction.get("_source_seq")

    def callback_line(event: dict) -> str | None:
        if event.get("type") == "dialogue":
            who = event.get("character") or event.get("who") or "Narrator"
            text = _display_text(event.get("text") or event.get("what", ""))
            prefix = "[user] " if event.get("user_initiated") else ""
            return "{}[{}] {}".format(prefix, who, text)
        if event.get("type") == "narration":
            text = _display_text(event.get("text", ""))
            return text if text.strip() else None
        return None

    def belongs_to_transaction(event: dict) -> bool:
        if event.get("action_id") == transaction_action_id:
            return transaction_action_id is not None
        source_seq = event.get("_source_seq")
        return bool(
            not event.get("action_id")
            and transaction_source_id
            and event.get("_source_id") == transaction_source_id
            and type(transaction_source_after) is int
            and type(source_seq) is int
            and source_seq > transaction_source_after
        )

    callback_occurrences: dict[str, list[dict]] = {}
    for candidate in events:
        if not isinstance(candidate, dict) or not belongs_to_transaction(candidate):
            continue
        line = callback_line(candidate)
        if line:
            callback_occurrences.setdefault(line, []).append(candidate)

    rewritten = []
    delivered = []
    relocated_overlay_ids: set[int] = set()
    for event in events:
        if not isinstance(event, dict):
            rewritten.append(event)
            continue
        event_seq = event.get("_seq")
        sequenced = type(event_seq) is int
        if event.get("type") in {"game_started", "game_resumed"}:
            # Scoped transaction reads and the ordinary cursor are merged by
            # the client. A newly read ordinary batch can therefore contain a
            # lifecycle marker older than overlay rows already processed in a
            # preceding settle read. Do not let that stale marker erase the
            # occurrence receipts and replay cumulative history.
            if not sequenced or event_seq >= ctx.overlay.last_bridge_seq:
                _end_passive_overlay_generation(ctx)
                ctx.overlay.baseline()
                if sequenced:
                    ctx.overlay.last_bridge_seq = event_seq
            rewritten.append(event)
            continue
        if event.get("type") != "screen_content" or event.get("overlay_active"):
            rewritten.append(event)
            continue
        if sequenced:
            ctx.overlay.last_bridge_seq = max(
                ctx.overlay.last_bridge_seq, event_seq)
        has_rows = bool(_passive_overlay_rows(event))
        has_contributors = bool(_passive_overlay_rows_by_screen(event))
        has_durable_delta = isinstance(
            event.get("passive_overlay_delta"), list)
        if not event.get("passive_overlay_snapshot") and not has_rows:
            rewritten.append(event)
            continue
        if not has_rows and not has_contributors:
            if ctx.overlay.contributor_snapshots:
                _close_absent_overlay_contributors(ctx)
            elif not ctx.overlay.retain_generation:
                _end_passive_overlay_generation(ctx)
            continue
        if has_durable_delta:
            # The bridge computed this delta before retaining the cumulative
            # snapshot. Synchronize the local ledger from the full panel, but
            # render only its durable rows. This keeps one-shot CLI/MCP
            # processes from replaying history merely because their
            # HandlerContext started empty.
            fresh = _book_durable_passive_overlay_delta(
                ctx, event, authoritative_drain=True) or []
        else:
            fresh = _book_passive_overlay_snapshot(ctx, event)
        if not fresh:
            continue
        if not inline_with_story:
            _hold_passive_overlay_deliveries(ctx, fresh)
            continue
        for record in fresh:
            candidates = callback_occurrences.get(record["text"], [])
            callback = None
            while candidates:
                candidate = candidates[0]
                candidate_seq = candidate.get("_seq")
                record_seq = record.get("_bridge_seq")
                if (
                    type(candidate_seq) is int
                    and type(record_seq) is int
                    and candidate_seq > record_seq
                ):
                    # A later identical callback is a different occurrence;
                    # leave it available for the later screen row.
                    break
                candidates.pop(0)
                if "overlay_delivery_id" not in candidate:
                    callback = candidate
                    break
            if callback is not None:
                # The same visible occurrence can arrive through both the say
                # callback and a passive screen scrape. Keep the callback at
                # its original chronological position, but transfer the
                # overlay occurrence identity to it so the cumulative screen
                # channel does not print the row a second time.
                callback["overlay_delivery_id"] = record["id"]
                callback["passive_overlay_snapshot"] = True
                continue
            synthetic = {
                "type": "screen_text",
                "texts": [record["text"]],
                "overlay_delivery_ids": [record["id"]],
                "passive_overlay_snapshot": True,
            }
            if type(record.get("_bridge_seq")) is int:
                synthetic["_seq"] = record["_bridge_seq"]
            elif "_seq" in event:
                synthetic["_seq"] = event["_seq"]
            rewritten.append(synthetic)
            if (
                type(record.get("_bridge_seq")) is int
                and record.get("_bridge_seq") != event.get("_seq")
            ):
                relocated_overlay_ids.add(id(synthetic))
        for record in fresh:
            public_record = {
                key: value for key, value in record.items()
                if key not in _OVERLAY_LEDGER_RECORD_KEYS
            }
            public_record["channel"] = "story"
            delivered.append(public_record)
    # Whatever is still queued here was printed as a callback with no overlay
    # row of its own. A look-ahead row of the same occurrence is held behind
    # the cursor and would otherwise reappear as a fresh terminal line on the
    # next call.
    _remember_presented_callback_lines(ctx, callback_occurrences)
    sequenced_overlays = []
    greatest_prior_seq: int | None = None
    for event in rewritten:
        event_seq = event.get("_seq") if isinstance(event, dict) else None
        if (
            isinstance(event, dict)
            and event.get("passive_overlay_snapshot")
            and type(event_seq) is int
            and (
                id(event) in relocated_overlay_ids
                or (
                    greatest_prior_seq is not None
                    and greatest_prior_seq > event_seq
                )
            )
        ):
            sequenced_overlays.append(event)
        if type(event_seq) is int:
            greatest_prior_seq = max(
                event_seq,
                greatest_prior_seq if greatest_prior_seq is not None else event_seq,
            )
    if sequenced_overlays:
        sequenced_overlay_ids = {id(event) for event in sequenced_overlays}
        rewritten = [
            event for event in rewritten
            if id(event) not in sequenced_overlay_ids]
        for overlay in sorted(
            sequenced_overlays, key=lambda item: item["_seq"],
        ):
            insert_at = len(rewritten)
            for index, existing in enumerate(rewritten):
                existing_seq = (
                    existing.get("_seq") if isinstance(existing, dict) else None
                )
                if type(existing_seq) is int and existing_seq > overlay["_seq"]:
                    insert_at = index
                    break
            rewritten.insert(insert_at, overlay)
    events[:] = rewritten
    return delivered


_OVERLAY_CLOSE_UNKNOWN = object()


def _confirm_passive_overlay_closed(
    ctx: Any, *, deadline: float | None = None,
) -> dict | None | object:
    """Re-scrape once at a boundary that shows no overlay.

    Returns the live snapshot when the panel is still up, None when a usable
    empty snapshot confirms closure, or a sentinel when the check failed and
    the existing generation must be retained.
    """
    remaining = deadline - time.time() if deadline is not None else 2.2
    if remaining <= 0:
        return _OVERLAY_CLOSE_UNKNOWN
    time.sleep(min(_OVERLAY_CLOSE_CONFIRM_DELAY, remaining))
    remaining = deadline - time.time() if deadline is not None else 2.0
    if remaining <= 0:
        return _OVERLAY_CLOSE_UNKNOWN
    try:
        screen = _get_screen(ctx, timeout=min(2.0, remaining))
    except Exception:
        return _OVERLAY_CLOSE_UNKNOWN
    if not isinstance(screen, dict) or screen.get("overlay_active"):
        return _OVERLAY_CLOSE_UNKNOWN
    if _passive_overlay_rows(screen) or _passive_overlay_rows_by_screen(screen):
        return screen
    return None


def _merge_passive_overlay_text(
    ctx: Any,
    out: dict,
    screen: dict | None = None,
    fmt: str = "text",
    deadline: float | None = None,
    sample_live: bool = True,
    release_owner_fences: bool | None = None,
) -> None:
    """Merge passive overlay output under one occurrence-ledger owner."""
    with ctx.overlay.lock:
        _merge_passive_overlay_text_locked(
            ctx, out, screen=screen, fmt=fmt, deadline=deadline,
            sample_live=sample_live,
            release_owner_fences=release_owner_fences,
        )


def _merge_passive_overlay_text_locked(
    ctx: Any,
    out: dict,
    screen: dict | None = None,
    fmt: str = "text",
    deadline: float | None = None,
    sample_live: bool = True,
    release_owner_fences: bool | None = None,
) -> None:
    """Deliver registered-overlay scrollback text no other channel carries.

    The shim reports the text of every mod-registered overlay screen in
    ``overlay_texts``, passive (non-blocking) registrations included --
    "the text channel and the input-blocking flag are deliberately
    independent" (vnflight.rpy).  build_state_data() reads that field only
    inside its ``if overlay:`` branch, and the shim raises ``overlay_active``
    for BLOCKING overlays only.  So a passive scrollback panel reached the
    agent through no channel at all before passive snapshots became drainable:
    its rows are not say/NVL dialogue, and the post-act rescue in
    _refresh_missing_screen_text_from_state() only fires after act(), and only
    when the act produced no text of its own.

    Echoes of Tomorrow's live terminal is exactly that shape.  Agents were
    choosing which of ECHO-7's scarce questions to spend without ever being
    shown what ECHO-7 said -- a bare wait() at the terminal returned the stats
    line and the option list and nothing else, and a line written after the
    last act() settled only surfaced an interaction later, if at all.

    Delivery is based on ordered snapshot overlap rather than text membership
    (see _book_passive_overlay_snapshot).  This snapshot is the DECISION-POINT
    view; rows printed and hidden since the previous decision point were
    already booked from drainable screen_content events and are flushed in the
    order they were seen, so each row is delivered exactly once whether the
    panel is still up or closed before the agent got a turn.

    An absent ordinary overlay ends a generation only when a fresh re-scrape
    confirms it: a Journal reopened on identical rows must render. A retained
    overlay instead supplies an explicit generation key; its ledger survives
    a live/choice layer handoff, while a clear/reset changes the key.
    """
    if release_owner_fences is None:
        release_owner_fences = _ACTIVE_PRESENTATION_INVOCATION.get() is None
    if not ctx.allow_live_overlay_lookahead:
        # One-shot callers cannot preserve provisional ownership into their
        # next process. Durable screen_content events remain booked through
        # _book_drained_overlay_events and flush from the pending ledger below.
        screen = None
        sample_live = False
    if sample_live and deadline is not None and time.time() >= deadline:
        sample_live = False
    if screen is None and sample_live:
        remaining = deadline - time.time() if deadline is not None else 2.0
        if remaining <= 0:
            sample_live = False
        else:
            try:
                screen = _get_screen(ctx, timeout=min(2.0, remaining))
            except Exception:
                screen = None
    fresh: list[dict] = []
    if not isinstance(screen, dict):
        # No usable view of the screen: never guess at a close.  Rows already
        # booked from samples are still news and are flushed below.
        pass
    elif screen.get("overlay_active"):
        # Blocking overlays render through _screen_texts already; leave both
        # the panel and the ledger to that path.
        pass
    elif _passive_overlay_rows(screen) or _passive_overlay_rows_by_screen(screen):
        screen_seq = screen.get("_seq")
        client_cursor = getattr(ctx.client, "cursor", None)
        screen_source_id = str(screen.get("_source_id") or "")
        screen_source_seq = screen.get("_source_seq")
        source_position_unseen = bool(
            screen_source_id
            and type(screen_source_seq) is int
            and screen_source_seq > ctx.overlay.timeline_source_sequences.get(
                screen_source_id, 0)
        )
        presentation_fenced = (
            source_position_unseen
            or _passive_overlay_ahead_of_presentation(ctx, screen_seq)
        )
        already_drained = bool(
            type(screen_seq) is int
            and type(client_cursor) is int
            and screen_seq <= client_cursor
            and not source_position_unseen
        )
        durable = _book_durable_passive_overlay_delta(ctx, screen)
        if already_drained and not presentation_fenced:
            # /screen is a latest-state cache, not a second event channel. If
            # the ordinary cursor has already passed this exact snapshot, its
            # durable event was the only authority allowed to deliver rows.
            # Synchronize the local ledger/receipts above, but do not turn a
            # stale cached panel into provisional output after a later scene.
            if durable is None:
                _book_passive_overlay_snapshot(ctx, screen)
        elif durable is None:
            fresh = _book_passive_overlay_snapshot(
                ctx, screen, confirm_absent=True)
            _remember_provisional_overlay_deliveries(ctx, fresh, screen)
        else:
            fresh = durable
        # These rows came from latest-screen look-ahead, not the current
        # scoped/ordinary drain. Preserve that ownership distinction for both
        # modern durable deltas and legacy cumulative snapshots.
        _fence_latest_passive_overlay_deliveries(ctx, fresh, screen)
    elif ctx.overlay.text_snapshot and (
        ctx.overlay.contributor_snapshots
        or not ctx.overlay.retain_generation
    ):
        confirmed = _confirm_passive_overlay_closed(ctx, deadline=deadline)
        if confirmed is _OVERLAY_CLOSE_UNKNOWN:
            pass
        elif confirmed is None:
            if ctx.overlay.contributor_snapshots:
                _close_absent_overlay_contributors(ctx)
            else:
                _end_passive_overlay_generation(ctx)
        else:
            # The panel outlived the boundary snapshot — and it may have
            # printed its last rows in the gap.
            durable = _book_durable_passive_overlay_delta(ctx, confirmed)
            if durable is None:
                fresh = _book_passive_overlay_snapshot(ctx, confirmed)
                _remember_provisional_overlay_deliveries(
                    ctx, fresh, confirmed)
            else:
                fresh = durable
            _fence_latest_passive_overlay_deliveries(ctx, fresh, confirmed)

    pending = _claim_passive_overlay_deliveries(ctx)
    # Object identity, not the delivery id: durable re-bookings can reuse a
    # sequence-derived id, and only these exact records were held.
    held_records = {id(record) for record in pending}
    if pending:
        fresh = pending + fresh
    # A latest-screen read can observe a passive row while older narration is
    # still waiting on the ordinary transcript lane.  Book that occurrence
    # now, but do not present it ahead of the bridge cursor: its durable
    # screen_content event will either reconcile the provisional record or
    # the cursor will cross its sequence on a later wait.  Rows drained by the
    # current transaction are not provisional and remain immediately
    # renderable even though scoped reads do not advance the ordinary cursor.
    deferred = [
        record for record in fresh
        if (
            record.get("_cursor_fenced")
            and _passive_overlay_fence_still_active(
                ctx,
                record,
                release_owner_fences=release_owner_fences,
            )
        )
    ]
    if deferred:
        deferred_ids = {record["id"] for record in deferred}
        fresh = [
            record for record in fresh
            if record.get("id") not in deferred_ids
        ]
        _hold_passive_overlay_deliveries(ctx, deferred)
    if held_records and ctx.overlay.presented_callback_lines:
        # A row that was held while its own occurrence printed as a character
        # callback is now becoming visible a call later. Apply the same
        # mirrored-overlay matching the drain applies in-batch, so the line
        # does not read as a new terminal row. Only rows released from the
        # hold queue are eligible, and each printed callback is claimed once:
        # anything this cannot pair is presented, duplicate over drop.
        mirrored = set()
        for record in fresh:
            if id(record) not in held_records:
                continue
            if _claim_presented_callback_mirror(ctx, record):
                mirrored.add(id(record))
        if mirrored:
            fresh = [
                record for record in fresh if id(record) not in mirrored
            ]
    if release_owner_fences:
        # This merge is a presentation boundary (the serialized public flush,
        # or a direct one-shot caller). Age the mirror memory here, after the
        # matching above has had its chance to use it.
        _age_presented_callback_lines(ctx)
    # Incoming markers were protected until the fence decision. Normalize a
    # second time against final pending ownership so a large immediately
    # rendered batch cannot bypass the unowned-marker bound.
    _trim_provisional_overlay_ownership(ctx)
    for record in fresh:
        for key in _OVERLAY_LEDGER_RECORD_KEYS:
            record.pop(key, None)
    if fresh and all(type(record.get("_bridge_seq")) is int for record in fresh):
        # Scoped transaction reads and ordinary cursor reads can observe the
        # same durable stream in different batches. The bridge sequence, not
        # HTTP completion order, is the presentation chronology.
        fresh.sort(key=lambda record: record["_bridge_seq"])
    if not fresh:
        return

    if str(out.get("text") or "").strip() == "(no new events)":
        # The event formatter ran before this late overlay flush. Once booked
        # rows become visible, its empty-batch placeholder is no longer true.
        out.pop("text", None)

    existing_screen = out.get("screen_text")
    deliver = fresh
    rendered_rows = [record["text"] for record in deliver]
    if fmt == "json":
        prior = existing_screen if isinstance(existing_screen, list) else []
        if rendered_rows:
            out["screen_text"] = list(prior) + rendered_rows
    elif fmt in ("text", "quiet"):
        if rendered_rows:
            rendered = "\n".join(rendered_rows)
            if isinstance(existing_screen, str) and existing_screen.strip():
                out["screen_text"] = existing_screen.rstrip() + "\n" + rendered
            else:
                out["screen_text"] = rendered
    records = [{**record, "channel": "screen_text"} for record in deliver]
    _merge_overlay_delivery_records(out, records)
    if out.get(_STORY_RENDER_SECTIONS_KEY):
        # Promotion may already have established A -> B -> C chronology.
        # Rows discovered at this final decision-point merge must extend that
        # plan; otherwise the renderer trusts the stale plan and hides them.
        sections = _story_render_sections(out)
        additions = [{
            "channel": "screen_text",
            "text": record["text"],
            "delivery_ids": [record["id"]],
            **(
                {"_bridge_seq": record["_bridge_seq"]}
                if type(record.get("_bridge_seq")) is int
                else (
                    {"_bridge_seq": screen["_seq"]}
                    if (
                        isinstance(screen, dict)
                        and type(screen.get("_seq")) is int
                    ) else {}
                )
            ),
        } for record in deliver]
        out[_STORY_RENDER_SECTIONS_KEY] = (
            _merge_story_render_sections_by_bridge_sequence(
                sections, additions)
        )


def _claim_prefetched_screen_text_snapshot(
    ctx: Any,
    screen: dict,
    rendered_text: str,
) -> None:
    """Retire the durable event already represented by a screen fallback.

    A screen-level action can expose its updated modal through ``/screen``
    before the normal event drain is composed. The command-result poll may
    already have parked the matching ``screen_text`` event in prefetch. Once
    the latest-state fallback renders that same occurrence, leaving the event
    queued makes a later plain wait replay the modal in an unrelated scene.

    Claim only the event immediately emitted from this exact source snapshot;
    text equality alone is not ownership because identical terminal rows can
    be legitimate later occurrences.
    """
    source_id = screen.get("_source_id")
    source_seq = screen.get("_source_seq")
    bridge_seq = screen.get("_seq")
    rendered_rows = [
        line.strip() for line in str(rendered_text or "").splitlines()
        if line.strip()
    ]
    if not rendered_rows:
        return

    receipts = ctx.overlay.rendered_screen_event_receipts
    expected_rows = tuple(rendered_rows)
    if source_id and type(source_seq) is int:
        receipts[("source", str(source_id), source_seq + 1)] = expected_rows
    if type(bridge_seq) is int:
        receipts[("bridge", "", bridge_seq + 1)] = expected_rows
    while len(receipts) > 4096:
        receipts.pop(next(iter(receipts)))

    prefetched = list(getattr(ctx.client, "_prefetched_events", []) or [])
    if not prefetched:
        return

    def _is_ordered_subset(rows: list[str], whole: list[str]) -> bool:
        position = 0
        for row in rows:
            try:
                position = whole.index(row, position) + 1
            except ValueError:
                return False
        return True

    remaining = []
    claimed = False
    for event in prefetched:
        if not isinstance(event, dict):
            remaining.append(event)
            continue
        same_source_snapshot = (
            event.get("type") == "screen_text"
            and (
                (
                    source_id
                    and event.get("_source_id") == source_id
                    and type(source_seq) is int
                    and event.get("_source_seq") == source_seq + 1
                )
                or (
                    type(bridge_seq) is int
                    and event.get("_seq") == bridge_seq + 1
                )
            )
        )
        event_texts = event.get("texts")
        if not isinstance(event_texts, (list, tuple)):
            remaining.append(event)
            continue
        event_rows = [
            str(value).strip() for value in event_texts
            if str(value).strip()
        ]
        if (
            not claimed
            and same_source_snapshot
            and event_rows
            and _is_ordered_subset(event_rows, rendered_rows)
        ):
            claimed = True
            continue
        remaining.append(event)
    if claimed:
        ActionDeliveryOwnership._retain_held_events(ctx.client, remaining)


def _drop_rendered_screen_occurrence_events(
    ctx: Any,
    result: object,
) -> None:
    """Drop durable screen events already rendered from the latest cache."""
    events = getattr(result, "events", None)
    receipts = ctx.overlay.rendered_screen_event_receipts
    if not isinstance(events, list) or not receipts:
        return

    def was_rendered(event: object) -> bool:
        if not isinstance(event, dict) or event.get("type") != "screen_text":
            return False
        event_texts = event.get("texts")
        if not isinstance(event_texts, (list, tuple)):
            return False
        event_rows = [
            str(value).strip() for value in event_texts if str(value).strip()
        ]
        if not event_rows:
            return False

        def matches(receipt: tuple[str, str, int]) -> bool:
            expected = receipts.get(receipt)
            if not expected:
                return False
            position = 0
            for row in event_rows:
                try:
                    position = expected.index(row, position) + 1
                except ValueError:
                    return False
            return True

        source_id = event.get("_source_id")
        source_seq = event.get("_source_seq")
        if (
            source_id
            and type(source_seq) is int
            and matches(("source", str(source_id), source_seq))
        ):
            return True
        bridge_seq = event.get("_seq")
        return (
            type(bridge_seq) is int
            and matches(("bridge", "", bridge_seq))
        )

    events[:] = [event for event in events if not was_rendered(event)]


def _screen_has_choice_buttons(screen: dict | None) -> bool:
    """Return True when raw /screen buttons include story choice actions."""
    for button in (screen or {}).get("buttons") or []:
        actions = button.get("actions") or []
        action_strs = button.get("action_strs") or ""
        if "ChoiceReturn" in actions or "ChoiceReturn" in str(action_strs):
            return True
    return False

